{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	// In this scenario, the client starts the server
	serverPath := "./bin/server"
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		// Fallback to go run if bin/server doesn't exist (for development/tests)
		serverPath = "go"
	}

	var cmd *exec.Cmd
	if serverPath == "go" {
		cmd = exec.CommandContext(ctx, "go", "run", "./cmd/server/main.go")
	} else {
		cmd = exec.CommandContext(ctx, serverPath)
	}

	transport := &mcp.CommandTransport{
		Command: cmd,
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer session.Close()

	if *listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		for _, content := range res.Content {
			if textContent, ok := content.(*mcp.TextContent); ok {
				fmt.Println(textContent.Text)
			}
		}
	}
}
","filename":"cmd/client/main.go"}

