{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type ClientApp struct {
	mcpClient *mcp.Client
}

func NewClientApp() *ClientApp {
	return &ClientApp{
		mcpClient: mcp.NewClient(&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		}, nil),
	}
}

func (c *ClientApp) Run(ctx context.Context, serverPath string, listTools bool, callTool string) error {
	var cmd *exec.Cmd
	if serverPath == "go" {
		cmd = exec.CommandContext(ctx, "go", "run", "../../cmd/server/main.go")
	} else {
		cmd = exec.CommandContext(ctx, serverPath)
	}

	transport := &mcp.CommandTransport{
		Command: cmd,
	}

	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range res.Content {
			if textContent, ok := content.(*mcp.TextContent); ok {
				fmt.Println(textContent.Text)
			}
		}
	}

	return nil
}

// ConnectUsingTransport allows testing with custom transports (like in-memory)
func (c *ClientApp) ConnectUsingTransport(ctx context.Context, transport mcp.Transport) (*mcp.ClientSession, error) {
	return c.mcpClient.Connect(ctx, transport, nil)
}
