{"content":"package client

import (
	"bytes"
	"context"
	"strings"
	"testing"

	"mcp-example/internal/server"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestRunClient_ListTools(t *testing.T) {
	ctx := context.Background()
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	s := server.NewServer()
	go func() {
		_, _ = s.Connect(ctx, serverTransport, nil)
	}()

	var stdout bytes.Buffer
	err := RunClient(ctx, clientTransport, true, "", &stdout)
	if err != nil {
		t.Fatalf("RunClient failed: %v", err)
	}

	if !strings.Contains(stdout.String(), "hello_world") {
		t.Errorf("Expected stdout to contain 'hello_world', got %q", stdout.String())
	}
}

func TestRunClient_CallTool(t *testing.T) {
	ctx := context.Background()
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	s := server.NewServer()
	go func() {
		_, _ = s.Connect(ctx, serverTransport, nil)
	}()

	var stdout bytes.Buffer
	err := RunClient(ctx, clientTransport, false, "hello_world", &stdout)
	if err != nil {
		t.Fatalf("RunClient failed: %v", err)
	}

	if !strings.Contains(stdout.String(), "Hello, MCP World!") {
		t.Errorf("Expected stdout to contain 'Hello, MCP World!', got %q", stdout.String())
	}
}
