{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type ClientApp struct {
	client *mcp.Client
	serverBin string
}

func NewClientApp(serverBin string) *ClientApp {
	return &ClientApp{
		client: mcp.NewClient(&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		}, nil),
		serverBin: serverBin,
	}
}

func (a *ClientApp) ListTools(ctx context.Context) ([]string, error) {
	transport := &mcp.CommandTransport{
		Command: exec.Command(a.serverBin),
	}

	session, err := a.client.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}
	defer session.Close()

	tools, err := session.ListTools(ctx, &mcp.ListToolsParams{})
	if err != nil {
		return nil, err
	}

	var names []string
	for _, tool := range tools.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

func (a *ClientApp) CallTool(ctx context.Context, toolName string) (string, error) {
	transport := &mcp.CommandTransport{
		Command: exec.Command(a.serverBin),
	}

	session, err := a.client.Connect(ctx, transport, nil)
	if err != nil {
		return "", err
	}
	defer session.Close()

	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name:      toolName,
		Arguments: map[string]any{},
	})
	if err != nil {
		return "", err
	}

	for _, content := range result.Content {
		if textPtr, ok := content.(*mcp.TextContent); ok {
			return textPtr.Text, nil
		}
	}
	return "", fmt.Errorf("no text content in result")
}
