{"content":"package client

import (
	"context"
	"fmt"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	Session *mcp.ClientSession
}

func NewClient(ctx context.Context, transport mcp.Transport) (*Client, error) {
	c := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-world-client",
		Version: "1.0.0",
	}, nil)

	session, err := c.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}

	return &Client{Session: session}, nil
}

func (c *Client) ListTools(ctx context.Context) error {
	res, err := c.Session.ListTools(ctx, &mcp.ListToolsParams{})
	if err != nil {
		return err
	}
	for _, tool := range res.Tools {
		fmt.Printf("- %s: %s\n", tool.Name, tool.Description)
	}
	return nil
}

func (c *Client) CallTool(ctx context.Context, name string) error {
	res, err := c.Session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return err
	}
	for _, content := range res.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			fmt.Println(text.Text)
		}
	}
	return nil
}

func (c *Client) Close() error {
	return c.Session.Close()
}
