{"filename":"pkg/client/client_test.go","new_content":"func TestClientApp(t *testing.T) {
	ctx := context.Background()

	// Create server and client apps
	s := server.NewHelloServer()
	c := NewClientApp()

	t1, t2 := mcp.NewInMemoryTransports()

	// Connect server
	if _, err := s.Connect(ctx, t1, nil); err != nil {
		t.Fatalf("Failed to connect server: %v", err)
	}

	// Connect client using transport
	session, err := c.ConnectUsingTransport(ctx, t2)
	if err != nil {
		t.Fatalf("Failed to connect client: %v", err)
	}
	defer session.Close()

	// Test ListTools functionality
	tools, err := session.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("Failed to list tools: %v", err)
	}
	if len(tools.Tools) == 0 {
		t.Errorf("Expected tools, got none")
	}

	// Test CallTool functionality
	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("Failed to call tool: %v", err)
	}

	found := false
	for _, content := range res.Content {
		if textContent, ok := content.(*mcp.TextContent); ok {
			if textContent.Text == "Hello, MCP World!" {
				found = true
				break
			}
		}
	}
	if !found {
		t.Errorf("Expected 'Hello, MCP World!' in response")
	}
}

func TestClientApp_Run(t *testing.T) {
	// This is a bit of an integration test
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	// Ensure the server binary exists
	cmd := exec.Command("go", "build", "-o", "../../bin/server", "../../cmd/server/main.go")
	if err := cmd.Run(); err != nil {
		t.Skipf("Skipping integration test: failed to build server: %v", err)
