	err := c.Run(ctx, "../../bin/server", true, "")
	if err != nil {
		t.Errorf("Run failed for listTools: %v", err)
	}

	// Test calling tool
	err = c.Run(ctx, "../../bin/server", false, "hello_world")
	if err != nil {
		t.Errorf("Run failed for callTool: %v", err)
	}
}
