func TestClient(t *testing.T) {
	ctx := context.Background()
	clientTransport, serverTransport := mcp.NewInMemoryTransports()

	s := mcp.NewServer(&mcp.Implementation{
		Name:    "test-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(s, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns 'Hello, MCP World!'",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				&mcp.TextContent{Text: "Hello, MCP World!"},
			},
		}, nil, nil
	})

	go func() {
		_, _ = s.Connect(ctx, serverTransport, nil)
	}()

	c, err := NewClient(ctx, clientTransport)
	if err != nil {
		t.Fatalf("Failed to create client: %v", err)
	}
	defer c.Close()

	// Test ListTools
	if err := c.ListTools(ctx); err != nil {
		t.Errorf("ListTools failed: %v", err)
	}

	// Test CallTool
	if err := c.CallTool(ctx, "hello_world"); err != nil {
		t.Errorf("CallTool failed: %v", err)
	}
}
