{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// ListTools lists all available tools from the session.
func ListTools(ctx context.Context, session *mcp.ClientSession) error {
	tools, err := session.ListTools(ctx, &mcp.ListToolsParams{})
	if err != nil {
		return err
	}
	for _, tool := range tools.Tools {
		fmt.Println(tool.Name)
	}
	return nil
}

// CallTool calls a tool by name and prints the response.
func CallTool(ctx context.Context, session *mcp.ClientSession, name string) error {
	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return err
	}
	for _, content := range res.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			fmt.Println(text.Text)
		}
	}
	return nil
}

// Run executes the client logic.
func Run(ctx context.Context, listTools bool, callTool string, serverPath string) error {
	mcpClient := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	transport := &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}

	session, err := mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	defer session.Close()

	if listTools {
		if err := ListTools(ctx, session); err != nil {
			return err
		}
	}

	if callTool != "" {
		if err := CallTool(ctx, session, callTool); err != nil {
			return err
		}
	}
	return nil
}
