import (
	"context"
	"flag"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func RunCLI() error {
	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		return nil
	}

	ctx := context.Background()
	transport := &mcp.CommandTransport{
		Command: exec.CommandContext(ctx, *serverPath),
	}

	c, err := NewClient(ctx, transport)
	if err != nil {
		return err
	}
	defer c.Close()

	if *listTools {
		if err := c.ListTools(ctx); err != nil {
			return err
		}
	}

	if *callTool != "" {
		if err := c.CallTool(ctx, *callTool); err != nil {
			return err
		}
	}
	return nil
}
