func TestClientApp(t *testing.T) {
	ctx := context.Background()
	t1, t2 := mcp.NewInMemoryTransports()

	// Setup server
	server := mcp.NewServer(&mcp.Implementation{Name: "test-server"}, nil)
	mcp.AddTool(server, &mcp.Tool{
		Name: "hello_world",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{&mcp.TextContent{Text: "Hello, MCP World!"}},
		}, nil, nil
	})

	go func() {
		if _, err := server.Connect(ctx, t1, nil); err != nil {
			panic(err)
		}
	}()

	// Setup client app
	app := NewClientApp(t2)

	t.Run("ListTools", func(t *testing.T) {
		tools, err := app.ListTools(ctx)
		if err != nil {
			t.Fatalf("ListTools failed: %v", err)
		}
		if len(tools) != 1 || tools[0] != "hello_world" {
			t.Errorf("unexpected tools: %v", tools)
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		text, err := app.CallTool(ctx, "hello_world")
		if err != nil {
			t.Fatalf("CallTool failed: %v", err)
		}
		if text != "Hello, MCP World!" {
			t.Errorf("expected 'Hello, MCP World!', got '%s'", text)
		}
	})
}
