func TestClientFunctions(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	server := hello.NewServer()
	client := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "1.0.0"}, nil)

	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	errCh := make(chan error, 1)
	go func() {
		errCh <- server.Run(ctx, serverTransport)
	}()

	session, err := client.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	t.Run("ListTools", func(t *testing.T) {
		err := ListTools(ctx, session)
		if err != nil {
			t.Errorf("ListTools failed: %v", err)
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		err := CallTool(ctx, session, "hello_world")
		if err != nil {
			t.Errorf("CallTool failed: %v", err)
		}
	})

	cancel()
	<-errCh
}

func TestRun(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Find the server binary.
	// We are in internal/client. bin/server is in ../../bin/server.
	wd, _ := os.Getwd()
	serverPath := filepath.Join(wd, "..", "..", "bin", "server")

	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		t.Skip("server binary not found, skipping TestRun")
	}

	t.Run("ListTools", func(t *testing.T) {
		err := Run(ctx, true, "", serverPath)
		if err != nil {
			t.Errorf("Run (list-tools) failed: %v", err)
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		err := Run(ctx, false, "hello_world", serverPath)
		if err != nil {
			t.Errorf("Run (call-tool) failed: %v", err)
		}
	})
}
