{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-world-client",
		Version: "1.0.0",
	}, nil)

	// In a real scenario, the client would start the server.
	// We'll use CommandTransport to start our own server binary.
	transport := &mcp.CommandTransport{
		Command: exec.Command("./bin/server"),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer session.Close()

	if *listTools {
		for tool, err := range session.Tools(ctx, nil) {
			if err != nil {
				log.Fatalf("Failed to list tools: %v", err)
			}
			fmt.Printf("- %s: %s\n", tool.Name, tool.Description)
		}
	}

	if *callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		for _, content := range res.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
}
","filename":"cmd/client/main.go"}

{"filename":"pkg/client/client.go","new_content":"type ClientApp struct {
	client    *mcp.Client
	transport mcp.Transport
	session   *mcp.ClientSession
}

func NewClientApp(transport mcp.Transport) *ClientApp {
	return &ClientApp{
		client: mcp.NewClient(&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		}, nil),
		transport: transport,
	}
}

func (a *ClientApp) connect(ctx context.Context) error {
	if a.session != nil {
		return nil
	}
	session, err := a.client.Connect(ctx, a.transport, nil)
	if err != nil {
		return err
	}
	a.session = session
	return nil
}

func (a *ClientApp) Close() error {
	if a.session != nil {
		return a.session.Close()
	}
	return nil
}

func (a *ClientApp) ListTools(ctx context.Context) ([]string, error) {
	if err := a.connect(ctx); err != nil {
		return nil, err
	}

	tools, err := a.session.ListTools(ctx, &mcp.ListToolsParams{})
	if err != nil {
		return nil, err
	}

	var names []string
	for _, tool := range tools.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

func (a *ClientApp) CallTool(ctx context.Context, toolName string) (string, error) {
	if err := a.connect(ctx); err != nil {
		return "", err
	}

	result, err := a.session.CallTool(ctx, &mcp.CallToolParams{
		Name:      toolName,
		Arguments: map[string]any{},
	})
	if err != nil {
		return "", err
	}

	for _, content := range result.Content {
		if textPtr, ok := content.(*mcp.TextContent); ok {
			return textPtr.Text, nil
		}
	}
	return "", fmt.Errorf("no text content in result")
}","old_content":"type ClientApp struct {
