func TestIntegration_Main(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	// Build binaries
	cmd := exec.Command("go", "build", "-o", "../../bin/server", "../../cmd/server/main.go")
	if err := cmd.Run(); err != nil {
		t.Fatalf("Failed to build server: %v", err)
	}
	cmd = exec.Command("go", "build", "-o", "../../bin/client", "../../cmd/client/main.go")
	if err := cmd.Run(); err != nil {
		t.Fatalf("Failed to build client: %v", err)
	}

	// Test client --list-tools
	cmd = exec.CommandContext(ctx, "../../bin/client", "--list-tools")
	output, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("Client --list-tools failed: %v\nOutput: %s", err, string(output))
	}
	if string(output) != "hello_world\n" {
		t.Errorf("Expected 'hello_world\\n', got %q", string(output))
	}

	// Test client --call-tool hello_world
	cmd = exec.CommandContext(ctx, "../../bin/client", "--call-tool", "hello_world")
	output, err = cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("Client --call-tool hello_world failed: %v\nOutput: %s", err, string(output))
