func run(args []string) error {
	fs := flag.NewFlagSet("client", flag.ContinueOnError)
	listTools := fs.Bool("list-tools", false, "List available tools")
	callTool := fs.String("call-tool", "", "Call a tool by name")
	if err := fs.Parse(args); err != nil {
		return err
	}

	if !*listTools && *callTool == "" {
		fs.Usage()
		return flag.ErrHelp
	}

	ctx := context.Background()
	app := client.NewClientApp()

	serverPath := "./bin/server"
	command := serverPath
	var cmdArgs []string
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		command = "go"
		cmdArgs = []string{"run", "./cmd/server/main.go"}
	}

	return app.Run(ctx, *listTools, *callTool, command, cmdArgs...)
}
