{"content":"package server

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldTool(t *testing.T) {
	ctx := context.Background()
	s := NewHelloWorldServer()

	t1, t2 := mcp.NewInMemoryTransports()

	// Start server on t1
	go func() {
		if err := s.Connect(ctx, t1, nil); err != nil {
			// In test, we can't really log.Fatal if it fails in a goroutine easily without affecting the test
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)
	session, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("Failed to call tool: %v", err)
	}

	if len(res.Content) != 1 {
		t.Fatalf("Expected 1 content item, got %d", len(res.Content))
	}

	textContent, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", res.Content[0])
	}

	expected := "Hello, MCP World!"
	if textContent.Text != expected {
		t.Errorf("Expected %q, got %q", expected, textContent.Text)
	}
}

func TestListTools(t *testing.T) {
	ctx := context.Background()
	s := NewHelloWorldServer()

	t1, t2 := mcp.NewInMemoryTransports()

	go func() {
		if err := s.Connect(ctx, t1, nil); err != nil {
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)
	session, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	found := false
	for tool, err := range session.Tools(ctx, nil) {
		if err != nil {
			t.Fatalf("Failed to list tools: %v", err)
		}
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}

	if !found {
		t.Errorf("hello_world tool not found in list")
	}
}
