{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
}

func NewHelloWorldClient() *Client {
	return &Client{
		mcpClient: mcp.NewClient(&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "1.0.0",
		}, nil),
	}
}

func (c *Client) ListTools(ctx context.Context, serverPath string) error {
	transport := &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}

	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	for tool, err := range session.Tools(ctx, nil) {
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		fmt.Printf("- %s: %s\n", tool.Name, tool.Description)
	}
	return nil
}

func (c *Client) CallTool(ctx context.Context, serverPath string, toolName string) error {
	transport := &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}

	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: toolName,
	})
	if err != nil {
		return fmt.Errorf("failed to call tool: %w", err)
	}

	for _, content := range res.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			fmt.Println(text.Text)
		}
	}
	return nil
}
","filename":"internal/client/client.go"}

