	if *listTools {
		names, err := c.ListTools(ctx, session)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, name := range names {
			fmt.Println(name)
		}
	}

	if *callTool != "" {
		output, err := c.CallTool(ctx, session, *callTool)
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		fmt.Println(output)
	}
}
