import (
	"context"
	"flag"
	"log"
	"os"
	"path/filepath"

	"mcp-hello-world/internal/client"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	// Assuming server is built as ./bin/server relative to current dir
	// Or we can try to find it in the same dir as the client
	ex, err := os.Executable()
	if err != nil {
		log.Fatal(err)
	}
	binDir := filepath.Dir(ex)
	serverCmd := filepath.Join(binDir, "server")

	// If bin/server doesn't exist, try ./bin/server
	if _, err := os.Stat(serverCmd); os.IsNotExist(err) {
		serverCmd = "./bin/server"
	}

	if err := client.RunClient(context.Background(), serverCmd, *listTools, *callTool); err != nil {
		log.Fatal(err)
	}
}
