)

func TestClient(t *testing.T) {
	ctx := context.Background()
	clientTransport, serverTransport := mcp.NewInMemoryTransports()

	s := server.CreateServer()
	serverSession, err := s.Connect(ctx, serverTransport, nil)
	if err != nil {
		t.Fatalf("Failed to connect server: %v", err)
	}
	defer serverSession.Close()

	c := NewClient()
	clientSession, err := c.mcpClient.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("Failed to connect client: %v", err)
	}
	defer clientSession.Close()

	// Test ListTools
	names, err := c.ListTools(ctx, clientSession)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}

	found := false
	for _, name := range names {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("hello_world tool not found in list")
	}

	// Test CallTool
	output, err := c.CallTool(ctx, clientSession, "hello_world")
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}

	expected := "Hello, MCP World!"
	if output != expected {
		t.Errorf("expected %q, got %q", expected, output)
	}
}
