{"content":"package server

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldServer(t *testing.T) {
	s := NewHelloWorldServer()
	if s == nil {
		t.Fatal("NewHelloWorldServer returned nil")
	}

	ctx := context.Background()
	t1, t2 := mcp.NewInMemoryTransports()

	// Connect server to t1
	ss, err := s.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatalf("failed to connect server: %v", err)
	}
	defer ss.Close()

	// Use a client to talk to the server via t2
	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)
	cs, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("failed to connect client: %v", err)
	}
	defer cs.Close()

	// Test ListTools
	tools, err := cs.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("failed to list tools: %v", err)
	}

	found := false
	for _, tool := range tools.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("hello_world tool not found")
	}

	// Test CallTool
	res, err := cs.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("failed to call tool: %v", err)
	}

	if len(res.Content) == 0 {
		t.Fatal("expected content in result")
	}

	text, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("expected text content, got %T", res.Content[0])
	}

	expected := "Hello, MCP World!"
	if text.Text != expected {
		t.Errorf("expected %q, got %q", expected, text.Text)
	}
}
