type EmptyInput struct{}

type HelloOutput struct {
	Message string `json:"message" jsonschema:"The hello world message"`
}

func HelloWorld(ctx context.Context, req *mcp.CallToolRequest, input EmptyInput) (*mcp.CallToolResult, HelloOutput, error) {
	return nil, HelloOutput{Message: "Hello, MCP World!"}, nil
}

func main() {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "hello-world-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns a hello world message",
	}, HelloWorld)

	if err := server.Run(context.Background(), &mcp.StdioTransport{}); err != nil {
		log.Fatal(err)
	}
}
