{"content":"package client

import (
	"context"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
}

func NewClient() *Client {
	return &Client{
		mcpClient: mcp.NewClient(&mcp.Implementation{
			Name:    "example-client",
			Version: "1.0.0",
		}, nil),
	}
}

func (c *Client) Connect(ctx context.Context, serverPath string) (*mcp.ClientSession, error) {
	cmd := exec.Command(serverPath)
	cmd.Stderr = os.Stderr
	transport := &mcp.CommandTransport{Command: cmd}

	return c.mcpClient.Connect(ctx, transport, nil)
}

func (c *Client) ListTools(ctx context.Context, session *mcp.ClientSession) ([]string, error) {
	result, err := session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}

	var names []string
	for _, tool := range result.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

func (c *Client) CallTool(ctx context.Context, session *mcp.ClientSession, name string) (string, error) {
	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return "", err
	}

	var output string
	for _, content := range result.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			output += text.Text
		}
	}
	return output, nil
}
