		err := RunClient(ctx, serverCmd, true, "")
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
	})

	// Test call tool
	t.Run("CallTool", func(t *testing.T) {
		err := RunClient(ctx, serverCmd, false, "hello_world")
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
	})
}
