func run(args []string) error {
	fs := flag.NewFlagSet("client", flag.ContinueOnError)
	listTools := fs.Bool("list-tools", false, "List available tools")
	callTool := fs.String("call-tool", "", "Call a tool by name")
	if err := fs.Parse(args); err != nil {
		return err
	}

	if !*listTools && *callTool == "" {
		fs.Usage()
		return nil
	}

	ex, err := os.Executable()
	if err != nil {
		return err
	}
	binDir := filepath.Dir(ex)
	serverCmd := filepath.Join(binDir, "server")

	if _, err := os.Stat(serverCmd); os.IsNotExist(err) {
		serverCmd = "./bin/server"
	}

	return client.RunClient(context.Background(), serverCmd, *listTools, *callTool)
}
