func TestListTools(t *testing.T) {
	ctx := context.Background()
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	server := mcp.NewServer(&mcp.Implementation{Name: "test"}, nil)
	mcp.AddTool(server, &mcp.Tool{Name: "test_tool"}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return nil, nil, nil
	})

	go server.Run(ctx, serverTransport)

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)
	cs, err := client.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("failed to connect: %v", err)
	}
	defer cs.Close()

	// Redirect stdout to capture output
	oldStdout := os.Stdout
	r, w, _ := os.Pipe()
	os.Stdout = w

	err = ListTools(ctx, cs)
	w.Close()
	os.Stdout = oldStdout

	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}

	out, _ := io.ReadAll(r)
	if string(out) != "test_tool\n" {
		t.Errorf("expected %q, got %q", "test_tool\n", string(out))
	}
}

func TestCallTool(t *testing.T) {
	ctx := context.Background()
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	server := mcp.NewServer(&mcp.Implementation{Name: "test"}, nil)
	mcp.AddTool(server, &mcp.Tool{Name: "test_tool"}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{&mcp.TextContent{Text: "test result"}},
		}, nil, nil
	})

	go server.Run(ctx, serverTransport)

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)
	cs, err := client.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("failed to connect: %v", err)
	}
	defer cs.Close()

	// Redirect stdout to capture output
	oldStdout := os.Stdout
	r, w, _ := os.Pipe()
	os.Stdout = w

	err = CallTool(ctx, cs, "test_tool")
	w.Close()
	os.Stdout = oldStdout

	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}

	out, _ := io.ReadAll(r)
	if string(out) != "test result\n" {
		t.Errorf("expected %q, got %q", "test result\n", string(out))
	}
}
