{"content":"package mcp

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorld(t *testing.T) {
	ctx := context.Background()
	req := &mcp.CallToolRequest{}
	input := EmptyInput{}

	res, output, err := HelloWorld(ctx, req, input)
	if err != nil {
		t.Errorf("HelloWorld returned error: %v", err)
	}
	if output != nil {
		t.Errorf("HelloWorld returned non-nil output: %v", output)
	}
	if res == nil {
		t.Fatal("HelloWorld returned nil result")
	}
	if len(res.Content) != 1 {
		t.Errorf("Expected 1 content, got %d", len(res.Content))
	}
	textContent, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatal("Expected TextContent")
	}
	if textContent.Text != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got '%s'", textContent.Text)
	}
}
