{"content":"package mcp

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorld(t *testing.T) {
	ctx := context.Background()
	req := &mcp.CallToolRequest{}
	input := EmptyInput{}

	res, output, err := HelloWorld(ctx, req, input)
	if err != nil {
		t.Errorf("HelloWorld returned error: %v", err)
	}
	if output != nil {
		t.Errorf("HelloWorld returned non-nil output: %v", output)
	}
	if res == nil {
		t.Fatal("HelloWorld returned nil result")
	}
	if len(res.Content) != 1 {
		t.Errorf("Expected 1 content, got %d", len(res.Content))
	}
	textContent, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatal("Expected TextContent")
	}
	if textContent.Text != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got '%s'", textContent.Text)
	}
}

func TestServerClientIntegration(t *testing.T) {
	// Build the server binary for testing
	tmpDir, err := os.MkdirTemp("", "mcp-test-*")
	if err != nil {
		t.Fatal(err)
	}
	defer os.RemoveAll(tmpDir)

	serverPath := filepath.Join(tmpDir, "server")
	// We need to build the server from cmd/server/main.go but it's relative to project root
	// Since we are in internal/mcp, we need to go up 2 levels
	cmd := exec.Command("go", "build", "-o", serverPath, "../../cmd/server/main.go")
	if output, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("Failed to build server: %v\nOutput: %s", err, string(output))
	}

	ctx := context.Background()

	// Test ListTools
	tools, err := ListTools(ctx, serverPath)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}
	found := false
	for _, tool := range tools {
		if tool == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("hello_world tool not found in %v", tools)
	}

	// Test CallTool
	output, err := CallTool(ctx, serverPath, "hello_world")
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}
	if output != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got '%s'", output)
	}
}
