func ListTools(ctx context.Context, session *mcp.ClientSession) error {
	tools, err := session.ListTools(ctx, nil)
	if err != nil {
		return err
	}
	for _, tool := range tools.Tools {
		fmt.Println(tool.Name)
	}
	return nil
}

func CallTool(ctx context.Context, session *mcp.ClientSession, toolName string) error {
	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: toolName,
	})
	if err != nil {
		return err
	}

	for _, content := range res.Content {
		if textPtr, ok := content.(*mcp.TextContent); ok {
			fmt.Println(textPtr.Text)
		}
	}
	return nil
}
