func RunClient(ctx context.Context, listTools bool, callTool string, serverPath string) error {
	if listTools {
		names, err := ListTools(ctx, serverPath)
		if err != nil {
			return err
		}
		for _, name := range names {
			fmt.Println(name)
		}
