func TestClientIntegration(t *testing.T) {
	ctx := context.Background()

	s := server.NewHelloServer()
	c := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)

	t1, t2 := mcp.NewInMemoryTransports()

	if _, err := s.Connect(ctx, t1, nil); err != nil {
		t.Fatalf("Failed to connect server: %v", err)
	}

	session, err := c.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("Failed to connect client: %v", err)
	}
	defer session.Close()

	t.Run("ListTools", func(t *testing.T) {
		err := ListTools(ctx, session)
		if err != nil {
			t.Errorf("ListTools failed: %v", err)
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		err := CallTool(ctx, session, "hello_world")
		if err != nil {
			t.Errorf("CallTool failed: %v", err)
		}
	})

	t.Run("CallToolNotFound", func(t *testing.T) {
		err := CallTool(ctx, session, "not_found")
		if err == nil {
			t.Error("Expected error for non-existent tool, got nil")
		}
	})
}
