{"content":"package client

import (
	"context"
	"flag"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func RunApp(args []string) error {
	fs := flag.NewFlagSet("client", flag.ContinueOnError)
	listTools := fs.Bool("list-tools", false, "List available tools")
	callTool := fs.String("call-tool", "", "Call a tool by name")
	serverPath := fs.String("server-path", "./bin/server", "Path to the server executable")

	if err := fs.Parse(args); err != nil {
		return err
	}

	if !*listTools && *callTool == "" {
		return fmt.Errorf("either -list-tools or -call-tool must be provided")
	}

	ctx := context.Background()
	c := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "v1.0.0",
	}, nil)

	transport := &mcp.CommandTransport{
		Command: exec.Command(*serverPath),
	}

	session, err := c.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	defer session.Close()

	if *listTools {
		if err := ListTools(ctx, session); err != nil {
			return err
		}
	}

	if *callTool != "" {
		if err := CallTool(ctx, session, *callTool); err != nil {
			return err
		}
	}
	return nil
}
