func runClient(ctx context.Context, cmd *exec.Cmd, listTools bool, callTool string) error {
	transport := &mcp.CommandTransport{Command: cmd}
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if listTools {
		if err := doListTools(ctx, session); err != nil {
			return err
		}
	}

	if callTool != "" {
		if err := doCallTool(ctx, session, callTool); err != nil {
			return err
		}
	}
	return nil
}

func doListTools(ctx context.Context, session *mcp.ClientSession) error {
	tools := session.Tools(ctx, nil)
	for tool, err := range tools {
		if err != nil {
			return fmt.Errorf("error listing tools: %w", err)
		}
		fmt.Println(tool.Name)
	}
	return nil
}

func doCallTool(ctx context.Context, session *mcp.ClientSession, toolName string) error {
	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: toolName,
	})
	if err != nil {
		return fmt.Errorf("error calling tool: %w", err)
	}
	for _, content := range result.Content {
		if textContent, ok := content.(*mcp.TextContent); ok {
			fmt.Println(textContent.Text)
		}
	}
	return nil
}
