{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()

	// Using a custom transport that wraps the server process
	cmd := exec.CommandContext(ctx, *serverPath)
	stdin, err := cmd.StdinPipe()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to create stdin pipe: %v\n", err)
		os.Exit(1)
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to create stdout pipe: %v\n", err)
		os.Exit(1)
	}
	// We should probably redirect stderr of the server to our stderr
	cmd.Stderr = os.Stderr

	if err := cmd.Start(); err != nil {
		fmt.Fprintf(os.Stderr, "Failed to start server: %v\n", err)
		os.Exit(1)
	}
	defer cmd.Process.Kill()

	transport := &mcp.IOTransport{
		Reader: stdout,
		Writer: stdin,
	}

	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "0.1.0",
		},
		nil,
	)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to connect to server: %v\n", err)
		os.Exit(1)
	}
	defer session.Close()

	if *listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Failed to list tools: %v\n", err)
			os.Exit(1)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			fmt.Fprintf(os.Stderr, "Failed to call tool: %v\n", err)
			os.Exit(1)
		}
		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
}
