func TestRunApp(t *testing.T) {
	// Ensure server is built
	serverPath := filepath.Join("..", "..", "bin", "server")
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		t.Skip("Server binary not found at", serverPath)
	}

	t.Run("ListTools", func(t *testing.T) {
		args := []string{"-list-tools", "-server-path", serverPath}
		err := RunApp(args)
		if err != nil {
			t.Errorf("RunApp failed: %v", err)
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		args := []string{"-call-tool", "hello_world", "-server-path", serverPath}
		err := RunApp(args)
		if err != nil {
			t.Errorf("RunApp failed: %v", err)
		}
	})

	t.Run("InvalidArgs", func(t *testing.T) {
		args := []string{"-invalid"}
		err := RunApp(args)
		if err == nil {
			t.Error("Expected error for invalid args, got nil")
		}
	})

	t.Run("MissingArgs", func(t *testing.T) {
		args := []string{}
		err := RunApp(args)
		if err == nil {
			t.Error("Expected error for missing args, got nil")
		}
	})
}
