{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
	session   *mcp.ClientSession
}

func NewClient(serverPath string) (*Client, error) {
	c := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		},
		nil,
	)

	transport := &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}

	session, err := c.Connect(context.Background(), transport, nil)
	if err != nil {
		return nil, err
	}

	return &Client{
		mcpClient: c,
		session:   session,
	}, nil
}

func (c *Client) Close() error {
	return c.session.Close()
}

func (c *Client) ListTools(ctx context.Context) error {
	for tool, err := range c.session.Tools(ctx, nil) {
		if err != nil {
			return err
		}
		fmt.Printf("- %s: %s\n", tool.Name, tool.Description)
	}
	return nil
}

func (c *Client) CallTool(ctx context.Context, name string) error {
	res, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return err
	}

	for _, content := range res.Content {
		if textContent, ok := content.(mcp.TextContent); ok {
			fmt.Println(textContent.Text)
		} else if textPtr, ok := content.(*mcp.TextContent); ok {
			fmt.Println(textPtr.Text)
		}
	}
	return nil
}
","file_path":"internal/client/client.go"}

