{"content":"package server

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldHandler(t *testing.T) {
	ctx := context.Background()
	req := &mcp.CallToolRequest{}
	input := HelloInput{}

	result, extra, err := HelloWorldHandler(ctx, req, input)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if extra != nil {
		t.Fatalf("expected nil extra, got %v", extra)
	}

	if len(result.Content) != 1 {
		t.Fatalf("expected 1 content, got %d", len(result.Content))
	}

	textContent, ok := result.Content[0].(mcp.TextContent)
	if !ok {
		// Try pointer
		textPtr, ok := result.Content[0].(*mcp.TextContent)
		if !ok {
			t.Fatalf("expected TextContent, got %T", result.Content[0])
		}
		if textPtr.Text != "Hello, MCP World!" {
			t.Errorf("expected 'Hello, MCP World!', got %q", textPtr.Text)
		}
	} else {
		if textContent.Text != "Hello, MCP World!" {
			t.Errorf("expected 'Hello, MCP World!', got %q", textContent.Text)
		}
	}
}

func TestNewServer(t *testing.T) {
	s := NewServer()
	if s == nil {
		t.Fatal("expected server, got nil")
	}
}

func TestServerIntegration(t *testing.T) {
	ctx := context.Background()
	s := NewServer()

	t1, t2 := mcp.NewInMemoryTransports()

	_, err := s.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatalf("failed to connect server: %v", err)
	}

	c := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "1.0.0"}, nil)
	session, err := c.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("failed to connect client: %v", err)
	}
	defer session.Close()

	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("failed to call tool: %v", err)
	}

	if len(res.Content) != 1 {
		t.Fatalf("expected 1 content, got %d", len(res.Content))
	}
}
