{"content":"package server

import (
	"context"
	"io"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// NewHelloWorldServer creates a new MCP server with the hello_world tool.
func NewHelloWorldServer() *mcp.Server {
	s := mcp.NewServer(
		&mcp.Implementation{
			Name:    "hello-world-server",
			Version: "0.1.0",
		},
		nil,
	)

	mcp.AddTool(s, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns 'Hello, MCP World!'",
	}, HelloWorldHandler)

	return s
}

// HelloWorldHandler is the handler for the hello_world tool.
func HelloWorldHandler(ctx context.Context, req *mcp.CallToolRequest, input any) (*mcp.CallToolResult, any, error) {
	return &mcp.CallToolResult{
		Content: []mcp.Content{
			&mcp.TextContent{
				Text: "Hello, MCP World!",
			},
		},
	}, nil, nil
}

// RunServer runs the hello world server on the provided reader and writer.
func RunServer(ctx context.Context, r io.ReadCloser, w io.WriteCloser) error {
	s := NewHelloWorldServer()
	return s.Run(ctx, &mcp.IOTransport{Reader: r, Writer: w})
}
