	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldHandler(t *testing.T) {
	ctx := context.Background()
	req := &mcp.CallToolRequest{}

	result, output, err := HelloWorldHandler(ctx, req, nil)
	if err != nil {
		t.Fatalf("Expected no error, got %v", err)
	}

	if output != nil {
		t.Errorf("Expected nil output, got %v", output)
	}

	if result == nil {
		t.Fatal("Expected non-nil result")
	}

	if len(result.Content) != 1 {
		t.Fatalf("Expected 1 content item, got %d", len(result.Content))
	}

	textContent, ok := result.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatal("Expected TextContent")
	}

	expected := "Hello, MCP World!"
	if textContent.Text != expected {
		t.Errorf("Expected %q, got %q", expected, textContent.Text)
	}
}

func TestNewHelloWorldServer(t *testing.T) {
	s := NewHelloWorldServer()
	if s == nil {
		t.Fatal("Expected non-nil server")
	}
}

func TestRunServer(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()

	r, w := io.Pipe()

	// Start server in goroutine
	go func() {
		_ = RunServer(ctx, r, w)
	}()

	// We don't need to do much, just ensure it doesn't crash immediately
	time.Sleep(50 * time.Millisecond)
	r.Close()
	w.Close()
}
