	"context"
	"fmt"
	"io"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// StartServerAndRunClient starts the server process and runs the client.
func StartServerAndRunClient(ctx context.Context, serverPath string, listTools bool, callTool string) error {
	cmd := exec.CommandContext(ctx, serverPath)
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return fmt.Errorf("failed to create stdin pipe: %w", err)
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return fmt.Errorf("failed to create stdout pipe: %w", err)
	}
	cmd.Stderr = os.Stderr

	if err := cmd.Start(); err != nil {
		return fmt.Errorf("failed to start server: %w", err)
	}
	defer cmd.Process.Kill()

	return RunClient(ctx, stdout, stdin, listTools, callTool)
}

// RunClient performs client operations.
func RunClient(ctx context.Context, reader io.ReadCloser, writer io.WriteCloser, listTools bool, callTool string) error {
