{"content":"package hello

import (
	"context"
	"fmt"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// RunClient handles the client logic for listing and calling tools.
func RunClient(ctx context.Context, session *mcp.ClientSession, listTools bool, callTool string) error {
	if listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			return fmt.Errorf("failed to list tools: %v", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %v", err)
		}
		for _, content := range res.Content {
			if tc, ok := content.(*mcp.TextContent); ok {
				fmt.Println(tc.Text)
			}
		}
	}
	return nil
}
