	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	// Use the current directory's bin/server as the server command
	serverCmd := "./bin/server"
	if _, err := os.Stat(serverCmd); os.IsNotExist(err) {
		// Fallback to searching in PATH if not in ./bin/
		serverCmd = "server"
	}

	transport := &mcp.CommandTransport{
		Command: exec.Command(serverCmd),
	}

	if err := run(context.Background(), transport, *listTools, *callTool); err != nil {
		log.Fatal(err)
	}
}

