import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestClient(t *testing.T) {
	ctx := context.Background()
	s := mcp.NewServer(&mcp.Implementation{Name: "test-server", Version: "1.0.0"}, nil)
	mcp.AddTool(s, &mcp.Tool{Name: "test_tool", Description: "test description"}, func(ctx context.Context, req *mcp.CallToolRequest, in struct{}) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{&mcp.TextContent{Text: "test result"}},
		}, nil, nil
	})

	t1, t2 := mcp.NewInMemoryTransports()
	_, err := s.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatalf("failed to connect server: %v", err)
	}

	c, err := NewClient(t2)
	if err != nil {
		t.Fatalf("failed to create client: %v", err)
	}
	defer c.Close()

	t.Run("ListTools", func(t *testing.T) {
		err := c.ListTools(ctx)
		if err != nil {
			t.Errorf("ListTools failed: %v", err)
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		err := c.CallTool(ctx, "test_tool")
		if err != nil {
			t.Errorf("CallTool failed: %v", err)
		}
	})

	t.Run("CallToolNotFound", func(t *testing.T) {
		err := c.CallTool(ctx, "non_existent")
		if err == nil {
			t.Error("expected error for non-existent tool, got nil")
		}
	})
}
","file_path":"internal/client/client_test.go"}

{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		},
		nil,
	)

	// In a real scenario, we might want to specify the path to the server binary.
	// For this task, we assume ./bin/server exists or we can use go run.
	// We'll use ./bin/server as specified in the TODO.
	serverPath := "./bin/server"
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		// Fallback for development if bin/server isn't built yet
		serverPath = "go run ./cmd/server/main.go"
	}

	var cmd *exec.Cmd
	if serverPath == "go run ./cmd/server/main.go" {
		cmd = exec.Command("go", "run", "./cmd/server/main.go")
	} else {
		cmd = exec.Command(serverPath)
	}

	transport := &mcp.CommandTransport{
		Command: cmd,
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	if *listTools {
		res, err := session.ListTools(ctx, &mcp.ListToolsParams{})
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, tool := range res.Tools {
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name:      *callTool,
			Arguments: map[string]any{},
		})
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}

		if res.IsError {
			fmt.Fprintf(os.Stderr, "Tool error\n")
			os.Exit(1)
		}

		for _, content := range res.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
}
","file_path":"cmd/client/main.go"}

