	err := Run(ctx, t2, true, "")
	if err != nil {
		t.Fatalf("Run(listTools=true) failed: %v", err)
	}

	// Test call tool
	// We need a new transport for each connect if we use Run which connects and closes
	t3, t4 := mcp.NewInMemoryTransports()
	go func() {
		if err := s.Connect(ctx, t3, nil); err != nil {
		}
	}()
	err = Run(ctx, t4, false, "hello_world")
	if err != nil {
		t.Fatalf("Run(callTool=hello_world) failed: %v", err)
	}
}
