{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func Run(ctx context.Context, listTools bool, callTool string, serverPath string) error {
	if !listTools && callTool == "" {
		return nil
	}

	c, err := NewClient(&mcp.CommandTransport{
		Command: exec.Command(serverPath),
	})
	if err != nil {
		return err
	}
	defer c.Close()

	if listTools {
		if err := c.ListTools(ctx); err != nil {
			return err
		}
	}

	if callTool != "" {
		if err := c.CallTool(ctx, callTool); err != nil {
			return err
		}
	}
	return nil
}

type Client struct {
	mcpClient *mcp.Client
	session   *mcp.ClientSession
}

func NewClient(transport mcp.Transport) (*Client, error) {
	c := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		},
		nil,
	)

	session, err := c.Connect(context.Background(), transport, nil)
	if err != nil {
		return nil, err
	}

	return &Client{
		mcpClient: c,
		session:   session,
	}, nil
}

func (c *Client) Close() error {
	return c.session.Close()
}

func (c *Client) ListTools(ctx context.Context) error {
	for tool, err := range c.session.Tools(ctx, nil) {
		if err != nil {
			return err
		}
		fmt.Printf("- %s: %s\n", tool.Name, tool.Description)
	}
	return nil
}

func (c *Client) CallTool(ctx context.Context, name string) error {
	res, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return err
	}

	for _, content := range res.Content {
		if textContent, ok := content.(*mcp.TextContent); ok {
			fmt.Println(textContent.Text)
		}
	}
	return nil
}
