{"content":"package tools

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestIntegration(t *testing.T) {
	ctx := context.Background()

	// Create server
	server := mcp.NewServer(&mcp.Implementation{Name: "test-server"}, nil)
	mcp.AddTool(server, &mcp.Tool{Name: "hello_world"}, HelloWorldHandler)

	// Create client
	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)

	// Setup in-memory transports
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	// Run server in background
	go func() {
		if err := server.Run(ctx, serverTransport); err != nil && err != context.Canceled {
			// ignore
		}
	}()

	// Connect client
	session, err := client.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	// List tools
	listRes, err := session.ListTools(ctx, &mcp.ListToolsParams{})
	if err != nil {
		t.Fatalf("Failed to list tools: %v", err)
	}

	found := false
	for _, tool := range listRes.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("Tool hello_world not found")
	}

	// Call tool
	callRes, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("Failed to call tool: %v", err)
	}

	if callRes.IsError {
		t.Fatal("Tool returned error")
	}

	expected := "Hello, MCP World!"
	foundMsg := false
	for _, c := range callRes.Content {
		if text, ok := c.(*mcp.TextContent); ok {
			if text.Text == expected {
				foundMsg = true
			}
		}
	}

	if !foundMsg {
		t.Errorf("Expected message %q not found in content", expected)
	}
}
