{"content":"package client

import (
	"context"
	"fmt"
	"io"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type HelloClient struct {
	client  *mcp.Client
	session *mcp.ClientSession
}

func NewHelloClient() *HelloClient {
	c := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		},
		nil,
	)
	return &HelloClient{client: c}
}

func (c *HelloClient) Connect(ctx context.Context, transport mcp.Transport) error {
	session, err := c.client.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	c.session = session
	return nil
}

func (c *HelloClient) Close() error {
	if c.session != nil {
		return c.session.Close()
	}
	return nil
}

func (c *HelloClient) ListTools(ctx context.Context, out io.Writer) error {
	res, err := c.session.ListTools(ctx, &mcp.ListToolsParams{})
	if err != nil {
		return err
	}
	for _, tool := range res.Tools {
		fmt.Fprintln(out, tool.Name)
	}
	return nil
}

func (c *HelloClient) CallTool(ctx context.Context, name string, out io.Writer) error {
	res, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name:      name,
		Arguments: map[string]any{},
	})
	if err != nil {
		return err
	}

	if res.IsError {
		return fmt.Errorf("tool error")
	}

	for _, content := range res.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			fmt.Fprintln(out, text.Text)
		}
	}
	return nil
}
