{"content":"package client

import (
	"bytes"
	"context"
	"mcp-hello-world/internal/server"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestClient(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	s := server.NewHelloServer()
	st, ct := mcp.NewInMemoryTransports()

	go func() {
		_ = s.Run(ctx, st)
	}()

	hc := NewHelloClient()
	err := hc.Connect(ctx, ct)
	if err != nil {
		t.Fatalf("Connect failed: %v", err)
	}
	defer hc.Close()

	// Test ListTools
	var buf bytes.Buffer
	err = hc.ListTools(ctx, &buf)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}
	if !bytes.Contains(buf.Bytes(), []byte("hello_world")) {
		t.Errorf("ListTools output doesn't contain hello_world: %s", buf.String())
	}

	// Test CallTool
	buf.Reset()
	err = hc.CallTool(ctx, "hello_world", &buf)
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}
	if !bytes.Contains(buf.Bytes(), []byte("Hello, MCP World!")) {
		t.Errorf("CallTool output doesn't contain expected message: %s", buf.String())
	}

	// Test CallTool error
	err = hc.CallTool(ctx, "non_existent", &buf)
	if err == nil {
		t.Error("Expected error for non-existent tool")
	}
}
","file_path":"internal/client/client_test.go"}

