type StreamableClientTransport struct {
        Endpoint   string
        HTTPClient *http.Client
        // MaxRetries is the maximum number of times to attempt a reconnect before giving up.
        // It defaults to 5. To disable retries, use a negative number.
        MaxRetries int

        // Has unexported fields.
}
    A StreamableClientTransport is a Transport that can communicate with an MCP
    endpoint serving the streamable HTTP transport defined by the 2025-03-26
    version of the spec.

func (t *StreamableClientTransport) Connect(ctx context.Context) (Connection, error)
    Connect implements the Transport interface.

    The resulting Connection writes messages via POST requests to the transport
    URL with the Mcp-Session-Id header set, and reads messages from hanging
    requests.

    When closed, the connection issues a DELETE request to terminate the logical
    session.

type StreamableHTTPHandler struct {
        // Has unexported fields.
}
    A StreamableHTTPHandler is an http.Handler that serves streamable MCP
    sessions, as defined by the MCP spec.

[MCP spec]: https://modelcontextprotocol.io/2025/03/26/streamable-http-transport.html

func NewStreamableHTTPHandler(getServer func(*http.Request) *Server, opts *StreamableHTTPOptions) *StreamableHTTPHandler
    NewStreamableHTTPHandler returns a new StreamableHTTPHandler.

    The getServer function is used to create or look up servers for new
    sessions. It is OK for getServer to return the same server multiple times.
    If getServer returns nil, a 400 Bad Request will be served.

func (h *StreamableHTTPHandler) ServeHTTP(w http.ResponseWriter, req *http.Request)

type StreamableHTTPOptions struct {
        // Stateless controls whether the session is 'stateless'.
        //
        // A stateless server does not validate the Mcp-Session-Id header, and uses a
        // temporary session with default initialization parameters. Any
        // server->client request is rejected immediately as there's no way for the
        // client to respond. Server->Client notifications may reach the client if
        // they are made in the context of an incoming request, as described in the
        // documentation for [StreamableServerTransport].
        Stateless bool

        // JSONResponse causes streamable responses to return application/json rather
        // than text/event-stream ([§2.1.5] of the spec).
        //
        // [§2.1.5]: https://modelcontextprotocol.io/specification/2025-06-18/basic/transports#sending-messages-to-the-server
        JSONResponse bool

        // Logger specifies the logger to use.
        // If nil, do not log.
        Logger *slog.Logger

        // EventStore enables stream resumption.
        //
        // If set, EventStore will be used to persist stream events and replay them
        // upon stream resumption.
        EventStore EventStore

        // SessionTimeout configures a timeout for idle sessions.
        //
        // When sessions receive no new HTTP requests from the client for this
        // duration, they are automatically closed.
        //
        // If SessionTimeout is the zero value, idle sessions are never closed.
        SessionTimeout time.Duration
}
    StreamableHTTPOptions configures the StreamableHTTPHandler.

type StreamableServerTransport struct {
        // SessionID is the ID of this session.
        //
        // If SessionID is the empty string, this is a 'stateless' session, which has
        // limited ability to communicate with the client. Otherwise, the session ID
        // must be globally unique, that is, different from any other session ID
        // anywhere, past and future. (We recommend using a crypto random number
        // generator to produce one, as with [crypto/rand.Text].)
        SessionID string

        // Stateless controls whether the eventstore is 'Stateless'. Server sessions
        // connected to a stateless transport are disallowed from making outgoing
        // requests.
        //
        // See also [StreamableHTTPOptions.Stateless].
        Stateless bool

        // EventStore enables stream resumption.
        //
        // If set, EventStore will be used to persist stream events and replay them
        // upon stream resumption.
        EventStore EventStore

        // Has unexported fields.
}
    A StreamableServerTransport implements the server side of the MCP streamable
    transport.

    Each StreamableServerTransport must be connected (via Server.Connect) at
    most once, since StreamableServerTransport.ServeHTTP serves messages to the
    connected session.

    Reads from the streamable server connection receive messages from http
    POST requests from the client. Writes to the streamable server connection
    are sent either to the related stream, or to the standalone SSE stream,
    according to the following rules:
      - JSON-RPC responses to incoming requests are always routed to the
        appropriate HTTP response.
      - Requests or notifications made with a context.Context value derived
        from an incoming request handler, are routed to the HTTP response
        corresponding to that request, unless it has already terminated,
        in which case they are routed to the standalone SSE stream.
      - Requests or notifications made with a detached context.Context value are
        routed to the standalone SSE stream.

func (t *StreamableServerTransport) Connect(ctx context.Context) (Connection, error)
    Connect implements the Transport interface.

func (t *StreamableServerTransport) ServeHTTP(w http.ResponseWriter, req *http.Request)
    ServeHTTP handles a single HTTP request for the session.

type SubscribeParams struct {
        // This property is reserved by the protocol to allow clients and servers to
        // attach additional metadata to their responses.
        Meta `json:"_meta,omitempty"`
        // The URI of the resource to subscribe to.
        URI string `json:"uri"`
}
    Sent from the client to request resources/updated notifications from the
    server whenever a particular resource changes.

type SubscribeRequest = ServerRequest[*SubscribeParams]

type TextContent struct {
        Text        string
        Meta        Meta
        Annotations *Annotations
}
    TextContent is a textual content.

func (c *TextContent) MarshalJSON() ([]byte, error)

type Tool struct {
        // See [specification/2025-06-18/basic/index#general-fields] for notes on _meta
        // usage.
        Meta `json:"_meta,omitempty"`
        // Optional additional tool information.
        //
        // Display name precedence order is: title, annotations.title, then name.
        Annotations *ToolAnnotations `json:"annotations,omitempty"`
        // A human-readable description of the tool.
        //
        // This can be used by clients to improve the LLM's understanding of available
        // tools. It can be thought of like a "hint" to the model.
        Description string `json:"description,omitempty"`
        // InputSchema holds a JSON Schema object defining the expected parameters
        // for the tool.
        //
        // From the server, this field may be set to any value that JSON-marshals to
        // valid JSON schema (including json.RawMessage). However, for tools added
        // using [AddTool], which automatically validates inputs and outputs, the
        // schema must be in a draft the SDK understands. Currently, the SDK uses
        // github.com/google/jsonschema-go for inference and validation, which only
        // supports the 2020-12 draft of JSON schema. To do your own validation, use
        // [Server.AddTool].
        //
        // From the client, this field will hold the default JSON marshaling of the
        // server's input schema (a map[string]any).
        InputSchema any `json:"inputSchema"`
        // Intended for programmatic or logical use, but used as a display name in past
        // specs or fallback (if title isn't present).
        Name string `json:"name"`
        // OutputSchema holds an optional JSON Schema object defining the structure
        // of the tool's output returned in the StructuredContent field of a
        // CallToolResult.
        //
        // From the server, this field may be set to any value that JSON-marshals to
        // valid JSON schema (including json.RawMessage). However, for tools added
        // using [AddTool], which automatically validates inputs and outputs, the
        // schema must be in a draft the SDK understands. Currently, the SDK uses
        // github.com/google/jsonschema-go for inference and validation, which only
        // supports the 2020-12 draft of JSON schema. To do your own validation, use
        // [Server.AddTool].
        //
        // From the client, this field will hold the default JSON marshaling of the
        // server's output schema (a map[string]any).
        OutputSchema any `json:"outputSchema,omitempty"`
        // Intended for UI and end-user contexts — optimized to be human-readable and
        // easily understood, even by those unfamiliar with domain-specific terminology.
        // If not provided, Annotations.Title should be used for display if present,
        // otherwise Name.
        Title string `json:"title,omitempty"`
        // Icons for the tool, if any.
        Icons []Icon `json:"icons,omitempty"`
}
    Definition for a tool the client can call.

type ToolAnnotations struct {
        // If true, the tool may perform destructive updates to its environment. If
        // false, the tool performs only additive updates.
        //
        // (This property is meaningful only when ReadOnlyHint == false.)
        //
        // Default: true
        DestructiveHint *bool `json:"destructiveHint,omitempty"`
        // If true, calling the tool repeatedly with the same arguments will have no
        // additional effect on the its environment.
        //
        // (This property is meaningful only when ReadOnlyHint == false.)
        //
        // Default: false
        IdempotentHint bool `json:"idempotentHint,omitempty"`
        // If true, this tool may interact with an "open world" of external entities. If
        // false, the tool's domain of interaction is closed. For example, the world of
        // a web search tool is open, whereas that of a memory tool is not.
        //
        // Default: true
        OpenWorldHint *bool `json:"openWorldHint,omitempty"`
        // If true, the tool does not modify its environment.
        //
        // Default: false
        ReadOnlyHint bool `json:"readOnlyHint,omitempty"`
        // A human-readable title for the tool.
        Title string `json:"title,omitempty"`
}
    Additional properties describing a Tool to clients.

    NOTE: all properties in ToolAnnotations are hints. They are not guaranteed
    to provide a faithful description of tool behavior (including descriptive
    properties like title).

    Clients should never make tool use decisions based on ToolAnnotations
    received from untrusted servers.

type ToolCapabilities struct {
        // ListChanged reports whether the client supports notifications for
        // changes to the tool list.
        ListChanged bool `json:"listChanged,omitempty"`
}
    ToolCapabilities describes the server's support for tools.

type ToolHandler func(context.Context, *CallToolRequest) (*CallToolResult, error)
    A ToolHandler handles a call to tools/call.

    This is a low-level API, for use with Server.AddTool. It does not do any
    pre- or post-processing of the request or result: the params contain raw
    arguments, no input validation is performed, and the result is returned to
    the user as-is, without any validation of the output.

    Most users will write a ToolHandlerFor and install it with the generic
    AddTool function.

    If ToolHandler returns an error, it is treated as a protocol error.
    By contrast, ToolHandlerFor automatically populates [CallToolResult.IsError]
    and [CallToolResult.Content] accordingly.

type ToolHandlerFor[In, Out any] func(_ context.Context, request *CallToolRequest, input In) (result *CallToolResult, output Out, _ error)
    A ToolHandlerFor handles a call to tools/call with typed arguments and
    results.

    Use AddTool to add a ToolHandlerFor to a server.

    Unlike ToolHandler, ToolHandlerFor provides significant functionality out of
    the box, and enforces that the tool conforms to the MCP spec:
      - The In type provides a default input schema for the tool, though it may
        be overridden in AddTool.
      - The input value is automatically unmarshaled from req.Params.Arguments.
      - The input value is automatically validated against its input schema.
        Invalid input is rejected before getting to the handler.
      - If the Out type is not the empty interface [any], it provides the
        default output schema for the tool (which again may be overridden in
        AddTool).
      - The Out value is used to populate result.StructuredOutput.
      - If [CallToolResult.Content] is unset, it is populated with the JSON
        content of the output.
      - An error result is treated as a tool error, rather than a protocol
        error, and is therefore packed into CallToolResult.Content, with
        [IsError] set.

    For these reasons, most users can ignore the CallToolRequest argument and
    CallToolResult return values entirely. In fact, it is permissible to return
    a nil CallToolResult, if you only care about returning a output value or
    error. The effective result will be populated as described above.

type ToolListChangedParams struct {
        // This property is reserved by the protocol to allow clients and servers to
        // attach additional metadata to their responses.
        Meta `json:"_meta,omitempty"`
}

func (x *ToolListChangedParams) GetProgressToken() any

func (x *ToolListChangedParams) SetProgressToken(t any)

type ToolListChangedRequest = ClientRequest[*ToolListChangedParams]

type Transport interface {
        // Connect returns the logical JSON-RPC connection..
        //
        // It is called exactly once by [Server.Connect] or [Client.Connect].
        Connect(ctx context.Context) (Connection, error)
}
    A Transport is used to create a bidirectional connection between MCP client
    and server.

    Transports should be used for at most one call to Server.Connect or
    Client.Connect.

type URLElicitationCapabilities struct {
}
    URLElicitationCapabilities describes capabilities for url elicitation.

type UnsubscribeParams struct {
        // This property is reserved by the protocol to allow clients and servers to
        // attach additional metadata to their responses.
        Meta `json:"_meta,omitempty"`
        // The URI of the resource to unsubscribe from.
        URI string `json:"uri"`
}
    Sent from the client to request cancellation of resources/updated
    notifications from the server. This should follow a previous
    resources/subscribe request.

type UnsubscribeRequest = ServerRequest[*UnsubscribeParams]

