func NewCommandTransport(serverPath string) mcp.Transport {
	var cmd *exec.Cmd
	if serverPath == "go run ./cmd/server/main.go" {
		cmd = exec.Command("go", "run", "./cmd/server/main.go")
	} else {
		cmd = exec.Command(serverPath)
	}
	return &mcp.CommandTransport{
		Command: cmd,
	}
}

func GetServerPath() string {
	serverPath := "./bin/server"
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		return "go run ./cmd/server/main.go"
	}
	return serverPath
}
