{"content":"package main

import (
	"context"
	"flag"
	"log"
	"os"

	"mcp-hello-world/internal/client"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	hc := client.NewHelloClient()

	serverPath := client.GetServerPath()
	transport := client.NewCommandTransport(serverPath)

	if err := hc.Connect(ctx, transport); err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer hc.Close()

	if *listTools {
		if err := hc.ListTools(ctx, os.Stdout); err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
	}

	if *callTool != "" {
		if err := hc.CallTool(ctx, *callTool, os.Stdout); err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
	}
}
