{"content":"package client

import (
	"context"
	"fmt"
	"io"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Config struct {
	ListTools bool
	CallTool  string
	Transport mcp.Transport
}

func RunClient(ctx context.Context, cfg *Config, out io.Writer) error {
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	session, err := client.Connect(ctx, cfg.Transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	if cfg.ListTools {
		tools := session.Tools(ctx, nil)
		fmt.Fprintln(out, "tools:")
		for t, err := range tools {
			if err != nil {
				return fmt.Errorf("error listing tools: %w", err)
			}
			fmt.Fprintf(out, "- %s: %s\n", t.Name, t.Description)
		}
	}

	if cfg.CallTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: cfg.CallTool,
		})
		if err != nil {
			return fmt.Errorf("error calling tool: %w", err)
		}

		for _, content := range res.Content {
			if textContent, ok := content.(*mcp.TextContent); ok {
				fmt.Fprintln(out, textContent.Text)
			}
		}
	}
	return nil
}
