{"content":"package client

import (
	"bytes"
	"context"
	"mcp-hello-world/internal/server"
	"strings"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestIntegration(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	t1, t2 := mcp.NewInMemoryTransports()

	// Start server in a goroutine
	serverErrCh := make(chan error, 1)
	go func() {
		serverErrCh <- server.RunServer(ctx, t1)
	}()

	// Test ListTools
	var out bytes.Buffer
	cfg := &Config{
		ListTools: true,
		Transport: t2,
	}
	err := RunClient(ctx, cfg, &out)
	if err != nil {
		t.Fatalf("RunClient failed: %v", err)
	}

	if !strings.Contains(out.String(), "hello_world") {
		t.Errorf("expected output to contain hello_world, got %q", out.String())
	}

	// Test CallTool
	out.Reset()
	cfg.ListTools = false
	cfg.CallTool = "hello_world"
	err = RunClient(ctx, cfg, &out)
	if err != nil {
		t.Fatalf("RunClient failed: %v", err)
	}

	if !strings.Contains(out.String(), "Hello, MCP World!") {
		t.Errorf("expected output to contain 'Hello, MCP World!', got %q", out.String())
	}

	cancel()
	// We don't necessarily need to wait for server to exit, but it's good practice
}
