{"content":"package client

import (
	"context"
	"fmt"
	"iter"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type MCPClient struct {
	session *mcp.ClientSession
}

func NewMCPClient(ctx context.Context, transport mcp.Transport) (*MCPClient, error) {
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-mcp-client",
		Version: "1.0.0",
	}, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}
	return &MCPClient{session: session}, nil
}

func (c *MCPClient) Close() error {
	return c.session.Close()
}

func (c *MCPClient) ListTools(ctx context.Context) iter.Seq2[*mcp.Tool, error] {
	return c.session.Tools(ctx, nil)
}

func (c *MCPClient) CallTool(ctx context.Context, name string) (string, error) {
	result, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return "", err
	}

	var output string
	for _, content := range result.Content {
		if textContent, ok := content.(*mcp.TextContent); ok {
			output += textContent.Text
		}
	}
	return output, nil
}
