{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"mcp-example/internal/client"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	cmd := exec.Command(*serverPath)
	transport := &mcp.CommandTransport{Command: cmd}

	mcpClient, err := client.NewMCPClient(ctx, transport)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer mcpClient.Close()

	if *listTools {
		fmt.Println("Available tools:")
		for tool, err := range mcpClient.ListTools(ctx) {
			if err != nil {
				log.Fatalf("Error iterating tools: %v", err)
			}
			fmt.Printf("- %s: %s\n", tool.Name, tool.Description)
		}
	}

	if *callTool != "" {
		output, err := mcpClient.CallTool(ctx, *callTool)
		if err != nil {
			log.Fatalf("Failed to call tool %s: %v", *callTool, err)
		}
		fmt.Println(output)
	}
}
