func TestRunServer(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	t1, _ := mcp.NewInMemoryTransports()

	// Just check if it starts without immediate error
	// We can't easily wait for it to finish because it blocks
	errCh := make(chan error, 1)
	go func() {
		errCh <- RunServer(ctx, t1)
	}()

	cancel()
	err := <-errCh
	if err != nil && err != context.Canceled {
		t.Fatalf("RunServer failed: %v", err)
	}
}
