{"content":"package client

import (
	"context"
	"testing"
	"time"

	"mcp-example/internal/server"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestClientServerInteraction(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	// Create in-memory transports
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	// Start server
	s := server.NewHelloServer()
	go func() {
		if err := s.Run(ctx, serverTransport); err != nil {
			// server might exit on context cancel, which is fine
		}
	}()

	// Start client
	mcpClient, err := NewMCPClient(ctx, clientTransport)
	if err != nil {
		t.Fatalf("Failed to create client: %v", err)
	}
	defer mcpClient.Close()

	// Test ListTools
	toolsFound := false
	for tool, err := range mcpClient.ListTools(ctx) {
		if err != nil {
			t.Fatalf("Error listing tools: %v", err)
		}
		if tool.Name == "hello_world" {
			toolsFound = true
		}
	}
	if !toolsFound {
		t.Error("Tool 'hello_world' not found")
	}

	// Test CallTool
	output, err := mcpClient.CallTool(ctx, "hello_world")
	if err != nil {
		t.Fatalf("Error calling tool: %v", err)
	}
	expected := "Hello, MCP World!"
	if output != expected {
		t.Errorf("Expected %q, got %q", expected, output)
	}
}
