{"content":"package client

import (
	"context"
	"fmt"
	"io"
	"iter"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type MCPClient struct {
	session *mcp.ClientSession
}

func NewMCPClient(ctx context.Context, transport mcp.Transport) (*MCPClient, error) {
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-mcp-client",
		Version: "1.0.0",
	}, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}
	return &MCPClient{session: session}, nil
}

func (c *MCPClient) Close() error {
	return c.session.Close()
}

func (c *MCPClient) ListTools(ctx context.Context) iter.Seq2[*mcp.Tool, error] {
	return c.session.Tools(ctx, nil)
}

func (c *MCPClient) CallTool(ctx context.Context, name string) (string, error) {
	result, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return "", err
	}

	var output string
	for _, content := range result.Content {
		if textContent, ok := content.(*mcp.TextContent); ok {
			output += textContent.Text
		}
	}
	return output, nil
}

func Run(ctx context.Context, transport mcp.Transport, listTools bool, callTool string, out io.Writer) error {
	mcpClient, err := NewMCPClient(ctx, transport)
	if err != nil {
		return err
	}
	defer mcpClient.Close()

	if listTools {
		fmt.Fprintln(out, "Available tools:")
		for tool, err := range mcpClient.ListTools(ctx) {
			if err != nil {
				return err
			}
			fmt.Fprintf(out, "- %s: %s\n", tool.Name, tool.Description)
		}
	}

	if callTool != "" {
		output, err := mcpClient.CallTool(ctx, callTool)
		if err != nil {
			return err
		}
		fmt.Fprintln(out, output)
	}
	return nil
}
","filename":"internal/client/client.go"}

{"content":"package server

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldTool(t *testing.T) {
	s := NewHelloWorldServer()

	clientTransport, serverTransport := mcp.NewInMemoryTransports()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		if err := s.Run(ctx, serverTransport); err != nil && err != context.Canceled {
			t.Errorf("Server.Run failed: %v", err)
		}
	}()

	client := mcp.NewClient(
		&mcp.Implementation{Name: "test-client", Version: "1.0.0"},
		nil,
	)

	session, err := client.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("Client.Connect failed: %v", err)
	}
	defer session.Close()

	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}

	if len(result.Content) != 1 {
		t.Fatalf("Expected 1 content item, got %d", len(result.Content))
	}

	textContent, ok := result.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", result.Content[0])
	}

	expected := "Hello, MCP World!"
	if textContent.Text != expected {
		t.Errorf("Expected %q, got %q", expected, textContent.Text)
	}
}

func TestListTools(t *testing.T) {
	s := NewHelloWorldServer()

	clientTransport, serverTransport := mcp.NewInMemoryTransports()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		if err := s.Run(ctx, serverTransport); err != nil && err != context.Canceled {
			t.Errorf("Server.Run failed: %v", err)
		}
	}()

	client := mcp.NewClient(
		&mcp.Implementation{Name: "test-client", Version: "1.0.0"},
		nil,
	)

	session, err := client.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("Client.Connect failed: %v", err)
	}
	defer session.Close()

	result, err := session.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}

	found := false
	for _, tool := range result.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}

	if !found {
		t.Errorf("Tool 'hello_world' not found in ListTools result")
	}
}
