{"content":"package main

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloServer(t *testing.T) {
	server := NewHelloServer()
	ctx := context.Background()

	t1, t2 := mcp.NewInMemoryTransports()
	go func() {
		if _, err := server.Connect(ctx, t1, nil); err != nil {
			t.Errorf("Server Connect failed: %v", err)
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "1.0.0"}, nil)
	session, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("Client Connect failed: %v", err)
	}
	defer session.Close()

	// Test listing tools
	tools, err := session.Tools(ctx, nil)
	if err != nil {
		t.Fatalf("Listing tools failed: %v", err)
	}

	found := false
	for tool, err := range tools {
		if err != nil {
			t.Fatalf("Error iterating tools: %v", err)
		}
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("Tool 'hello_world' not found in server")
	}

	// Test calling tool
	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("Calling tool failed: %v", err)
	}

	if len(result.Content) != 1 {
		t.Fatalf("Expected 1 content item, got %d", len(result.Content))
	}

	text, ok := result.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", result.Content[0])
	}

	expected := "Hello, MCP World!"
	if text.Text != expected {
		t.Errorf("Expected %q, got %q", expected, text.Text)
	}
}
