{"content":"package client

import (
	"bytes"
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-hello-world/pkg/server"
)

func TestRunClient(t *testing.T) {
	s := server.NewHelloWorldServer()
	clientTransport, serverTransport := mcp.NewInMemoryTransports()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		if err := s.Run(ctx, serverTransport); err != nil && err != context.Canceled {
			t.Errorf("Server.Run failed: %v", err)
		}
	}()

	t.Run("ListTools", func(t *testing.T) {
		var out bytes.Buffer
		err := RunClient(ctx, clientTransport, true, "", &out)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}

		expected := "hello_world\n"
		if out.String() != expected {
			t.Errorf("Expected %q, got %q", expected, out.String())
		}
	})

	// Re-create transports for the second run because Connect might have closed them or session is finished
	// Actually, session.Close() on the client side might close the transport.
}

func TestRunClientCallTool(t *testing.T) {
	s := server.NewHelloWorldServer()
	clientTransport, serverTransport := mcp.NewInMemoryTransports()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		if err := s.Run(ctx, serverTransport); err != nil && err != context.Canceled {
			t.Errorf("Server.Run failed: %v", err)
		}
	}()

	t.Run("CallTool", func(t *testing.T) {
		var out bytes.Buffer
		err := RunClient(ctx, clientTransport, false, "hello_world", &out)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}

		expected := "Hello, MCP World!\n"
		if out.String() != expected {
			t.Errorf("Expected %q, got %q", expected, out.String())
		}
	})
}
