{"filename":"cmd/client/main.go","new_content":"func run(ctx context.Context, listTools bool, callTool string, serverPath string) error {
	cmd := exec.Command(serverPath)
	transport := &mcp.CommandTransport{Command: cmd}

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-mcp-client",
		Version: "1.0.0",
	}, nil)

	cs, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer cs.Close()

	if listTools {
		tools, err := cs.Tools(ctx, nil)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		fmt.Println("tools:")
		for tool, err := range tools {
			if err != nil {
				return fmt.Errorf("error iterating tools: %w", err)
			}
			fmt.Printf("\t%s\n", tool.Name)
		}
	}

	if callTool != "" {
		result, err := cs.Call(ctx, callTool, nil)
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
	return nil
}

func main() {
	listTools := flag.Bool("list-tools", false, "list all available tools")
	callTool := flag.String("call-tool", "", "call a tool by name")
	serverPath := flag.String("server", "./bin/server", "path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		return
	}

	if err := run(context.Background(), *listTools, *callTool, *serverPath); err != nil {
		log.Fatal(err)
	}
