args:
{"content":"package clientapp

import (
	"context"
	"fmt"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type ClientApp struct {
	Client *mcp.Client
}

func NewClientApp() *clientapp.ClientApp {
	return &clientapp.ClientApp{
		Client: mcp.NewClient(&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		}, nil),
	}
}

func (a *ClientApp) ListTools(ctx context.Context, transport mcp.Transport) ([]string, error) {
	session, err := a.Client.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}
	defer session.Close()

	res, err := session.ListTools(ctx, &mcp.ListToolsParams{})
	if err != nil {
		return nil, err
	}

	var names []string
	for _, tool := range res.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

func (a *ClientApp) CallTool(ctx context.Context, transport mcp.Transport, name string) (string, error) {
	session, err := a.Client.Connect(ctx, transport, nil)
	if err != nil {
		return "", err
	}
	defer session.Close()

	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return "", err
	}

	var out string
	for _, content := range res.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			out += text.Text
		}
	}
	return out, nil
}
