func TestClientApp(t *testing.T) {
	ctx := context.Background()
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	server := serverapp.NewHelloServer()
	go server.Run(ctx, serverTransport)

	app := NewClientApp()

	// Test ListTools
	tools, err := app.ListTools(ctx, clientTransport)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}
	found := false
	for _, name := range tools {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("expected tool hello_world not found")
	}

	// Reconnect for CallTool (since Connect closes the transport when deferred session.Close() is called)
	// Actually my implementation of ListTools and CallTool connect and defer close.
	// So I need fresh transports for each call if they close the underlying transport.
	// Let's check if session.Close() closes the transport.
}
