{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()

	// Use ./bin/server as the server to connect to
	serverPath := "./bin/server"
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		// Fallback to cmd/server if bin/server doesn't exist (for development)
		serverPath = "go run ./cmd/server/main.go"
	}

	var cmd *exec.Cmd
	if serverPath == "./bin/server" {
		cmd = exec.Command(serverPath)
	} else {
		cmd = exec.Command("go", "run", "./cmd/server/main.go")
	}

	transport := &mcp.CommandTransport{Command: cmd}
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "example-client",
		Version: "1.0.0",
	}, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer session.Close()

	if *listTools {
		tools := session.Tools(ctx, nil)
		for tool, err := range tools {
			if err != nil {
				log.Fatalf("Failed to list tools: %v", err)
			}
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		result, err := session.CallTool(ctx, *callTool, nil, nil)
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
}
