import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-server/internal/clientapp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	app := clientapp.NewClientApp()

	cmd := exec.Command("./bin/server")
	// No need to set stderr here unless we want to see server panics/logs
	transport := &mcp.CommandTransport{
		Command: cmd,
	}

	if *listTools {
		tools, err := app.ListTools(ctx, transport)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, name := range tools {
			fmt.Println(name)
		}
	} else if *callTool != "" {
		res, err := app.CallTool(ctx, transport, *callTool)
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		fmt.Println(res)
	}
}
