func NewHelloWorldServer() *mcp.Server {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "hello-world-server",
		Version: "v1.0.0",
	}, nil)

	// Add the hello_world tool
	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns 'Hello, MCP World!'",
	}, HelloWorldHandler)

	return server
}

func HelloWorldHandler(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
	return &mcp.CallToolResult{
		Content: []mcp.Content{
			&mcp.TextContent{Text: "Hello, MCP World!"},
		},
	}, nil, nil
}
