{"content":"package main

import (
	"context"
	"fmt"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func runClient(ctx context.Context, listTools bool, callTool string, serverCmd string, serverArgs ...string) error {
	var transport mcp.Transport
	if serverCmd != "" {
		cmd := exec.Command(serverCmd, serverArgs...)
		transport = &mcp.CommandTransport{Command: cmd}
	} else {
		// This is mostly for testing with a provided transport
		return fmt.Errorf("server command required")
	}

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "example-client",
		Version: "1.0.0",
	}, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if listTools {
		tools := session.Tools(ctx, nil)
		for tool, err := range tools {
			if err != nil {
				return fmt.Errorf("failed to list tools: %w", err)
			}
			fmt.Println(tool.Name)
		}
	}

	if callTool != "" {
		params := &mcp.CallToolParams{
			Name: callTool,
		}
		result, err := session.CallTool(ctx, params)
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}

	return nil
}
","filename":"cmd/client/client.go"}

{"content":"package clientlib

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
	session   *mcp.ClientSession
}

func NewClient(name, version string) *Client {
	mcpClient := mcp.NewClient(&mcp.Implementation{
		Name:    name,
		Version: version,
	}, nil)
	return &Client{mcpClient: mcpClient}
}

func (c *Client) Connect(ctx context.Context, serverPath string) error {
	transport := &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}
	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	c.session = session
	return nil
}

func (c *Client) Close() error {
	if c.session != nil {
		return c.session.Close()
	}
	return nil
}

func (c *Client) ListTools(ctx context.Context) ([]string, error) {
	tools, err := c.session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, tool := range tools.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

func (c *Client) CallTool(ctx context.Context, name string) ([]string, error) {
	res, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return nil, err
	}

	var outputs []string
	for _, content := range res.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			outputs = append(outputs, text.Text)
		}
	}
	return outputs, nil
}
","filename":"pkg/clientlib/client.go"}

{"content":"package main

import (
	"context"
	"flag"
	"log"
	"os"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	serverCmd := "./bin/server"
	var serverArgs []string

	if _, err := os.Stat(serverCmd); os.IsNotExist(err) {
		serverCmd = "go"
		serverArgs = []string{"run", "./cmd/server/main.go"}
	}

	if err := runClient(context.Background(), *listTools, *callTool, serverCmd, serverArgs...); err != nil {
		log.Fatal(err)
	}
}
","filename":"cmd/client/main.go"}

