func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()

	// Connect to the server using CommandTransport (stdio)
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-world-client",
		Version: "v1.0.0",
	}, nil)

	// We assume the server is built and located at ./bin/server
	transport := &mcp.CommandTransport{
		Command: exec.Command("./bin/server"),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer session.Close()

	if *listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}

		for _, content := range res.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
}"}

{"content":"package clientapp

import (
	"context"
	"mcp-server/internal/serverapp"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestClientApp(t *testing.T) {
	ctx := context.Background()
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	server := serverapp.NewHelloServer()
	go server.Run(ctx, serverTransport)

	app := NewClientApp()

	// Test ListTools
	tools, err := app.ListTools(ctx, clientTransport)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}
	found := false
	for _, name := range tools {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("expected tool hello_world not found")
	}

	// Test CallTool
	serverTransport2, clientTransport2 := mcp.NewInMemoryTransports()
	go server.Run(ctx, serverTransport2)

	res, err := app.CallTool(ctx, clientTransport2, "hello_world")
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}
	expected := "Hello, MCP World!"
	if res != expected {
		t.Errorf("expected %q, got %q", expected, res)
	}

	// Test error cases
	_, err = app.ListTools(ctx, &mcp.StdioTransport{})
	if err == nil {
		t.Error("expected error with uninitialized stdio transport")
	}

	_, err = app.CallTool(ctx, &mcp.StdioTransport{}, "hello_world")
	if err == nil {
		t.Error("expected error with uninitialized stdio transport")
	}
}
