func TestClient(t *testing.T) {
	ctx := context.Background()
	t1, t2 := mcp.NewInMemoryTransports()

	server := serverlib.NewHelloWorldServer()
	go func() {
		if err := server.Connect(ctx, t1, nil); err != nil {
			// In a test, we can't easily fail the test from a goroutine
			return
		}
	}()

	client := NewClient("test-client", "v1.0.0")
	session, err := client.mcpClient.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	client.session = session
	defer client.Close()

	// Test ListTools
	tools, err := client.ListTools(ctx)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}
	if len(tools) != 1 || tools[0] != "hello_world" {
		t.Errorf("Expected [hello_world], got %v", tools)
	}

	// Test CallTool
	outputs, err := client.CallTool(ctx, "hello_world")
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}
	if len(outputs) != 1 || outputs[0] != "Hello, MCP World!" {
		t.Errorf("Expected ['Hello, MCP World!'], got %v", outputs)
	}
}
