func TestRunClient(t *testing.T) {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "test-server",
		Version: "1.0.0",
	}, nil)

	type emptyArgs struct{}
	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns 'Hello, MCP World!'",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args emptyArgs) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				&mcp.TextContent{Text: "Hello, MCP World!"},
			},
		}, nil, nil
	})

	serverTransport, clientTransport := mcp.NewInMemoryTransports()
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		if err := server.Run(ctx, serverTransport); err != nil && ctx.Err() == nil {
			t.Errorf("Server failed: %v", err)
		}
	}()

	t.Run("list-tools", func(t *testing.T) {
		err := runClient(ctx, true, "", clientTransport)
		if err != nil {
			t.Errorf("runClient failed: %v", err)
		}
	})

	// Note: We need a fresh transport for each run because Connect closes the transport on session close.
	// Actually, session.Close() closes the transport. 
	// So we need to recreate the connection or avoid closing it in runClient if we want to reuse it.
	// But runClient closes the session.
}

func TestRunClientCallTool(t *testing.T) {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "test-server",
		Version: "1.0.0",
	}, nil)

	type emptyArgs struct{}
	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns 'Hello, MCP World!'",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args emptyArgs) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				&mcp.TextContent{Text: "Hello, MCP World!"},
			},
		}, nil, nil
	})

	serverTransport, clientTransport := mcp.NewInMemoryTransports()
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		if err := server.Run(ctx, serverTransport); err != nil && ctx.Err() == nil {
			t.Errorf("Server failed: %v", err)
		}
	}()

	t.Run("call-tool", func(t *testing.T) {
		err := runClient(ctx, false, "hello_world", clientTransport)
		if err != nil {
			t.Errorf("runClient failed: %v", err)
		}
	})
}
