	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	server := mcp.NewServer(
		&mcp.Implementation{
			Name:    "hello-server",
			Version: "1.0.0",
		},
		nil,
	)

	err := server.AddTool(&mcp.Tool{
		Name:        "hello_world",
		Description: "Returns a hello message",
		InputSchema: mcp.NewToolSchema(nil),
	}, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				mcp.TextContent{Text: "Hello, MCP World!"},
			},
		}, nil
	})
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to add tool: %v\n", err)
		os.Exit(1)
	}

	if _, err := server.Connect(context.Background(), &mcp.StdioTransport{}, nil); err != nil {
		fmt.Fprintf(os.Stderr, "server error: %v\n", err)
		os.Exit(1)
	}
}
