func NewHelloWorldServer() *mcp.Server {
	s := mcp.NewServer(&mcp.Implementation{
		Name:    "hello-world-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(s, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns a hello world message",
	}, handler.HelloWorldHandler)

	return s
}
