{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()

	// For the client to connect to the server over stdio, we need to start the server as a subprocess.
	// But the task says "Create a client that connects with the server over stdio".
	// Usually this means the client starts the server.
	// However, if the client is run with flags, it should probably start the server binary.
	// The server binary will be at ./bin/server.

	// In a real MCP setup, the client starts the server process and uses its stdin/stdout.
	// The SDK's StdioTransport uses os.Stdin/os.Stdout, which works for the server.
	// For the client, we need a transport that wraps the subprocess's stdin/stdout.

	serverCmd := exec.CommandContext(ctx, "./bin/server")
	serverIn, err := serverCmd.StdinPipe()
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to get stdin pipe: %v\n", err)
		os.Exit(1)
	}
	serverOut, err := serverCmd.StdoutPipe()
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to get stdout pipe: %v\n", err)
		os.Exit(1)
	}
	serverCmd.Stderr = os.Stderr

	if err := serverCmd.Start(); err != nil {
		fmt.Fprintf(os.Stderr, "failed to start server: %v\n", err)
		os.Exit(1)
	}
	defer func() {
		_ = serverCmd.Process.Kill()
	}()

	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		},
		nil,
	)

	transport := &mcp.IOTransport{
		Reader: serverOut,
		Writer: serverIn,
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to connect: %v\n", err)
		os.Exit(1)
	}
	defer session.Close()

	if *listTools {
		for tool, err := range session.Tools(ctx, nil) {
			if err != nil {
				fmt.Fprintf(os.Stderr, "failed to list tools: %v\n", err)
				os.Exit(1)
			}
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to call tool: %v\n", err)
			os.Exit(1)
		}
		for _, content := range res.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			} else if text, ok := content.(mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
}
