{"content":"package client

import (
	"context"
	"fmt"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type HelloClient struct {
	client  *mcp.Client
	session *mcp.ClientSession
}

func NewHelloClient(name, version string) *HelloClient {
	c := mcp.NewClient(&mcp.Implementation{
		Name:    name,
		Version: version,
	}, nil)
	return &HelloClient{client: c}
}

func (c *HelloClient) Connect(ctx context.Context, transport mcp.Transport) error {
	session, err := c.client.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	c.session = session
	return nil
}

func (c *HelloClient) Close() error {
	if c.session != nil {
		return c.session.Close()
	}
	return nil
}

func (c *HelloClient) ListTools(ctx context.Context) ([]string, error) {
	tools, err := c.session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, tool := range tools.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

func (c *HelloClient) CallTool(ctx context.Context, name string) (string, error) {
	res, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return "", err
	}
	for _, content := range res.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			return text.Text, nil
		}
	}
	return "", fmt.Errorf("no text content returned")
}
