import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloClient(t *testing.T) {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "test-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(server, &mcp.Tool{
		Name: "test_tool",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{&mcp.TextContent{Text: "test result"}},
		}, nil, nil
	})

	ctx := context.Background()
	t1, t2 := mcp.NewInMemoryTransports()

	if _, err := server.Connect(ctx, t1, nil); err != nil {
		t.Fatal(err)
	}

	c := NewHelloClient("test-client", "1.0.0")
	if err := c.Connect(ctx, t2); err != nil {
		t.Fatal(err)
	}
	defer c.Close()

	// Test ListTools
	tools, err := c.ListTools(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if len(tools) != 1 || tools[0] != "test_tool" {
		t.Errorf("unexpected tools: %v", tools)
	}

	// Test CallTool
	res, err := c.CallTool(ctx, "test_tool")
	if err != nil {
		t.Fatal(err)
	}
	if res != "test result" {
		t.Errorf("expected 'test result', got '%s'", res)
	}
}
