{"content":"package clientapp

import (
	"context"
	"fmt"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type ClientConfig struct {
	ListTools bool
	CallTool  string
	ServerCmd string
}

func RunClient(ctx context.Context, config ClientConfig, transport mcp.Transport) error {
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "example-client",
		Version: "1.0.0",
	}, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if config.ListTools {
		params := &mcp.ListToolsParams{}
		result, err := session.ListTools(ctx, params)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, tool := range result.Tools {
			fmt.Println(tool.Name)
		}
	}

	if config.CallTool != "" {
		params := &mcp.CallToolParams{
			Name: config.CallTool,
		}
		result, err := session.CallTool(ctx, params)
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
	return nil
}
","file_path":"pkg/clientapp/client.go"}

{"content":"package main

import (
	"context"
	"flag"
	"log"
	"os/exec"
	"mcp-example/pkg/clientapp"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		return
	}

	config := clientapp.ClientConfig{
		ListTools: *listTools,
		CallTool:  *callTool,
	}

	transport := &mcp.CommandTransport{
		Command: exec.Command("./bin/server"),
	}

	if err := clientapp.RunClient(context.Background(), config, transport); err != nil {
		log.Fatalf("Client error: %v", err)
	}
}
