func main() {
	// Use a logger that writes to stderr because stdout is used for the MCP protocol.
	logger := log.New(os.Stderr, "[server] ", log.LstdFlags)

	server := mcp.NewServer(&mcp.Implementation{
		Name:    "hello-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns 'Hello, MCP World!'",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				&mcp.TextContent{Text: "Hello, MCP World!"},
			},
		}, nil, nil
	})

	if err := server.Run(context.Background(), &mcp.StdioTransport{}); err != nil {
		logger.Fatalf("Server error: %v", err)
	}
}
