	}

	ctx := context.Background()
	if err := c.Connect(ctx, transport); err != nil {
		log.Fatal(err)
	}
	defer c.Close()

	if *listTools {
		tools, err := c.ListTools(ctx)
		if err != nil {
			log.Fatal(err)
