{"content":"package hello

import (
	"context"
	"fmt"
	"io"
	"os"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func ListTools(ctx context.Context, session *mcp.ClientSession) error {
	for tool, err := range session.Tools(ctx, nil) {
		if err != nil {
			return err
		}
		fmt.Println(tool.Name)
	}
	return nil
}

func CallTool(ctx context.Context, session *mcp.ClientSession, toolName string) error {
	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: toolName,
	})
	if err != nil {
		return err
	}
	for _, content := range res.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			fmt.Println(text.Text)
		}
	}
	return nil
}

func NewHelloClient(reader io.ReadCloser, writer io.WriteCloser) (*mcp.Client, *mcp.IOTransport) {
	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		},
		nil,
	)

	transport := &mcp.IOTransport{
		Reader: reader,
		Writer: writer,
	}

	return client, transport
}
