{"content":"package cli

import (
	"context"
	"fmt"

	"mcp-server-client/pkg/client"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Config struct {
	ListTools bool
	CallTool  string
	Transport mcp.Transport
}

func Run(ctx context.Context, cfg Config) error {
	if !cfg.ListTools && cfg.CallTool == "" {
		return fmt.Errorf("either -list-tools or -call-tool must be provided")
	}

	if cfg.Transport == nil {
		return fmt.Errorf("transport must be provided")
	}

	c := client.NewHelloClient("hello-client", "1.0.0")

	if err := c.Connect(ctx, cfg.Transport); err != nil {
		return err
	}
	defer c.Close()

	if cfg.ListTools {
		tools, err := c.ListTools(ctx)
		if err != nil {
			return err
		}
		for _, name := range tools {
			fmt.Println(name)
		}
	}

	if cfg.CallTool != "" {
		res, err := c.CallTool(ctx, cfg.CallTool)
		if err != nil {
			return err
		}
		fmt.Println(res)
	}
	return nil
}
