{"content":"package cli

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestRun(t *testing.T) {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "test-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(server, &mcp.Tool{
		Name: "hello_world",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{&mcp.TextContent{Text: "Hello, MCP World!"}},
		}, nil, nil
	})

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	t1, t2 := mcp.NewInMemoryTransports()
	if _, err := server.Connect(ctx, t1, nil); err != nil {
		t.Fatal(err)
	}

	// Test ListTools
	cfg := Config{
		ListTools: true,
		Transport: t2,
	}
	if err := Run(ctx, cfg); err != nil {
		t.Errorf("Run failed: %v", err)
	}

	// Test CallTool
	t3, t4 := mcp.NewInMemoryTransports()
	if _, err := server.Connect(ctx, t3, nil); err != nil {
		t.Fatal(err)
	}
	cfg = Config{
		CallTool:  "hello_world",
		Transport: t4,
	}
	if err := Run(ctx, cfg); err != nil {
		t.Errorf("Run failed: %v", err)
	}
}

func TestRunErrors(t *testing.T) {
	ctx := context.Background()

	// No flags
	if err := Run(ctx, Config{}); err == nil {
		t.Error("expected error with no flags")
	}

	// No transport
	if err := Run(ctx, Config{ListTools: true}); err == nil {
		t.Error("expected error with no transport")
	}
}
