{"filename":"cmd/client/main.go","new_content":"type ClientOptions struct {
	ListTools  bool
	CallTool   string
	ServerPath string
}

func RunClient(ctx context.Context, opts ClientOptions) error {
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	// CommandTransport is used to spawn the server process and communicate via stdio.
	transport := &mcp.CommandTransport{
		Command: exec.CommandContext(ctx, opts.ServerPath),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	if opts.ListTools {
		tools, err := session.ListTools(ctx, &mcp.ListToolsParams{})
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if opts.CallTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: opts.CallTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range res.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
	return nil
}

func main() {
	opts := ClientOptions{}
	flag.BoolVar(&opts.ListTools, "list-tools", false, "List available tools")
	flag.StringVar(&opts.CallTool, "call-tool", "", "Call a tool by name")
	flag.StringVar(&opts.ServerPath, "server-path", "./bin/server", "Path to the MCP server binary")
	flag.Parse()

	if !opts.ListTools && opts.CallTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	if err := RunClient(context.Background(), opts); err != nil {
		log.Fatal(err)
	}
}
