{"content":"package hello

import (
	"context"
	"fmt"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func HelloWorldHandler(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
	return &mcp.CallToolResult{
		Content: []mcp.Content{
			&mcp.TextContent{Text: "Hello, MCP World!"},
		},
	}, nil, nil
}

func NewHelloServer() *mcp.Server {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "hello-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns 'Hello, MCP World!'",
	}, HelloWorldHandler)

	return server
}

type ClientOptions struct {
	ListTools bool
	CallTool  string
}

func RunClientWithSession(ctx context.Context, session *mcp.ClientSession, opts ClientOptions) error {
	if opts.ListTools {
		tools, err := session.ListTools(ctx, &mcp.ListToolsParams{})
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if opts.CallTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: opts.CallTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range res.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
	return nil
}
