func RunClient(ctx context.Context, listTools bool, callTool string) error {
	serverCmd := exec.CommandContext(ctx, "./bin/server")
	serverIn, err := serverCmd.StdinPipe()
	if err != nil {
		return fmt.Errorf("failed to get stdin pipe: %v", err)
	}
	serverOut, err := serverCmd.StdoutPipe()
	if err != nil {
		return fmt.Errorf("failed to get stdout pipe: %v", err)
	}
	serverCmd.Stderr = os.Stderr

	if err := serverCmd.Start(); err != nil {
		return fmt.Errorf("failed to start server: %v", err)
	}
	defer func() {
		_ = serverCmd.Process.Kill()
	}()

	client, transport := NewHelloClient(serverOut, serverIn)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %v", err)
	}
	defer session.Close()

	if listTools {
		if err := ListTools(ctx, session); err != nil {
			return fmt.Errorf("failed to list tools: %v", err)
		}
	}

	if callTool != "" {
		if err := CallTool(ctx, session, callTool); err != nil {
			return fmt.Errorf("failed to call tool: %v", err)
		}
	}
	return nil
}
