{"content":"package client

import (
	"context"
	"fmt"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
}

func NewClient() *Client {
	return &Client{
		mcpClient: mcp.NewClient(&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		}, nil),
	}
}

func (c *Client) ListTools(ctx context.Context, transport mcp.Transport) ([]string, error) {
	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}
	defer session.Close()

	res, err := session.ListTools(ctx, &mcp.ListToolsParams{})
	if err != nil {
		return nil, err
	}

	var names []string
	for _, tool := range res.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

func (c *Client) CallTool(ctx context.Context, transport mcp.Transport, name string) ([]string, error) {
	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}
	defer session.Close()

	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return nil, err
	}

	var contents []string
	for _, content := range res.Content {
		if tc, ok := content.(*mcp.TextContent); ok {
			contents = append(contents, tc.Text)
		}
	}
	return contents, nil
}
