import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldHandler(t *testing.T) {
	ctx := context.Background()
	res, _, err := HelloWorldHandler(ctx, nil, nil)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if len(res.Content) != 1 {
		t.Fatalf("expected 1 content item, got %d", len(res.Content))
	}

	text, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatal("expected TextContent")
	}

	expected := "Hello, MCP World!"
	if text.Text != expected {
		t.Errorf("expected %q, got %q", expected, text.Text)
	}
}

func TestNewHelloServer(t *testing.T) {
	server := NewHelloServer()
	if server == nil {
		t.Fatal("expected non-nil server")
	}
}

func TestRunClientWithSession(t *testing.T) {
	ctx := context.Background()
	t1, t2 := mcp.NewInMemoryTransports()

	server := NewHelloServer()

	go func() {
		if _, err := server.Connect(ctx, t1, nil); err != nil {
			// This might happen if the test ends before the server connects.
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)
	session, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("client connect error: %v", err)
	}
	defer session.Close()

	t.Run("ListTools", func(t *testing.T) {
		opts := ClientOptions{ListTools: true}
		if err := RunClientWithSession(ctx, session, opts); err != nil {
			t.Errorf("RunClientWithSession failed: %v", err)
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		opts := ClientOptions{CallTool: "hello_world"}
		if err := RunClientWithSession(ctx, session, opts); err != nil {
			t.Errorf("RunClientWithSession failed: %v", err)
		}
	})

	t.Run("CallNonExistentTool", func(t *testing.T) {
		opts := ClientOptions{CallTool: "non_existent"}
		if err := RunClientWithSession(ctx, session, opts); err == nil {
			t.Error("expected error calling non-existent tool, got nil")
		}
	})
}
