package main

import (
        "context"
        "flag"
        "log"
        "os"
        "os/exec"

        "mcp-hello-world/pkg/hello"

        "github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
        opts := hello.ClientOptions{}
        var serverPath string
        flag.BoolVar(&opts.ListTools, "list-tools", false, "List available tools")
        flag.StringVar(&opts.CallTool, "call-tool", "", "Call a tool by name")
        flag.StringVar(&serverPath, "server-path", "./bin/server", "Path to the MCP server binary")
        flag.Parse()

        if !opts.ListTools && opts.CallTool == "" {
                flag.Usage()
                os.Exit(1)
        }

        ctx := context.Background()
        client := mcp.NewClient(&mcp.Implementation{
                Name:    "hello-client",
                Version: "1.0.0",
        }, nil)

        transport := &mcp.CommandTransport{
                Command: exec.CommandContext(ctx, serverPath),
        }

        session, err := client.Connect(ctx, transport, nil)
        if err != nil {
                log.Fatalf("failed to connect: %v", err)
        }
        defer session.Close()

        if err := hello.RunClientWithSession(ctx, session, opts); err != nil {
                log.Fatal(err)
        }
}

