{"content":"package hello

import (
	"context"
	"io"
	"os"
	"testing"
	"time"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestIntegration(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	server := NewHelloServer()

	// Use pipes to simulate stdio
	serverRead, clientWrite := io.Pipe()
	clientRead, serverWrite := io.Pipe()

	client, transport := NewHelloClient(clientRead, clientWrite)

	// Run server in background
	serverTransport := &mcp.IOTransport{Reader: serverRead, Writer: serverWrite}
	go server.Run(ctx, serverTransport)

	cs, err := client.Connect(ctx, transport, nil)
	if err != nil {
		t.Fatalf("failed to connect client: %v", err)
	}
	defer cs.Close()

	// Test ListTools
	if err := ListTools(ctx, cs); err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}

	// Test CallTool
	if err := CallTool(ctx, cs, "hello_world"); err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}
}

func TestRunClient(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	serverPath := "../../bin/server"
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		t.Skip("bin/server not found, skipping TestRunClient")
	}

	if err := RunClient(ctx, serverPath, true, "hello_world"); err != nil {
		t.Fatalf("RunClient failed: %v", err)
	}
}
