{"content":"package app

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func RunClient(ctx context.Context, args []string) error {
	fs := flag.NewFlagSet("client", flag.ContinueOnError)
	listTools := fs.Bool("list-tools", false, "List available tools")
	callTool := fs.String("call-tool", "", "Call a tool by name")
	err := fs.Parse(args)
	if err != nil {
		return err
	}

	if !*listTools && *callTool == "" {
		return fmt.Errorf("either -list-tools or -call-tool must be provided")
	}

	cmd := exec.Command("./bin/server")
	transport := &mcp.CommandTransport{Command: cmd}

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if *listTools {
		tools := session.Tools(ctx, nil)
		fmt.Println("tools:")
		for tool, err := range tools {
			if err != nil {
				return fmt.Errorf("error iterating tools: %w", err)
			}
			fmt.Printf("- %s\n", tool.Name)
		}
	}

	if *callTool != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range result.Content {
			if textContent, ok := content.(*mcp.TextContent); ok {
				fmt.Println(textContent.Text)
			}
		}
	}
	return nil
}
