		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
		if !strings.Contains(stdout.String(), "hello_world") {
			t.Errorf("Expected output to contain 'hello_world', got %q", stdout.String())
		}
	})

	// Reconnect for next test because RunClient closes the session
	clientTransport, serverTransport = mcp.NewInMemoryTransports()
	go func() {
		if err := s.Run(ctx, serverTransport); err != nil {
			// ignore
		}
	}()

	t.Run("call-tool", func(t *testing.T) {
		var stdout bytes.Buffer
		err := RunClient(ctx, clientTransport, false, "hello_world", &stdout)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
		if !strings.Contains(stdout.String(), "Hello, MCP World!") {
			t.Errorf("Expected output to contain 'Hello, MCP World!', got %q", stdout.String())
		}
	})
}
