{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type ClientApp struct {
	Client *mcp.Client
}

func NewClientApp() *ClientApp {
	return &ClientApp{
		Client: mcp.NewClient(&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		}, nil),
	}
}

func (a *ClientApp) Run(ctx context.Context, serverPath string, listTools bool, callTool string) error {
	transport := &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}

	session, err := a.Client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if listTools {
		for tool, err := range session.Tools(ctx, nil) {
			if err != nil {
				return fmt.Errorf("failed to list tools: %w", err)
			}
			fmt.Println(tool.Name)
		}
	}

	if callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}

		for _, content := range res.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}

	return nil
}
