{"content":"package client

import (
	"context"
	"testing"

	"mcp-hello-world/pkg/server"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestClientServerIntegration(t *testing.T) {
	ctx := context.Background()

	s := server.NewHelloWorldServer()
	c := NewClient()

	t1, t2 := mcp.NewInMemoryTransports()

	// Start server on t1
	go func() {
		if _, err := s.Connect(ctx, t1, nil); err != nil {
			// This might happen if test finishes before server connects
		}
	}()

	// List tools
	tools, err := c.ListTools(ctx, t2)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}

	found := false
	for _, name := range tools {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("hello_world tool not found in %v", tools)
	}

	// Call tool - need new transport because ListTools closed it
	t3, t4 := mcp.NewInMemoryTransports()
	go func() {
		if _, err := s.Connect(ctx, t3, nil); err != nil {
		}
	}()

	text, err := c.CallTool(ctx, t4, "hello_world")
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}

	expected := "Hello, MCP World!"
	if text != expected {
		t.Errorf("expected %q, got %q", expected, text)
	}
}
