{"content":"package client

import (
	"context"
	"fmt"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type ClientApp struct {
	Implementation *mcp.Implementation
}

func NewClientApp() *ClientApp {
	return &ClientApp{
		Implementation: &mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		},
	}
}

func (c *ClientApp) ListTools(ctx context.Context, transport mcp.Transport) error {
	client := mcp.NewClient(c.Implementation, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	tools, err := session.ListTools(ctx, nil)
	if err != nil {
		return fmt.Errorf("failed to list tools: %w", err)
	}
	for _, tool := range tools.Tools {
		fmt.Printf("tool: %s\n", tool.Name)
	}
	return nil
}

func (c *ClientApp) CallTool(ctx context.Context, transport mcp.Transport, toolName string) error {
	client := mcp.NewClient(c.Implementation, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: toolName,
	})
	if err != nil {
		return fmt.Errorf("failed to call tool: %w", err)
	}

	for _, content := range result.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			fmt.Println(text.Text)
		}
	}
	return nil
}
