{"content":"package client

import (
	"context"
	"fmt"
	"io"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func RunClient(ctx context.Context, serverPath string, listTools bool, callTool string, out io.Writer) error {
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	transport := &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	if listTools {
		res, err := session.ListTools(ctx, &mcp.ListToolsParams{})
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, tool := range res.Tools {
			fmt.Fprintln(out, tool.Name)
		}
	}

	if callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name:      callTool,
			Arguments: map[string]any{},
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range res.Content {
			if tc, ok := content.(*mcp.TextContent); ok {
				fmt.Fprintln(out, tc.Text)
			}
		}
	}

	return nil
}
