{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		return
	}

	ctx := context.Background()

	implementation := &mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}

	client := mcp.NewClient(implementation, nil)

	// CommandTransport starts the server as a subprocess and connects to its stdio.
	transport := &mcp.CommandTransport{
		Command: exec.Command("./bin/server"),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer session.Close()

	if *listTools {
		result, err := session.ListTools(ctx, nil)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, tool := range result.Tools {
			fmt.Printf("- %s: %s\n", tool.Name, tool.Description)
		}
	}

	if *callTool != "" {
		params := &mcp.CallToolParams{
			Name:      *callTool,
			Arguments: map[string]any{},
		}
		result, err := session.CallTool(ctx, params)
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		if result.IsError {
			log.Fatalf("Tool returned error")
		}
		for _, content := range result.Content {
			if textContent, ok := content.(*mcp.TextContent); ok {
				fmt.Println(textContent.Text)
			}
		}
	}
}
