{"content":"package main

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldTool(t *testing.T) {
	implementation := &mcp.Implementation{
		Name:    "test-server",
		Version: "1.0.0",
	}

	server := mcp.NewServer(implementation, nil)

	tool := &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns a friendly greeting",
		InputSchema: map[string]any{
			"type":       "object",
			"properties": map[string]any{},
		},
	}

	server.AddTool(tool, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				&mcp.TextContent{
					Text: "Hello, MCP World!",
				},
			},
		}, nil
	})

	ctx := context.Background()
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	errCh := make(chan error, 1)
	go func() {
		errCh <- server.Run(ctx, serverTransport)
	}()

	client := mcp.NewClient(implementation, nil)
	session, err := client.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	// Test ListTools
	tools, err := session.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("Failed to list tools: %v", err)
	}

	found := false
	for _, tool := range tools.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("Tool hello_world not found")
	}

	// Test CallTool
	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name:      "hello_world",
		Arguments: map[string]any{},
	})
	if err != nil {
		t.Fatalf("Failed to call tool: %v", err)
	}

	if result.IsError {
		t.Errorf("Tool returned error")
	}

	if len(result.Content) != 1 {
		t.Fatalf("Expected 1 content, got %d", len(result.Content))
	}

	textContent, ok := result.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent")
	}

	if textContent.Text != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got '%s'", textContent.Text)
	}
}
