	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestRunClient(t *testing.T) {
	ctx := context.Background()

	// Create a mock server
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "test-server",
		Version: "1.0.0",
	}, nil)

	type args struct{}
	mcp.AddTool(server, &mcp.Tool{
		Name: "hello_world",
	}, func(ctx context.Context, req *mcp.CallToolRequest, _ args) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				&mcp.TextContent{Text: "Hello, MCP World!"},
			},
		}, nil, nil
	})

	t1, t2 := mcp.NewInMemoryTransports()
	_, err := server.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatalf("failed to connect server: %v", err)
	}

	// Test list tools
	err = RunClient(ctx, true, "", t2)
	if err != nil {
		t.Errorf("RunClient(listTools=true) failed: %v", err)
	}

	// Test call tool
	// Note: We need a new transport for a new session if Connect is called again
	// Actually mcp.NewInMemoryTransports only gives one pair.
	// Let's create another pair for the second test or reuse.
	// The RunClient closes the session, so we need a new transport.
}

func TestRunClientCall(t *testing.T) {
	ctx := context.Background()
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "test-server",
		Version: "1.0.0",
	}, nil)
	mcp.AddTool(server, &mcp.Tool{Name: "hello_world"}, func(ctx context.Context, req *mcp.CallToolRequest, _ any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{Content: []mcp.Content{&mcp.TextContent{Text: "Hello, MCP World!"}}}, nil, nil
	})

	t1, t2 := mcp.NewInMemoryTransports()
	server.Connect(ctx, t1, nil)

	err := RunClient(ctx, false, "hello_world", t2)
	if err != nil {
		t.Errorf("RunClient(callTool=hello_world) failed: %v", err)
	}
}
