{"content":"package client

import (
	"context"
	"mcp-example/pkg/server"
	"testing"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestRunClient(t *testing.T) {
	clientTransport, serverTransport := mcp.MemoryTransport()
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	s := server.NewHelloWorldServer()

	serverErrChan := make(chan error, 1)
	go func() {
		serverErrChan <- s.Run(ctx, serverTransport)
	}()

	err := RunClient(ctx, clientTransport, true, "hello_world")
	if err != nil {
		t.Fatalf("RunClient failed: %v", err)
	}

	// Server should exit when transport is closed by client
	err = <-serverErrChan
	if err != nil && err.Error() != "EOF" && err.Error() != "session closed" {
		// Some errors are expected on close
		t.Logf("Server exited with: %v", err)
	}
}
