{"content":"package client

import (
	"context"
	"fmt"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
	session   *mcp.ClientSession
}

func NewClient(ctx context.Context, transport mcp.Transport) (*Client, error) {
	mcpClient := mcp.NewClient(&mcp.Implementation{
		Name:    "example-client",
		Version: "v0.0.1",
	}, nil)

	session, err := mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}

	return &Client{
		mcpClient: mcpClient,
		session:   session,
	}, nil
}

func (c *Client) ListTools(ctx context.Context) ([]string, error) {
	res, err := c.session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, tool := range res.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

func (c *Client) CallTool(ctx context.Context, name string) (string, error) {
	res, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return "", err
	}
	for _, content := range res.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			return text.Text, nil
		}
	}
	return "", fmt.Errorf("no text content in result")
}

func (c *Client) Close() error {
	return c.session.Close()
}
