func TestRunClient(t *testing.T) {
	// Find the server binary. It should be in ../../bin/server relative to this file
	// but when running go test ./... it depends on where it's executed.
	// We'll try to find it or skip.
	serverPath := "../../bin/server"
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		// Try absolute path from project root
		wd, _ := os.Getwd()
		serverPath = filepath.Join(wd, "../../bin/server")
		if _, err := os.Stat(serverPath); os.IsNotExist(err) {
			t.Skip("server binary not found, run 'go build -o bin/server cmd/server/main.go' first")
		}
	}

	t.Run("list-tools", func(t *testing.T) {
		var stdout bytes.Buffer
		err := RunClient(context.Background(), serverPath, true, "", &stdout)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
		output := stdout.String()
		if !strings.Contains(output, "hello_world") {
			t.Errorf("expected output to contain hello_world, got %q", output)
		}
	})

	t.Run("call-tool", func(t *testing.T) {
		var stdout bytes.Buffer
		err := RunClient(context.Background(), serverPath, false, "hello_world", &stdout)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
		output := stdout.String()
		if !strings.Contains(output, "Hello, MCP World!") {
			t.Errorf("expected output to contain 'Hello, MCP World!', got %q", output)
		}
	})
}
