{"content":"package server

import (
	"context"
	"fmt"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-example/pkg/hello"
)

// NewHelloServer creates a new MCP server with the hello_world tool.
func NewHelloServer() *mcp.Server {
	server := mcp.NewServer(
		&mcp.Implementation{
			Name:    "hello-server",
			Version: "1.0.0",
		},
		nil,
	)

	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns a hello message",
	}, hello.HelloWorldHandler)

	return server
}

// RunServer runs the server on stdio.
func RunServer(ctx context.Context, server *mcp.Server) error {
	if err := server.Run(ctx, &mcp.StdioTransport{}); err != nil {
		return fmt.Errorf("server failed: %w", err)
	}
	return nil
}
","filename":"pkg/server/server.go"}

{"content":"package main

import (
	"context"
	"log"
	"os"
	"os/signal"
	"syscall"

	"mcp-example/pkg/server"
)

func main() {
	s := server.NewHelloServer()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
	go func() {
		<-sigChan
		cancel()
	}()

	if err := server.RunServer(ctx, s); err != nil {
		log.Fatal(err)
	}
}
","filename":"cmd/server/main.go"}

{"content":"package main

import (
	"context"
	"log"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type EmptyInput struct{}

func HelloWorld(ctx context.Context, req *mcp.CallToolRequest, input EmptyInput) (*mcp.CallToolResult, any, error) {
	return &mcp.CallToolResult{
		Content: []mcp.Content{
			&mcp.TextContent{Text: "Hello, MCP World!"},
		},
	}, nil, nil
}

func main() {
	server := mcp.NewServer(
		&mcp.Implementation{
			Name:    "hello-server",
			Version: "1.0.0",
		},
		nil,
	)

	err := mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns Hello, MCP World!",
	}, HelloWorld)
	if err != nil {
		log.Fatalf("Failed to add tool: %v", err)
	}

	if err := server.Run(context.Background(), &mcp.StdioTransport{}); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}
