{"content":"package client

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-example/pkg/server"
)

func TestClient(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	s := server.NewHelloServer()
	t1, t2 := mcp.NewInMemoryTransports()

	go func() {
		_, _ = s.Connect(ctx, t1, nil)
	}()

	c := NewClient()
	err := c.Connect(ctx, t2)
	if err != nil {
		t.Fatalf("failed to connect: %v", err)
	}
	defer c.Close()

	tools, err := c.ListTools(ctx)
	if err != nil {
		t.Fatalf("failed to list tools: %v", err)
	}

	found := false
	for _, name := range tools {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("hello_world tool not found")
	}

	res, err := c.CallTool(ctx, "hello_world")
	if err != nil {
		t.Fatalf("failed to call tool: %v", err)
	}

	if res != "Hello, MCP World!" {
		t.Errorf("expected %q, got %q", "Hello, MCP World!", res)
	}
}
