","file_path":"pkg/handler/handler.go"}

{"content":"package client

import (
	"context"
	"fmt"
	"time"
)

type CLIArgs struct {
	ListTools bool
	CallTool  string
	ServerPath string
}

func RunCLI(ctx context.Context, args CLIArgs) error {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()

	c := NewClient()
	if err := c.ConnectBinary(ctx, args.ServerPath); err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer c.Close()

	if args.ListTools {
		names, err := c.ListTools(ctx)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, name := range names {
			fmt.Println(name)
		}
	}

	if args.CallTool != "" {
		res, err := c.CallTool(ctx, args.CallTool)
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		fmt.Println(res)
	}
	return nil
}
","filename":"pkg/client/cli.go"}

