func runClient(listTools bool, callTool string) error {
	if !listTools && callTool == "" {
		return fmt.Errorf("either --list-tools or --call-tool must be specified")
	}

	// Start the server
	cmd := exec.Command("./bin/server")
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return fmt.Errorf("error getting stdin pipe: %v", err)
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return fmt.Errorf("error getting stdout pipe: %v", err)
	}
	stderr, err := cmd.StderrPipe()
	if err != nil {
		return fmt.Errorf("error getting stderr pipe: %v", err)
	}

	if err := cmd.Start(); err != nil {
		return fmt.Errorf("error starting server: %v", err)
	}
	defer cmd.Process.Kill()

	// Capture stderr for debugging
	go func() {
		// Just drain stderr to avoid blocking if the server writes to it
		_, _ = os.Stderr.ReadFrom(stderr)
	}()

	ctx := context.Background()
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "example-client",
		Version: "1.0.0",
	}, nil)

	transport := &mcp.IOTransport{
		Reader: stdout,
		Writer: stdin,
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("error connecting to server: %v", err)
	}
	defer session.Close()

	if listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			return fmt.Errorf("error listing tools: %v", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if callTool != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("error calling tool: %v", err)
		}
		for _, content := range result.Content {
			if textContent, ok := content.(*mcp.TextContent); ok {
				fmt.Println(textContent.Text)
			}
		}
	}
	return nil
