func TestRunClient(t *testing.T) {
	server := mcp.NewServer(&mcp.Implementation{Name: "test-server", Version: "1.0.0"}, nil)
	mcp.AddTool(server, &mcp.Tool{Name: "hello_world"}, func(ctx context.Context, req *mcp.CallToolRequest, in any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{&mcp.TextContent{Text: "Hello, MCP World!"}},
		}, nil, nil
	})

	ct, st := mcp.NewInMemoryTransports()
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		_ = server.Run(ctx, st)
	}()

	// Test list tools
	err := RunClient(ctx, true, "", ct)
	if err != nil {
		t.Fatalf("RunClient (list) failed: %v", err)
	}

	// Test call tool
	// We need a new transport or reset the existing one? 
	// Usually session.Close() closes the connection.
	// RunClient closes the session, which might close the transport.
	// Let's create new transports for the second call.

	ct2, st2 := mcp.NewInMemoryTransports()
	go func() {
		_ = server.Run(ctx, st2)
	}()

	err = RunClient(ctx, false, "hello_world", ct2)
	if err != nil {
		t.Fatalf("RunClient (call) failed: %v", err)
	}
}
