// MockServer provides a simple server for testing the client
func setupMockServer(ctx context.Context, t *testing.T) mcp.Transport {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "mock-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns a hello world message",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				&mcp.TextContent{Text: "Hello, MCP World!"},
			},
		}, nil, nil
	})

	t1, t2 := mcp.NewInMemoryTransports()
	if _, err := server.Connect(ctx, t1, nil); err != nil {
		t.Fatalf("failed to connect mock server: %v", err)
	}
	return t2
}

func TestRunClient_ListTools(t *testing.T) {
	ctx := context.Background()
	transport := setupMockServer(ctx, t)

	if err := RunClient(ctx, true, "", transport); err != nil {
		t.Errorf("RunClient failed: %v", err)
	}
}

func TestRunClient_CallTool(t *testing.T) {
	ctx := context.Background()
	transport := setupMockServer(ctx, t)

	if err := RunClient(ctx, false, "hello_world", transport); err != nil {
		t.Errorf("RunClient failed: %v", err)
	}
}
