{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
	cs        *mcp.ClientSession
}

func NewClient() *Client {
	return &Client{
		mcpClient: mcp.NewClient(&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "1.0.0",
		}, nil),
	}
}

func (c *Client) Connect(ctx context.Context, serverPath string) error {
	cmd := exec.Command(serverPath)
	transport := &mcp.CommandTransport{Command: cmd}
	cs, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	c.cs = cs
	return nil
}

func (c *Client) Close() error {
	if c.cs != nil {
		return c.cs.Close()
	}
	return nil
}

func (c *Client) ListTools(ctx context.Context) ([]string, error) {
	var tools []string
	for tool, err := range c.cs.Tools(ctx, nil) {
		if err != nil {
			return nil, err
		}
		tools = append(tools, tool.Name)
	}
	return tools, nil
}

func (c *Client) CallTool(ctx context.Context, name string) (string, error) {
	result, err := c.cs.CallTool(ctx, &mcp.CallToolRequest{
		Params: struct {
			Name string `json:"name"`
		}{Name: name},
	}, nil)
	if err != nil {
		return "", err
	}

	for _, content := range result.Content {
		if textContent, ok := content.(*mcp.TextContent); ok {
			return textContent.Text, nil
		}
	}

	return "", fmt.Errorf("no text content in result")
}
