{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"

	"mcp-example/internal/client"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	c := client.NewClient()

	// Use absolute path to the server binary
	serverPath, err := filepath.Abs("./bin/server")
	if err != nil {
		log.Fatal(err)
	}

	if err := c.Connect(ctx, serverPath); err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer c.Close()

	if *listTools {
		tools, err := c.ListTools(ctx)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, tool := range tools {
			fmt.Println(tool)
		}
	}

	if *callTool != "" {
		result, err := c.CallTool(ctx, *callTool)
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		fmt.Println(result)
	}
}
