	}

	res, err := cs.GetPrompt(ctx, &mcp.GetPromptParams{
		Name:		"greet",
		Arguments:	map[string]string{"name": "Pat"},
	})
	if err != nil {
		log.Fatal(err)
	}
	for _, msg := range res.Messages {
