{"content":"package main

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestIntegration(t *testing.T) {
	s := mcp.NewServer(
		&mcp.Implementation{
			Name:    "hello-world",
			Version: "1.0.0",
		},
		&mcp.ServerOptions{},
	)

	s.AddTool(&mcp.Tool{
		Name:        "hello_world",
		Description: "Returns 'Hello, MCP World!'",
		InputSchema: map[string]any{
			"type":       "object",
			"properties": map[string]any{},
		},
	}, func(ctx context.Context, request *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				&mcp.TextContent{Text: "Hello, MCP World!"},
			},
		}, nil
	})

	cTransport, sTransport := mcp.NewInMemoryTransports()

	ctx := context.Background()
	errCh := make(chan error, 1)
	go func() {
		errCh <- s.Run(ctx, sTransport)
	}()

	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "1.0.0",
		},
		&mcp.ClientOptions{},
	)

	session, err := client.Connect(ctx, cTransport, &mcp.ClientSessionOptions{})
	if err != nil {
		t.Fatalf("failed to connect: %v", err)
	}

	// Test ListTools
	listRes, err := session.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}
	found := false
	for _, tool := range listRes.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("hello_world tool not found")
	}

	// Test CallTool
	callRes, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}
	if len(callRes.Content) != 1 {
		t.Fatalf("expected 1 content, got %d", len(callRes.Content))
	}
	tc, ok := callRes.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("expected TextContent, got %T", callRes.Content[0])
	}
	if tc.Text != "Hello, MCP World!" {
		t.Errorf("expected 'Hello, MCP World!', got %q", tc.Text)
	}
}
","filename":"integration_test.go"}

{"content":"package client

import (
	"context"
	"mcp-example/internal/server"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestClient(t *testing.T) {
	ctx := context.Background()
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	s := server.NewHelloWorldServer()
	go func() {
		if err := s.Run(ctx, serverTransport); err != nil && err != context.Canceled {
			t.Errorf("Server run failed: %v", err)
		}
	}()

	c := NewClient()
	// We need to bypass c.Connect because it uses exec.Command
	// So we'll manually set the session
	cs, err := c.mcpClient.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	c.cs = cs
	defer c.Close()

	t.Run("ListTools", func(t *testing.T) {
		tools, err := c.ListTools(ctx)
		if err != nil {
			t.Fatalf("ListTools failed: %v", err)
		}
		found := false
		for _, tool := range tools {
			if tool == "hello_world" {
				found = true
				break
			}
		}
		if !found {
			t.Error("Expected tool 'hello_world' not found")
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		result, err := c.CallTool(ctx, "hello_world")
		if err != nil {
			t.Fatalf("CallTool failed: %v", err)
		}
		if result != "Hello, MCP World!" {
			t.Errorf("Expected 'Hello, MCP World!', got %q", result)
		}
	})
}
