func TestIntegration(t *testing.T) {
	s := newServer()

	cTransport, sTransport := mcp.NewInMemoryTransports()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	errCh := make(chan error, 1)
	go func() {
		errCh <- s.Run(ctx, sTransport)
	}()

	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "1.0.0",
		},
		&mcp.ClientOptions{},
	)

	session, err := client.Connect(ctx, cTransport, &mcp.ClientSessionOptions{})
	if err != nil {
		t.Fatalf("failed to connect: %v", err)
	}

	// Test ListTools
	listRes, err := session.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}
	found := false
	for _, tool := range listRes.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("hello_world tool not found")
	}

	// Test CallTool
	callRes, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}
	if len(callRes.Content) != 1 {
		t.Fatalf("expected 1 content, got %d", len(callRes.Content))
	}
	tc, ok := callRes.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("expected TextContent, got %T", callRes.Content[0])
	}
	if tc.Text != "Hello, MCP World!" {
		t.Errorf("expected 'Hello, MCP World!', got %q", tc.Text)
	}
}
