{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"io"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type clientApp struct {
	serverPath string
	stdout     io.Writer
	stderr     io.Writer
}

func (a *clientApp) run(listTools bool, callTool string) error {
	if !listTools && callTool == "" {
		return nil
	}

	// Launch server
	cmd := exec.Command(a.serverPath)
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return fmt.Errorf("failed to get stdin pipe: %v", err)
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return fmt.Errorf("failed to get stdout pipe: %v", err)
	}
	stderr, err := cmd.StderrPipe()
	if err != nil {
		return fmt.Errorf("failed to get stderr pipe: %v", err)
	}
	// Stream stderr to our stderr for debugging
	go func() {
		_, _ = io.Copy(a.stderr, stderr)
	}()

	if err := cmd.Start(); err != nil {
		return fmt.Errorf("failed to start server: %v", err)
	}
	defer func() {
		_ = cmd.Process.Kill()
	}()

	ctx := context.Background()
	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "1.0.0",
		},
		&mcp.ClientOptions{},
	)

	session, err := client.Connect(ctx, &mcp.IOTransport{
		Reader: stdout,
		Writer: stdin,
	}, &mcp.ClientSessionOptions{})
	if err != nil {
		return fmt.Errorf("failed to connect to server: %v", err)
	}

	if listTools {
		result, err := session.ListTools(ctx, nil)
		if err != nil {
			return fmt.Errorf("failed to list tools: %v", err)
		}
		for _, tool := range result.Tools {
			fmt.Fprintln(a.stdout, tool.Name)
		}
	}

	if callTool != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool %q: %v", callTool, err)
		}
		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Fprintln(a.stdout, text.Text)
			}
		}
	}
	return nil
}

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	app := &clientApp{
		serverPath: "./bin/server",
		stdout:     os.Stdout,
		stderr:     os.Stderr,
	}

	if err := app.run(*listTools, *callTool); err != nil {
		log.Fatal(err)
	}
}
