import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestClientRun(t *testing.T) {
	// Find the project root to find bin/server
	// In go test, the working directory is the package directory.
	// So we need to go up to the root.

	// Try to find the server binary.
	// We assume it's built in ../../bin/server
	serverPath := filepath.Join("..", "..", "bin", "server")
	if _, err := os.Stat(serverPath); err != nil {
		t.Skipf("server binary not found at %s, skipping integration test", serverPath)
	}

	stdout := &bytes.Buffer{}
	stderr := &bytes.Buffer{}
	app := &clientApp{
		serverPath: serverPath,
		stdout:     stdout,
		stderr:     stderr,
	}

	// Test list-tools
	err := app.run(true, "")
	if err != nil {
		t.Fatalf("client run (list-tools) failed: %v", err)
	}
	if !strings.Contains(stdout.String(), "hello_world") {
		t.Errorf("expected output to contain 'hello_world', got %q", stdout.String())
	}

	// Test call-tool
	stdout.Reset()
	err = app.run(false, "hello_world")
	if err != nil {
		t.Fatalf("client run (call-tool) failed: %v", err)
	}
	if !strings.Contains(stdout.String(), "Hello, MCP World!") {
		t.Errorf("expected output to contain 'Hello, MCP World!', got %q", stdout.String())
	}
}
