{"filename":"internal/client/cli.go","new_content":"import (
	"context"
	"flag"
	"fmt"
	"io"
	"log"
	"os"
	"path/filepath"
)

func RunCLI(args []string, stdout, stderr io.Writer) {
	fs := flag.NewFlagSet("mcp-client", flag.ContinueOnError)
	fs.SetOutput(stderr)
	listTools := fs.Bool("list-tools", false, "List available tools")
	callTool := fs.String("call-tool", "", "Call a tool by name")

	if err := fs.Parse(args); err != nil {
		return
	}

	if !*listTools && *callTool == "" {
		fs.Usage()
		return
	}

	ctx := context.Background()
	c := NewClient()

	// Use absolute path to the server binary
	serverPath, err := filepath.Abs("./bin/server")
	if err != nil {
		fmt.Fprintln(stderr, err)
		return
	}

	if err := c.Connect(ctx, serverPath); err != nil {
		fmt.Fprintf(stderr, "Failed to connect: %v\n", err)
		return
	}
	defer c.Close()

	if *listTools {
		tools, err := c.ListTools(ctx)
		if err != nil {
			fmt.Fprintf(stderr, "Failed to list tools: %v\n", err)
			return
		}
		for _, tool := range tools {
			fmt.Fprintln(stdout, tool)
		}
	}

	if *callTool != "" {
		result, err := c.CallTool(ctx, *callTool)
		if err != nil {
			fmt.Fprintf(stderr, "Failed to call tool: %v\n", err)
			return
		}
		fmt.Fprintln(stdout, result)
	}
}
