func TestIntegration(t *testing.T) {
	ctx := context.Background()
	s := server.NewHelloWorldServer()

	t1, t2 := mcp.NewInMemoryTransports()

	go func() {
		if _, err := s.Connect(ctx, t1, nil); err != nil {
			panic(err)
		}
	}()

	c := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "1.0.0"}, nil)
	session, err := c.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("failed to connect: %v", err)
	}
	defer session.Close()

	names, err := client.ListTools(ctx, session)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}
	found := false
	for _, n := range names {
		if n == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("hello_world tool not found")
	}

	results, err := client.CallTool(ctx, session, "hello_world")
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}
	if len(results) != 1 || results[0] != "Hello, MCP World!" {
		t.Errorf("unexpected results: %v", results)
