func TestIntegration(t *testing.T) {
	ctx := context.Background()

	// Find the server binary.
	cwd, _ := os.Getwd()
	serverPath := filepath.Join(cwd, "..", "..", "bin", "server")

	// Check if server exists, if not, skip (or we can try to build it)
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		t.Skip("bin/server not found, skipping integration test")
	}

	transport := &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}

	c := mcp.NewClient(&mcp.Implementation{
		Name:    "test-client",
		Version: "1.0.0",
	}, nil)

	cs, err := c.Connect(ctx, transport, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer cs.Close()

	// Test ListTools
	err = ListTools(ctx, cs)
	if err != nil {
		t.Errorf("ListTools failed: %v", err)
	}

	// Test CallTool
	err = CallTool(ctx, cs, "hello_world")
	if err != nil {
		t.Errorf("CallTool failed: %v", err)
	}
}
