{"content":"package app

import (
	"context"
	"flag"
	"fmt"
	"io"
	"mcp-example/internal/client"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func RunClient(ctx context.Context, stdout io.Writer, args []string) error {
	fs := flag.NewFlagSet("client", flag.ContinueOnError)
	listToolsFlag := fs.Bool("list-tools", false, "List available tools")
	callToolFlag := fs.String("call-tool", "", "Call a tool by name")
	serverPath := fs.String("server-path", "./bin/server", "Path to the server executable")
	if err := fs.Parse(args); err != nil {
		return err
	}

	if !*listToolsFlag && *callToolFlag == "" {
		return fmt.Errorf("either -list-tools or -call-tool must be provided")
	}

	c := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-world-client",
		Version: "1.0.0",
	}, nil)

	transport := &mcp.CommandTransport{
		Command: exec.CommandContext(ctx, *serverPath),
	}

	session, err := c.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	defer session.Close()

	if *listToolsFlag {
		names, err := client.ListTools(ctx, session)
		if err != nil {
			return err
		}
		for _, name := range names {
			fmt.Fprintln(stdout, name)
		}
	}

	if *callToolFlag != "" {
		results, err := client.CallTool(ctx, session, *callToolFlag)
		if err != nil {
			return err
		}
		for _, res := range results {
			fmt.Fprintln(stdout, res)
		}
	}
	return nil
}
