	// Skip if bin/server doesn't exist
	serverPath, err := filepath.Abs("../../bin/server")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		t.Skip("bin/server not found, skipping integration test")
	}

	// Change working directory to project root for the duration of this test
	originalWd, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	projectRoot := filepath.Join(originalWd, "../..")
	if err := os.Chdir(projectRoot); err != nil {
		t.Fatal(err)
	}
	defer os.Chdir(originalWd)

	t.Run("ListTools", func(t *testing.T) {
		var stdout, stderr bytes.Buffer
		RunCLI([]string{"--list-tools"}, &stdout, &stderr)
		if stderr.Len() > 0 {
			t.Errorf("Unexpected stderr: %s", stderr.String())
		}
		if !bytes.Contains(stdout.Bytes(), []byte("hello_world")) {
			t.Errorf("Expected 'hello_world' in stdout, got %q", stdout.String())
		}
