	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestIntegration(t *testing.T) {
	ctx := context.Background()

	// Find the server binary.
	cwd, _ := os.Getwd()
	serverPath := filepath.Join(cwd, "..", "..", "bin", "server")

	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		t.Skip("bin/server not found, skipping integration test")
	}

	transport := &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}

	// Test ListTools via RunClient
	err := RunClient(ctx, transport, true, "")
	if err != nil {
		t.Errorf("RunClient(listTools=true) failed: %v", err)
	}

	// Recreate transport for another run because CommandTransport can only be used once
	transport = &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}

	// Test CallTool via RunClient
	err = RunClient(ctx, transport, false, "hello_world")
	if err != nil {
		t.Errorf("RunClient(callTool=hello_world) failed: %v", err)
	}
}
