	logger := slog.New(mcp.NewLoggingHandler(ss, nil))

	logger.Info("info shows up", "value", 1)
	logger.Debug("debug doesn't show up", "value", 2)
	logger.Warn("warn shows up", "value", 3)

	<-done

}
