// GreetArgs represents the arguments for the hello_world tool.
type GreetArgs struct{}

// HelloWorldHandler returns "Hello, MCP World!".
func HelloWorldHandler(ctx context.Context, req *mcp.CallToolRequest, args GreetArgs) (*mcp.CallToolResult, any, error) {
