package server

import (
        "context"

        "github.com/example/mcp-hello-world/pkg/hello"
        "github.com/modelcontextprotocol/go-sdk/mcp"
)

// CreateServer initializes the MCP server with the hello_world tool.
func CreateServer() *mcp.Server {
        s := mcp.NewServer(&mcp.Implementation{
                Name:    "hello-server",
                Version: "1.0.0",
        }, nil)

        mcp.AddTool(s, &mcp.Tool{
                Name:        "hello_world",
                Description: "Returns 'Hello, MCP World!'",
        }, hello.HelloWorldHandler)

        return s
}

// RunServer runs the server on the given transport.
func RunServer(ctx context.Context, transport mcp.Transport) error {
        s := CreateServer()
        return s.Run(ctx, transport)
}
package client

import (
        "context"
        "fmt"

        "github.com/modelcontextprotocol/go-sdk/mcp"
)

// ListTools prints the names of all available tools.
func ListTools(ctx context.Context, cs *mcp.ClientSession) error {
        for tool, err := range cs.Tools(ctx, nil) {
                if err != nil {
                        return err
                }
                fmt.Println(tool.Name)
        }
        return nil
}

// CallTool calls a tool by name and prints its text content.
func CallTool(ctx context.Context, cs *mcp.ClientSession, name string) error {
        result, err := cs.CallTool(ctx, &mcp.CallToolParams{
                Name: name,
        })
        if err != nil {
                return err
        }

        for _, content := range result.Content {
                if text, ok := content.(*mcp.TextContent); ok {
                        fmt.Println(text.Text)
                }
        }
        return nil
}

// RunClient connects to a server and performs actions based on flags.
func RunClient(ctx context.Context, transport mcp.Transport, listTools bool, callTool string) error {
        c := mcp.NewClient(&mcp.Implementation{
                Name:    "hello-client",
                Version: "1.0.0",
        }, nil)

        cs, err := c.Connect(ctx, transport, nil)
        if err != nil {
                return err
        }
        defer cs.Close()

        if listTools {
                if err := ListTools(ctx, cs); err != nil {
                        return err
                }
        }

        if callTool != "" {
                if err := CallTool(ctx, cs, callTool); err != nil {
                        return err
                }
        }

        return nil
}

