{"content":"package hello

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldHandler(t *testing.T) {
	ctx := context.Background()
	res, out, err := HelloWorldHandler(ctx, nil, nil)
	if err != nil {
		t.Fatalf("Expected no error, got %v", err)
	}
	if res != nil {
		t.Errorf("Expected nil result, got %v", res)
	}
	if out != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got %v", out)
	}
}

func TestIntegration(t *testing.T) {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "test-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns Hello, MCP World!",
	}, HelloWorldHandler)

	sTrans, cTrans := mcp.NewInMemoryTransports()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		if err := server.Run(ctx, sTrans); err != nil && ctx.Err() == nil {
			t.Errorf("Server run error: %v", err)
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "test-client",
		Version: "1.0.0",
	}, nil)

	session, err := client.Connect(ctx, cTrans, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	// Test ListTools
	listRes, err := session.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("ListTools error: %v", err)
	}
	found := false
	for _, tool := range listRes.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("Tool 'hello_world' not found in ListTools")
	}

	// Test CallTool
	callRes, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("CallTool error: %v", err)
	}
	if callRes.IsError {
		t.Fatalf("Tool returned error")
	}
	if len(callRes.Content) == 0 {
		t.Fatalf("Expected content, got none")
	}
	text, ok := callRes.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", callRes.Content[0])
	}
	if text.Text != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got %q", text.Text)
	}
}
