{"content":"package client

import (
	"context"
	"fmt"
	"io"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
}

func NewHelloWorldClient() *Client {
	return &Client{
		mcpClient: mcp.NewClient(
			&mcp.Implementation{
				Name:    "hello-world-client",
				Version: "1.0.0",
			},
			nil,
		),
	}
}

func (c *Client) Run(ctx context.Context, transport mcp.Transport, listTools bool, callTool string, out io.Writer) error {
	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, tool := range tools.Tools {
			fmt.Fprintln(out, tool.Name)
		}
	}

	if callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}

		for _, content := range res.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Fprintln(out, text.Text)
			}
		}
	}

	return nil
}
