{"content":"package clientlib

import (
	"context"
	"fmt"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// ClientApp represents the client application logic.
type ClientApp struct {
	Client *mcp.Client
}

// NewClientApp creates a new ClientApp.
func NewClientApp() *ClientApp {
	return &ClientApp{
		Client: mcp.NewClient(&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		}, nil),
	}
}

// ListTools lists available tools from the server using the provided transport.
func (a *ClientApp) ListTools(ctx context.Context, transport mcp.Transport) ([]string, error) {
	session, err := a.Client.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}
	defer session.Close()

	result, err := session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}

	var names []string
	for _, tool := range result.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

// CallTool calls a tool by name on the server using the provided transport.
func (a *ClientApp) CallTool(ctx context.Context, transport mcp.Transport, name string) (string, error) {
	session, err := a.Client.Connect(ctx, transport, nil)
	if err != nil {
		return "", err
	}
	defer session.Close()

	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return "", err
	}
	if result.IsError {
		return "", fmt.Errorf("tool returned error")
	}

	var output string
	for _, content := range result.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			output += text.Text
		}
	}
	return output, nil
}
