{"filename":"cmd/client/main.go","new_content":"func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	transport := &mcp.CommandTransport{
		Command: exec.Command("./bin/server"),
	}

	if err := Run(ctx, client, transport, *listTools, *callTool); err != nil {
		log.Fatal(err)
	}
}

func Run(ctx context.Context, client *mcp.Client, transport mcp.Transport, listTools bool, callTool string) error {
	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	if listTools {
		result, err := session.ListTools(ctx, nil)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, tool := range result.Tools {
			fmt.Println(tool.Name)
		}
	}

	if callTool != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}

		if result.IsError {
			fmt.Printf("Tool returned error: ")
		}

		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
	return nil
}
