type empty struct{}

func SetupServer() *mcp.Server {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "hello-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns 'Hello, MCP World!'",
	}, HelloWorldHandler)

	return server
}

func HelloWorldHandler(ctx context.Context, req *mcp.CallToolRequest, args empty) (*mcp.CallToolResult, any, error) {
