{"content":"package clientlib

import (
	"context"
	"testing"

	"mcp-server/internal/serverlib"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestClientApp(t *testing.T) {
	server := serverlib.NewHelloServer()
	sTrans, cTrans := mcp.NewInMemoryTransports()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		if err := server.Run(ctx, sTrans); err != nil && ctx.Err() == nil {
			t.Errorf("Server run error: %v", err)
		}
	}()

	app := NewClientApp()

	// Test ListTools
	names, err := app.ListTools(ctx, cTrans)
	if err != nil {
		t.Fatalf("ListTools error: %v", err)
	}
	found := false
	for _, name := range names {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("Tool 'hello_world' not found")
	}

	// Test CallTool
	// Note: we need a new transport for a new connection if the previous one closed it
	// But ListTools closes the connection.
	_, cTrans2 := mcp.NewInMemoryTransports()
	// Wait, the server is also closed.
	// I should probably not close the connection in ListTools if I want to reuse the server,
	// or I should start the server per call.
	// Actually, StdioTransport/CommandTransport start a new process/connection anyway.
}

func TestClientApp_CallTool(t *testing.T) {
	server := serverlib.NewHelloServer()
	sTrans, cTrans := mcp.NewInMemoryTransports()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		if err := server.Run(ctx, sTrans); err != nil && ctx.Err() == nil {
			t.Errorf("Server run error: %v", err)
		}
	}()

	app := NewClientApp()
	output, err := app.CallTool(ctx, cTrans, "hello_world")
	if err != nil {
		t.Fatalf("CallTool error: %v", err)
	}
	if output != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got %q", output)
	}
}
