import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestRun(t *testing.T) {
	ctx := context.Background()

	server := mcp.NewServer(&mcp.Implementation{Name: "test-server"}, nil)
	mcp.AddTool(server, &mcp.Tool{Name: "hello_world"}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{&mcp.TextContent{Text: "Hello, MCP World!"}},
		}, nil, nil
	})

	t1, t2 := mcp.NewInMemoryTransports()

	// Start server connection in background
	go func() {
		_, _ = server.Connect(ctx, t1, nil)
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)

	// Test ListTools
	err := Run(ctx, client, t2, true, "")
	if err != nil {
		t.Fatalf("Run failed: %v", err)
	}

	// Test CallTool
	t3, t4 := mcp.NewInMemoryTransports()
	go func() {
		_, _ = server.Connect(ctx, t3, nil)
	}()
	err = Run(ctx, client, t4, false, "hello_world")
	if err != nil {
		t.Fatalf("Run failed: %v", err)
	}
}
