{"content":"package client

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-hello-world/pkg/hello"
)

func TestClientRunner_Run(t *testing.T) {
	ctx := context.Background()

	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	server := hello.SetupServer()
	go server.Run(ctx, serverTransport)

	cr := &ClientRunner{
		Transport: clientTransport,
	}

	// Test list tools
	err := cr.Run(ctx, true, "")
	if err != nil {
		t.Fatalf("Run(listTools=true) failed: %v", err)
	}

	// Test call tool
	err = cr.Run(ctx, false, "hello_world")
	if err != nil {
		t.Fatalf("Run(callTool=hello_world) failed: %v", err)
	}
}
","filename":"pkg/client/client_test.go"}

{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server", "./bin/server", "Path to server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	cmd := exec.Command(*serverPath)
	transport := &mcp.CommandTransport{Command: cmd}

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	cs, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer cs.Close()

	if *listTools {
		tools := cs.Tools(ctx, nil)
		fmt.Println("tools:")
		for tool, err := range tools {
			if err != nil {
				log.Fatalf("Error listing tools: %v", err)
			}
			fmt.Printf("\t%s\n", tool.Name)
		}
	}

	if *callTool != "" {
		result, err := cs.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			log.Fatalf("Error calling tool: %v", err)
		}

		for _, content := range result.Content {
			if tc, ok := content.(*mcp.TextContent); ok {
				fmt.Println(tc.Text)
			}
		}
	}
}
","filename":"cmd/client/main.go"}

