{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"os"
	"os/exec"

	"mcp-server/internal/clientlib"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "")
	callTool := flag.String("call-tool", "", "")
	flag.Parse()

	serverPath := "./bin/server"
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		serverPath = "./server"
	}

	transport := &mcp.CommandTransport{Command: exec.Command(serverPath)}
	app := clientlib.NewClientApp()
	ctx := context.Background()

	if *listTools {
		names, _ := app.ListTools(ctx, transport)
		for _, name := range names {
			fmt.Println(name)
		}
	} else if *callTool != "" {
		output, _ := app.CallTool(ctx, transport, *callTool)
		fmt.Println(output)
	}
}
