{"content":"package client

import (
	"context"
	"fmt"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
}

func NewClient() *Client {
	return &Client{
		mcpClient: mcp.NewClient(&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		}, nil),
	}
}

func (c *Client) ListTools(ctx context.Context, transport mcp.Transport) ([]string, error) {
	cs, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}
	defer cs.Close()

	var toolNames []string
	tools := cs.Tools(ctx, nil)
	for t, err := range tools {
		if err != nil {
			return nil, err
		}
		toolNames = append(toolNames, t.Name)
	}
	return toolNames, nil
}

func (c *Client) CallTool(ctx context.Context, transport mcp.Transport, toolName string) (string, error) {
	cs, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return "", err
	}
	defer cs.Close()

	result, err := cs.CallTool(ctx, &mcp.CallToolParams{
		Name: toolName,
	})
	if err != nil {
		return "", err
	}

	var output string
	for _, content := range result.Content {
		if tc, ok := content.(*mcp.TextContent); ok {
			output += tc.Text
		}
	}
	return output, nil
}
