{"content":"package client

import (
	"context"
	"fmt"
	"io"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type App struct {
	Client *mcp.Client
	Stdout io.Writer
}

func NewApp(stdout io.Writer) *App {
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)
	return &App{
		Client: client,
		Stdout: stdout,
	}
}

func (a *App) Run(ctx context.Context, transport mcp.Transport, listTools bool, callTool string) error {
	cs, err := a.Client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer cs.Close()

	if listTools {
		tools := cs.Tools(ctx, nil)
		fmt.Fprintln(a.Stdout, "tools:")
		for tool, err := range tools {
			if err != nil {
				return fmt.Errorf("error listing tools: %w", err)
			}
			fmt.Fprintf(a.Stdout, "\t%s\n", tool.Name)
		}
	}

	if callTool != "" {
		result, err := cs.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("error calling tool: %w", err)
		}

		for _, content := range result.Content {
			if tc, ok := content.(*mcp.TextContent); ok {
				fmt.Fprintln(a.Stdout, tc.Text)
			}
		}
	}

	return nil
}
","filename":"pkg/client/client.go"}

{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-hello-world/internal/client"
)

func main() {
	listTools := flag.Bool("list-tools", false, "list all available tools")
	callTool := flag.String("call-tool", "", "call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	cmd := exec.Command("./bin/server")
	transport := &mcp.CommandTransport{Command: cmd}

	c := client.NewClient()

	if *listTools {
		tools, err := c.ListTools(ctx, transport)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, name := range tools {
			fmt.Println(name)
		}
	}

	if *callTool != "" {
		output, err := c.CallTool(ctx, transport, *callTool)
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		fmt.Println(output)
	}
}
