{"content":"package client

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-hello-world/internal/server"
)

func TestClient(t *testing.T) {
	ctx := context.Background()
	s := server.NewHelloServer()

	// Create a pair of transports for in-memory communication
	serverTransport, clientTransport := mcp.InMemoryTransport()

	// Run the server in a goroutine
	go func() {
		if err := s.Run(ctx, serverTransport); err != nil {
			// This might happen on close, so don't fail the test necessarily
		}
	}()

	c := NewClient()

	t.Run("ListTools", func(t *testing.T) {
		tools, err := c.ListTools(ctx, clientTransport)
		if err != nil {
			t.Fatalf("failed to list tools: %v", err)
		}
		found := false
		for _, name := range tools {
			if name == "hello_world" {
				found = true
				break
			}
		}
		if !found {
			t.Error("hello_world tool not found in list")
		}
	})

	// We need a new connection/transport for the next call because Connect closes the transport?
	// Actually, let's check if Connect closes the transport.
	// In the client implementation I deferred cs.Close() which might close the transport.
}

func TestClientCall(t *testing.T) {
	ctx := context.Background()
	s := server.NewHelloServer()
	serverTransport, clientTransport := mcp.InMemoryTransport()

	go func() {
		_ = s.Run(ctx, serverTransport)
	}()

	c := NewClient()

	t.Run("CallTool", func(t *testing.T) {
		output, err := c.CallTool(ctx, clientTransport, "hello_world")
		if err != nil {
			t.Fatalf("failed to call tool: %v", err)
		}
		if output != "Hello, MCP World!" {
			t.Errorf("expected 'Hello, MCP World!', got %q", output)
		}
	})
}
