import (
	"bytes"
	"context"
	"strings"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/example/mcp-hello-world/pkg/server"
)

func TestApp_Run(t *testing.T) {
	ctx := context.Background()
	s := server.NewHelloServer()

	// Create in-memory transport
	c2s, s2c := mcp.MemoryTransport()

	// Start server in goroutine
	go func() {
		if err := s.Run(ctx, s2c); err != nil && !strings.Contains(err.Error(), "closed") {
			// Ignore closed error on shutdown
		}
	}()

	t.Run("list-tools", func(t *testing.T) {
		var stdout bytes.Buffer
		app := NewApp(&stdout)
		err := app.Run(ctx, c2s, true, "")
		if err != nil {
			t.Fatalf("Run failed: %v", err)
		}
		if !strings.Contains(stdout.String(), "hello_world") {
			t.Errorf("expected stdout to contain hello_world, got %q", stdout.String())
		}
	})

	// Re-establish connection for second test as Run closes it
	c2s, s2c = mcp.MemoryTransport()
	go func() {
		if err := s.Run(ctx, s2c); err != nil && !strings.Contains(err.Error(), "closed") {
		}
	}()

	t.Run("call-tool", func(t *testing.T) {
		var stdout bytes.Buffer
		app := NewApp(&stdout)
		err := app.Run(ctx, c2s, false, "hello_world")
		if err != nil {
			t.Fatalf("Run failed: %v", err)
		}
		if !strings.Contains(stdout.String(), "Hello, MCP World!") {
			t.Errorf("expected stdout to contain Hello, MCP World!, got %q", stdout.String())
		}
	})
}
