{"content":"package client

import (
	"context"
	"fmt"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type CLI struct {
	ListTools bool
	CallTool  string
}

func (cli *CLI) Run(ctx context.Context) error {
	if !cli.ListTools && cli.CallTool == "" {
		return fmt.Errorf("either --list-tools or --call-tool must be provided")
	}

	cmd := exec.Command("./bin/server")
	transport := &mcp.CommandTransport{Command: cmd}

	c := NewClient()

	if cli.ListTools {
		tools, err := c.ListTools(ctx, transport)
		if err != nil {
			return fmt.Errorf("failed to list tools: %v", err)
		}
		for _, name := range tools {
			fmt.Println(name)
		}
	}

	if cli.CallTool != "" {
		output, err := c.CallTool(ctx, transport, cli.CallTool)
		if err != nil {
			return fmt.Errorf("failed to call tool: %v", err)
		}
		fmt.Println(output)
	}

	return nil
}
