{"content":"package server

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestIntegration(t *testing.T) {
	ctx := context.Background()
	s := NewHelloServer()

	c := mcp.NewClient(&mcp.Implementation{
		Name:    "test-client",
		Version: "1.0.0",
	}, nil)

	t1, t2 := mcp.NewInMemoryTransports()

	go func() {
		if _, err := s.Connect(ctx, t1, nil); err != nil {
			// In a real test we might want to communicate this error back
		}
	}()

	session, err := c.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	// Test ListTools
	found := false
	for tool, err := range session.Tools(ctx, nil) {
		if err != nil {
			t.Fatalf("Failed to list tools: %v", err)
		}
		if tool.Name == "hello_world" {
			found = true
		}
	}
	if !found {
		t.Error("Tool hello_world not found")
	}

	// Test CallTool
	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("Failed to call tool: %v", err)
	}

	if len(res.Content) != 1 {
		t.Fatalf("Expected 1 content item, got %d", len(res.Content))
	}

	tc, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", res.Content[0])
	}

	expected := "Hello, MCP World!"
	if tc.Text != expected {
		t.Errorf("Expected %q, got %q", expected, tc.Text)
	}
}
