{"content":"package main

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldTool(t *testing.T) {
	ctx := context.Background()

	// Create server
	s := mcp.NewServer(&mcp.Implementation{
		Name:    "test-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(s, &mcp.Tool{
		Name: "hello_world",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				&mcp.TextContent{Text: "Hello, MCP World!"},
			},
		}, nil, nil
	})

	// Create client
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "test-client",
		Version: "1.0.0",
	}, nil)

	// In-memory transports
	t1, t2 := mcp.NewInMemoryTransports()

	// Connect server
	serverSession, err := s.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatalf("Failed to connect server: %v", err)
	}
	defer serverSession.Close()

	// Connect client
	clientSession, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("Failed to connect client: %v", err)
	}
	defer clientSession.Close()

	// List tools
	tools, err := clientSession.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("Failed to list tools: %v", err)
	}

	found := false
	for _, tool := range tools.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("hello_world tool not found")
	}

	// Call tool
	result, err := clientSession.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("Failed to call tool: %v", err)
	}

	if len(result.Content) != 1 {
		t.Fatalf("Expected 1 content, got %d", len(result.Content))
	}

	tc, ok := result.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", result.Content[0])
	}

	if tc.Text != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got %q", tc.Text)
	}
}
