import (
	"context"
	"fmt"
	"io"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func ListTools(ctx context.Context, session *mcp.ClientSession, out io.Writer) error {
	for tool, err := range session.Tools(ctx, nil) {
		if err != nil {
			return err
		}
		fmt.Fprintln(out, tool.Name)
	}
	return nil
}

func CallTool(ctx context.Context, session *mcp.ClientSession, toolName string, out io.Writer) error {
	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: toolName,
	})
	if err != nil {
		return err
	}

	for _, content := range result.Content {
		if tc, ok := content.(*mcp.TextContent); ok {
			fmt.Fprintln(out, tc.Text)
		}
	}
	return nil
}
