	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	c := client.NewClient()
	if err := c.Run(context.Background(), *serverPath, *listTools, *callTool); err != nil {
		log.Fatal(err)
	}
}
