func TestClient(t *testing.T) {
	ctx := context.Background()
	s := server.NewHelloServer()

	t1, t2 := mcp.NewInMemoryTransports()

	// Start server in background
	go func() {
		_, err := s.Connect(ctx, t1, nil)
		if err != nil {
			// In a test, we can't easily return this error but Connect 
			// should work if transports are fine.
		}
	}()

	c := NewClient()

	// Test listing tools
	err := c.RunWithTransport(ctx, t2, true, "")
	if err != nil {
		t.Fatalf("RunWithTransport failed: %v", err)
	}

	// Test calling tool
	err = c.RunWithTransport(ctx, t2, false, "hello_world")
	if err != nil {
		t.Fatalf("RunWithTransport failed: %v", err)
	}
}
