func Run(ctx context.Context, args []string, out io.Writer) error {
	fs := flag.NewFlagSet("client", flag.ContinueOnError)
	listTools := fs.Bool("list-tools", false, "List all available tools")
	callTool := fs.String("call-tool", "", "Call a tool by name")
	serverPath := fs.String("server", "./bin/server", "Path to the server binary")
	if err := fs.Parse(args); err != nil {
		return err
	}

	if !*listTools && *callTool == "" {
		return fmt.Errorf("either -list-tools or -call-tool must be provided")
	}

	mcpClient := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	transport := &mcp.CommandTransport{
		Command: exec.CommandContext(ctx, *serverPath),
	}

	session, err := mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if *listTools {
		if err := client.ListTools(ctx, session, out); err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
	}

	if *callTool != "" {
		if err := client.CallTool(ctx, session, *callTool, out); err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
	}
	return nil
