func TestRunClient(t *testing.T) {
	// Build the server binary first for the test
	tmpDir, err := os.MkdirTemp("", "mcp-test")
	if err != nil {
		t.Fatal(err)
	}
	defer os.RemoveAll(tmpDir)

	serverPath := filepath.Join(tmpDir, "server")

	// We need to go up to the root to build the server
	cmd := exec.Command("go", "build", "-o", serverPath, "../../cmd/server/main.go")
	if output, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("failed to build server: %v, output: %s", err, output)
	}

	ctx := context.Background()

	t.Run("ListTools", func(t *testing.T) {
		config := ClientConfig{
			ServerPath: serverPath,
			ListTools:  true,
