	t.Run("CallTool", func(t *testing.T) {
		config := ClientConfig{
			ServerPath: serverPath,
			CallTool:   "hello_world",
		}
		if err := RunClient(ctx, config); err != nil {
			t.Errorf("RunClient failed: %v", err)
		}
	})
}
