func TestRun(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	s := server.NewHelloServer()
	t1, t2 := mcp.NewInMemoryTransports()

	go func() {
		if _, err := s.Connect(ctx, t1, nil); err != nil {
			// error
		}
	}()

	factory := func(ctx context.Context, serverPath string) mcp.Transport {
		return t2
	}

	t.Run("ListTools", func(t *testing.T) {
		var out bytes.Buffer
		err := Run(ctx, []string{"-list-tools"}, &out, factory)
		if err != nil {
			t.Fatalf("Run failed: %v", err)
		}
		if !strings.Contains(out.String(), "hello_world") {
			t.Errorf("Expected output to contain hello_world, got %q", out.String())
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		var out bytes.Buffer
		err := Run(ctx, []string{"-call-tool", "hello_world"}, &out, factory)
		if err != nil {
			t.Fatalf("Run failed: %v", err)
		}
		if !strings.Contains(out.String(), "Hello, MCP World!") {
			t.Errorf("Expected output to contain Hello, MCP World!, got %q", out.String())
		}
	})
}
