{"content":"package main

import (
	"bytes"
	"context"
	"strings"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestRunClient(t *testing.T) {
	ctx := context.Background()
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	server := mcp.NewServer(&mcp.Implementation{Name: "test-server"}, nil)
	mcp.AddTool(server, &mcp.Tool{
		Name: "hello_world",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args struct{}) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{&mcp.TextContent{Text: "Hello, MCP World!"}},
		}, nil, nil
	})

	go func() {
		if err := server.Run(ctx, serverTransport); err != nil {
			// ignore error in test
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)
	session, err := client.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	t.Run("ListTools", func(t *testing.T) {
		var out bytes.Buffer
		err := RunClient(ctx, session, true, "", &out)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
		if !strings.Contains(out.String(), "hello_world") {
			t.Errorf("Expected hello_world in output, got %q", out.String())
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		var out bytes.Buffer
		err := RunClient(ctx, session, false, "hello_world", &out)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
		if !strings.Contains(out.String(), "Hello, MCP World!") {
			t.Errorf("Expected greeting in output, got %q", out.String())
		}
	})

	t.Run("CallNonExistentTool", func(t *testing.T) {
		var out bytes.Buffer
		err := RunClient(ctx, session, false, "non_existent", &out)
		if err == nil {
			t.Fatal("Expected error for non-existent tool, got nil")
		}
	})

	t.Run("RunMainListTools", func(t *testing.T) {
		var out bytes.Buffer
		err := run([]string{"--list-tools"}, &out)
		if err != nil {
			t.Fatalf("run failed: %v", err)
		}
		if !strings.Contains(out.String(), "hello_world") {
			t.Errorf("Expected hello_world in output, got %q", out.String())
		}
	})
}
