{"content":"package main

import (
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()

	// We assume the server binary is at ./bin/server
	cmd := exec.Command("./bin/server")
	transport := &mcp.CommandTransport{Command: cmd}

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-world-client",
		Version: "1.0.0",
	}, nil)

	cs, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer cs.Close()

	if *listTools {
		tools := cs.Tools(ctx, nil)
		for t, err := range tools {
			if err != nil {
				log.Fatalf("Error listing tools: %v", err)
			}
			fmt.Println(t.Name)
		}
	}

	if *callTool != "" {
		result, err := cs.Call(ctx, &mcp.CallToolRequest{
			Params: struct {
				Name      string `json:"name"`
				Arguments any    `json:"arguments,omitempty"`
			}{
				Name: *callTool,
			},
		})
		if err != nil {
			log.Fatalf("Error calling tool: %v", err)
		}

		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			} else {
				// Handle other content types if necessary
				data, _ := json.Marshal(content)
				fmt.Println(string(data))
			}
		}
	}
}
","filename":"cmd/client/main.go"}

