{"content":"package main

import (
	"context"
	"fmt"
	"os"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
}

func run() error {
	ctx := context.Background()

	// Create a server
	s := mcp.NewServer(
		&mcp.Implementation{
			Name:    "hello-world-server",
			Version: "1.0.0",
		},
		nil,
	)

	// Add the hello_world tool
	s.AddTool(&mcp.Tool{
		Name:        "hello_world",
		Description: "A tool that returns 'Hello, MCP World!'",
		InputSchema: mcp.EmptySchema,
	}, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				&mcp.TextContent{
					Text: "Hello, MCP World!",
				},
			},
		}, nil
	})

	// Serve over stdio transport
	transport := &mcp.StdioTransport{}
	ss, err := s.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	defer ss.Close()

	// Wait for the session to be closed
	<-ss.Done()
	return nil
}
