{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	if err := run(*listTools, *callTool); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
}

func run(listTools bool, toolName string) error {
	ctx := context.Background()

	// Use the current binary's directory to find the server
	// In production, you might want to specify the path to the server binary
	serverPath := "./bin/server"
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		return fmt.Errorf("server binary not found at %s. Please build it first", serverPath)
	}

	transport := &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}

	c := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "1.0.0",
		},
		nil,
	)

	session, err := c.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	defer session.Close()

	if listTools {
		for t, err := range session.Tools(ctx, nil) {
			if err != nil {
				return err
			}
			fmt.Println(t.Name)
		}
	}

	if toolName != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: toolName,
		})
		if err != nil {
			return err
		}
		for _, content := range res.Content {
			if tc, ok := content.(*mcp.TextContent); ok {
				fmt.Println(tc.Text)
			}
		}
	}

	return nil
}
