{"content":"package client

import (
	"context"
	"fmt"
	"log"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func HandleClient(ctx context.Context, transport mcp.Transport, listTools bool, callTool string) error {
	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "1.0.0",
		},
		nil,
	)

	cs, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer cs.Close()

	if listTools {
		for tool, err := range cs.Tools(ctx, nil) {
			if err != nil {
				return fmt.Errorf("error listing tools: %w", err)
			}
			fmt.Println(tool.Name)
		}
	}

	if callTool != "" {
		res, err := cs.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("error calling tool: %w", err)
		}
		for _, content := range res.Content {
			if tc, ok := content.(*mcp.TextContent); ok {
				fmt.Println(tc.Text)
			}
		}
	}
	return nil
}
