			},
		}, nil
	})"}

{"content":"package server

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldHandler(t *testing.T) {
	ctx := context.Background()
	req := &mcp.CallToolRequest{}
	res, err := HelloWorldHandler(ctx, req)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if len(res.Content) != 1 {
		t.Fatalf("expected 1 content item, got %d", len(res.Content))
	}

	tc, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatal("expected text content")
	}

	if tc.Text != "Hello, MCP World!" {
		t.Errorf("expected 'Hello, MCP World!', got %q", tc.Text)
	}
}

func TestNewHelloWorldServer(t *testing.T) {
	s := NewHelloWorldServer()
	if s == nil {
		t.Fatal("expected server to be non-nil")
	}

	// We can't easily inspect the tools registered in s because they are internal to mcp.Server
	// but we can try to connect and call it.
	ctx := context.Background()
	t1, t2 := mcp.NewInMemoryTransports()

	ss, err := s.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatalf("failed to connect server: %v", err)
	}
	defer ss.Close()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "1.0.0"}, nil)
	cs, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("failed to connect client: %v", err)
	}
	defer cs.Close()

	// List tools
	found := false
	for tool, err := range cs.Tools(ctx, nil) {
		if err != nil {
			t.Fatalf("failed to list tools: %v", err)
		}
		if tool.Name == "hello_world" {
			found = true
		}
	}
	if !found {
		t.Error("hello_world tool not found")
	}

	// Call tool
	res, err := cs.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("failed to call tool: %v", err)
	}

	if len(res.Content) != 1 {
		t.Fatalf("expected 1 content item, got %d", len(res.Content))
	}

	tc, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatal("expected text content")
	}

	if tc.Text != "Hello, MCP World!" {
		t.Errorf("expected 'Hello, MCP World!', got %q", tc.Text)
	}
}
