{
	ctx := context.Background()

	resources := map[string]string{
		"file:///a":		"a",
		"file:///dir/x":	"x",
		"file:///dir/y":	"y",
	}

	handler := func(_ context.Context, req *mcp.ReadResourceRequest) (*mcp.ReadResourceResult, error) {
