{"content":"package clientlib

import (
	"context"
	"os"
	"path/filepath"
	"testing"
)

func TestRunClient(t *testing.T) {
	// We need the server binary to be built and located at ../../bin/server
	// For the test, we can assume it's already built by the previous step in the workflow.

	// Get absolute path to the server binary
	cwd, _ := os.Getwd()
	serverPath := filepath.Join(cwd, "../../bin/server")

	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		t.Skip("Server binary not found, skipping integration test")
	}

	ctx := context.Background()

	t.Run("ListTools", func(t *testing.T) {
		err := RunClient(ctx, serverPath, true, "")
		if err != nil {
			t.Errorf("RunClient(listTools=true) failed: %v", err)
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		err := RunClient(ctx, serverPath, false, "hello_world")
		if err != nil {
			t.Errorf("RunClient(callTool=hello_world) failed: %v", err)
		}
	})

	t.Run("InvalidTool", func(t *testing.T) {
		err := RunClient(ctx, serverPath, false, "non_existent")
		if err == nil {
			t.Error("Expected error for non-existent tool, got nil")
		}
	})
}
","filename":"pkg/clientlib/clientlib_test.go"}

{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		return
	}

	ctx := context.Background()
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-world-client",
		Version: "v1.0.0",
	}, nil)

	transport := &mcp.CommandTransport{
		Command: exec.Command("./bin/server"),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	if *listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}

		for _, content := range res.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
}
","filename":"cmd/client/main.go"}

