{"content":"package server

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldHandler(t *testing.T) {
	ctx := context.Background()
	res, _, err := HelloWorldHandler(ctx, nil, nil)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if len(res.Content) != 1 {
		t.Fatalf("expected 1 content item, got %d", len(res.Content))
	}

	text, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("expected TextContent, got %T", res.Content[0])
	}

	if text.Text != "Hello, MCP World!" {
		t.Errorf("expected 'Hello, MCP World!', got '%s'", text.Text)
	}
}

func TestServerIntegration(t *testing.T) {
	ctx := context.Background()
	s := NewHelloWorldServer()

	t1, t2 := mcp.NewInMemoryTransports()

	go func() {
		if err := s.Connect(ctx, t1, nil); err != nil {
			// In a test we might not be able to log easily if it's in a goroutine
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)
	session, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("failed to connect: %v", err)
	}
	defer session.Close()

	tools, err := session.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("failed to list tools: %v", err)
	}

	found := false
	for _, tool := range tools.Tools {
