{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
	session   *mcp.ClientSession
}

func NewClient(name string) *Client {
	return &Client{
		mcpClient: mcp.NewClient(&mcp.Implementation{
			Name:    name,
			Version: "v1.0.0",
		}, nil),
	}
}

func (c *Client) Connect(ctx context.Context, serverPath string) error {
	transport := &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}
	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	c.session = session
	return nil
}

func (c *Client) ConnectTransport(ctx context.Context, transport mcp.Transport) error {
	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	c.session = session
	return nil
}

func (c *Client) Close() error {
	if c.session != nil {
		return c.session.Close()
	}
	return nil
}

func (c *Client) ListTools(ctx context.Context) ([]string, error) {
	tools, err := c.session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, t := range tools.Tools {
		names = append(names, t.Name)
	}
	return names, nil
}

func (c *Client) CallTool(ctx context.Context, name string) (string, error) {
	res, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return "", err
	}

	var result string
	for _, content := range res.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			result += text.Text
		}
	}
	return result, nil
}
","filename":"pkg/client/client.go"}

{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"

	"github.com/example/mcp-hello-world/pkg/client"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		return
	}

	ctx := context.Background()
	c := client.NewClient("hello-world-client")

	if err := c.Connect(ctx, "./bin/server"); err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer c.Close()

	if *listTools {
		names, err := c.ListTools(ctx)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, name := range names {
			fmt.Println(name)
		}
	}

	if *callTool != "" {
		res, err := c.CallTool(ctx, *callTool)
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		fmt.Println(res)
	}
}
