func TestRunClient(t *testing.T) {
	// Find the server binary. It should be in ../../bin/server relative to this file
	// or in ./bin/server relative to project root.
	// We'll try to find it relative to the current working directory.

	serverPath := "../../bin/server"
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		// Try another path
		serverPath = "./bin/server"
		if _, err := os.Stat(serverPath); os.IsNotExist(err) {
            // Last resort: try to find it from root
            cwd, _ := os.Getwd()
            t.Logf("CWD: %s", cwd)
			t.Skip("server binary not found, skipping integration test")
		}
	}

    absServerPath, err := filepath.Abs(serverPath)
    if err != nil {
        t.Fatalf("failed to get absolute path: %v", err)
    }

	ctx := context.Background()

	t.Run("list-tools", func(t *testing.T) {
		err := RunClient(ctx, absServerPath, true, "")
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
	})

	t.Run("call-tool", func(t *testing.T) {
		err := RunClient(ctx, absServerPath, false, "hello_world")
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
	})
}
