{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	// Start the server subprocess
	// We assume the server binary is at ./bin/server relative to where client is run
	cmd := exec.Command("./bin/server")
	stdin, err := cmd.StdinPipe()
	if err != nil {
		log.Fatalf("Failed to get stdin pipe: %v", err)
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		log.Fatalf("Failed to get stdout pipe: %v", err)
	}
	// Redirect server's stderr to our stderr so we can see any errors
	cmd.Stderr = os.Stderr

	if err := cmd.Start(); err != nil {
		log.Fatalf("Failed to start server: %v", err)
	}
	defer func() {
		_ = cmd.Process.Kill()
	}()

	ctx := context.Background()
	transport := &mcp.IOTransport{
		Reader: stdout,
		Writer: stdin,
	}

	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "1.0.0",
		},
		nil,
	)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	if *listTools {
		result, err := session.ListTools(ctx, nil)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, tool := range result.Tools {
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		for _, content := range result.Content {
			if tc, ok := content.(*mcp.TextContent); ok {
				fmt.Println(tc.Text)
			}
		}
	}
}
