func TestNewHelloServer(t *testing.T) {
	server := NewHelloServer()
	if server == nil {
		t.Fatal("expected server to be non-nil")
	}

	ctx := context.Background()

	// Test if tool exists
	tools := server.ListTools(ctx, nil)
	found := false
	for tool, err := range tools {
		if err != nil {
			t.Fatalf("error listing tools: %v", err)
		}
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}

	if !found {
		t.Error("expected tool 'hello_world' not found")
	}

	// Test calling the tool
	// We need to use the handler directly or via a session.
	// Since we are testing the server logic, let's see how AddTool works.
	// It registers a handler in the server.
}
