import (
	"context"
	"os"
	"path/filepath"
	"testing"
)

func TestRunClient(t *testing.T) {
	// We need the server binary to be built. 
	// Since go test runs in the directory of the test file, 
	// and we built it in bin/server (relative to project root),
	// we need to find it.

	wd, _ := os.Getwd()
	// Project root is one level up from cmd/client
	serverPath := filepath.Join(wd, "..", "..", "bin", "server")

	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		t.Skipf("Server binary not found at %s, skip client test", serverPath)
	}

	ctx := context.Background()

	t.Run("ListTools", func(t *testing.T) {
		err := runClient(ctx, serverPath, true, "")
		if err != nil {
			t.Fatalf("runClient failed: %v", err)
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		err := runClient(ctx, serverPath, false, "hello_world")
		if err != nil {
			t.Fatalf("runClient failed: %v", err)
		}
	})
}
