{"content":"package main

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloTool(t *testing.T) {
	ctx := context.Background()
	server := NewHelloServer()

	t1, t2 := mcp.NewInMemoryTransports()

	// Start server on t1
	go func() {
		if _, err := server.Connect(ctx, t1, nil); err != nil {
			panic(err)
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "1.0.0"}, nil)
	session, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("Failed to call tool: %v", err)
	}

	if len(res.Content) != 1 {
		t.Fatalf("Expected 1 content item, got %d", len(res.Content))
	}

	text, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", res.Content[0])
	}

	expected := "Hello, MCP World!"
	if text.Text != expected {
		t.Errorf("Expected %q, got %q", expected, text.Text)
	}
}

func TestListTools(t *testing.T) {
	ctx := context.Background()
	server := NewHelloServer()

	t1, t2 := mcp.NewInMemoryTransports()

	go func() {
		if _, err := server.Connect(ctx, t1, nil); err != nil {
			panic(err)
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "1.0.0"}, nil)
	session, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	found := false
	for tool, err := range session.Tools(ctx, nil) {
		if err != nil {
			t.Fatalf("Error listing tools: %v", err)
		}
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}

	if !found {
		t.Error("Tool hello_world not found")
	}
}
