{"filename":"cmd/client/main.go","new_content":"func RunClient(ctx context.Context, listTools bool, callTool string, serverPath string) error {
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "example-client",
		Version: "1.0.0",
	}, nil)

	transport := &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if listTools {
		for tool, err := range session.Tools(ctx, nil) {
			if err != nil {
				return fmt.Errorf("failed to list tools: %w", err)
			}
			fmt.Println(tool.Name)
		}
	}

	if callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}

		for _, content := range res.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
	return nil
}

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	if err := RunClient(context.Background(), *listTools, *callTool, "./bin/server"); err != nil {
		log.Fatal(err)
	}
}
