{"content":"package main

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldTool(t *testing.T) {
	server := SetupServer()
	ctx := context.Background()

	// We can use InMemoryTransport to test the server
	t1, t2 := mcp.NewInMemoryTransports()

	go func() {
		if err := server.Run(ctx, t1); err != nil {
			// t.Errorf might be called after test finished if we are not careful
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)
	session, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("Failed to call tool: %v", err)
	}

	if len(result.Content) != 1 {
		t.Fatalf("Expected 1 content, got %d", len(result.Content))
	}

	text, ok := result.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", result.Content[0])
	}

	if text.Text != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got '%s'", text.Text)
	}
}
