{"content":"package client

import (
	"context"
	"fmt"
	"io"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func RunClient(ctx context.Context, transport mcp.Transport, listTools bool, callTool string, out io.Writer) error {
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-world-client",
		Version: "1.0.0",
	}, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if listTools {
		tools := session.Tools(ctx, nil)
		fmt.Fprintln(out, "tools:")
		for tool, err := range tools {
			if err != nil {
				return fmt.Errorf("error listing tools: %w", err)
			}
			fmt.Fprintf(out, "\t%s\n", tool.Name)
		}
	}

	if callTool != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("error calling tool: %w", err)
		}

		for _, content := range result.Content {
			if tc, ok := content.(*mcp.TextContent); ok {
				fmt.Fprintln(out, tc.Text)
			}
		}
	}

	return nil
}
