{"filename":"cmd/client/main.go","new_content":"func RunClient(ctx context.Context, serverPath string, listTools bool, callTool string) error {
	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		},
		nil,
	)

	transport := &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if callTool != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range result.Content {
			if textPtr, ok := content.(*mcp.TextContent); ok {
				fmt.Println(textPtr.Text)
			}
		}
	}
	return nil
}

