{"content":"package main

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
)

func TestRunClient(t *testing.T) {
	// We need to build the server binary first if it doesn't exist
	serverPath := filepath.Join("..", "..", "bin", "server")
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		cmd := exec.Command("go", "build", "-o", serverPath, "../server/main.go")
		if err := cmd.Run(); err != nil {
			t.Fatalf("Failed to build server for test: %v", err)
		}
	}

	ctx := context.Background()

	t.Run("ListTools", func(t *testing.T) {
		err := RunClient(ctx, serverPath, true, "")
		if err != nil {
			t.Errorf("RunClient failed for ListTools: %v", err)
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		err := RunClient(ctx, serverPath, false, "hello_world")
		if err != nil {
			t.Errorf("RunClient failed for CallTool: %v", err)
		}
	})

	t.Run("CallNonExistentTool", func(t *testing.T) {
		err := RunClient(ctx, serverPath, false, "non_existent")
		if err == nil {
			t.Error("Expected error calling non-existent tool, got nil")
		}
	})
}
