{"content":"package client

import (
	"bytes"
	"context"
	"strings"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// MockServer is a simple MCP server for testing
func newMockServer() *mcp.Server {
	server := mcp.NewServer(&mcp.Implementation{Name: "mock", Version: "1.0.0"}, nil)
	type emptyArgs struct{}
	mcp.AddTool(server, &mcp.Tool{
		Name: "test_tool",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args emptyArgs) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{&mcp.TextContent{Text: "mock response"}},
		}, nil, nil
	})
	return server
}

func TestRunClient_ListTools(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	s1, s2 := mcp.NewInMemoryTransports()
	server := newMockServer()

	go func() {
		_ = server.Run(ctx, s1)
	}()

	var out bytes.Buffer
	err := RunClient(ctx, s2, true, "", &out)
	if err != nil {
		t.Fatalf("RunClient failed: %v", err)
	}

	if !strings.Contains(out.String(), "test_tool") {
		t.Errorf("expected output to contain 'test_tool', got %q", out.String())
	}
}

func TestRunClient_CallTool(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	s1, s2 := mcp.NewInMemoryTransports()
	server := newMockServer()

	go func() {
		_ = server.Run(ctx, s1)
	}()

	var out bytes.Buffer
	err := RunClient(ctx, s2, false, "test_tool", &out)
	if err != nil {
		t.Fatalf("RunClient failed: %v", err)
	}

	if !strings.Contains(out.String(), "mock response") {
		t.Errorf("expected output to contain 'mock response', got %q", out.String())
	}
}
