{"content":"package server

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloServer(t *testing.T) {
	s := NewHelloServer()
	ctx := context.Background()

	t1, t2 := mcp.NewInMemoryTransports()

	ss, err := s.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatalf("failed to connect: %v", err)
	}
	defer ss.Close()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)
	cs, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("failed to connect client: %v", err)
	}
	defer cs.Close()

	tools, err := cs.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("failed to list tools: %v", err)
	}

	found := false
	for _, tool := range tools.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("hello_world tool not found")
	}

	res, err := cs.CallTool(ctx, &mcp.CallToolParams{Name: "hello_world"})
	if err != nil {
		t.Fatalf("failed to call tool: %v", err)
	}

	if len(res.Content) != 1 {
		t.Fatalf("expected 1 content item, got %d", len(res.Content))
	}

	tc, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("expected TextContent, got %T", res.Content[0])
	}

	if tc.Text != "Hello, MCP World!" {
		t.Errorf("expected %q, got %q", "Hello, MCP World!", tc.Text)
	}
}
","filename":"pkg/server/server_test.go"}

{"content":"package main

import (
	"context"
	"log"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "hello-world-server",
		Version: "v1.0.0",
	}, nil)

	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns a hello world message",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				&mcp.TextContent{Text: "Hello, MCP World!"},
			},
		}, nil, nil
	})

	if err := server.Run(context.Background(), &mcp.StdioTransport{}); err != nil {
		log.Fatal(err)
	}
}
","filename":"cmd/server/main.go"}

{"content":"package mcp

import (
	"context"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func NewHelloServer() *mcp.Server {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "hello-server",
		Version: "v1.0.0",
	}, nil)

	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns a hello world message",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args struct{}) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				&mcp.TextContent{
					Text: "Hello, MCP World!",
				},
			},
		}, nil, nil
	})

	return server
}
