{"content":"package client

import (
	"context"
	"fmt"
	"io"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func RunClient(ctx context.Context, transport mcp.Transport, listTools bool, callTool string, out io.Writer) error {
	c := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		},
		nil,
	)

	session, err := c.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, tool := range tools.Tools {
			fmt.Fprintln(out, tool.Name)
		}
	}

	if callTool != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range result.Content {
			if tc, ok := content.(*mcp.TextContent); ok {
				fmt.Fprintln(out, tc.Text)
			}
		}
	}

	return nil
}
","filename":"pkg/client/client.go"}

{"content":"package main

import (
	"context"
	"flag"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-server-client/pkg/client"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	transport := &mcp.CommandTransport{
		Command: exec.Command(*serverPath),
	}

	if err := client.RunClient(context.Background(), transport, *listTools, *callTool, os.Stdout); err != nil {
		log.Fatal(err)
	}
}
","filename":"cmd/client/main.go"}

