{"content":"package client

import (
	"bytes"
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type mockServer struct {
	mcp.Server
}

func TestRunClient(t *testing.T) {
	ctx := context.Background()
	t1, t2 := mcp.NewInMemoryTransports()

	// Setup a minimal server to respond to the client
	s := mcp.NewServer(&mcp.Implementation{Name: "mock-server"}, nil)
	mcp.AddTool(s, &mcp.Tool{Name: "test_tool"}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{&mcp.TextContent{Text: "mock response"}},
		}, nil, nil
	})

	go func() {
		if _, err := s.Connect(ctx, t1, nil); err != nil {
			// Cannot t.Fatalf here since it's a goroutine
		}
	}()

	var out bytes.Buffer
	err := RunClient(ctx, t2, true, "test_tool", &out)
	if err != nil {
		t.Fatalf("RunClient failed: %v", err)
	}

	output := out.String()
	expectedTool := "test_tool\n"
	expectedResponse := "mock response\n"

	if !bytes.Contains(out.Bytes(), []byte("test_tool")) {
		t.Errorf("expected output to contain %q, got %q", expectedTool, output)
	}
	if !bytes.Contains(out.Bytes(), []byte("mock response")) {
		t.Errorf("expected output to contain %q, got %q", expectedResponse, output)
	}
}
