{"content":"package handler

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorld(t *testing.T) {
	ctx := context.Background()
	res, _, err := HelloWorld(ctx, nil, nil)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if len(res.Content) != 1 {
		t.Fatalf("expected 1 content, got %d", len(res.Content))
	}

	text, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("expected text content, got %T", res.Content[0])
	}

	expected := "Hello, MCP World!"
	if text.Text != expected {
		t.Errorf("expected %q, got %q", expected, text.Text)
	}
}
","filename":"internal/handler/handler_test.go"}

{"content":"package mcp

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloServer(t *testing.T) {
	server := NewHelloServer()
	if server == nil {
		t.Fatal("NewHelloServer returned nil")
	}

	// We can test the handler directly by connecting a client or just checking the tools
	ctx := context.Background()

	// Create a client and server and connect them via pipes to test the logic
	clientReader, serverWriter := mcp.Pipe()
	serverReader, clientWriter := mcp.Pipe()

	serverTransport := mcp.NewStdioTransport(serverReader, serverWriter)
	clientTransport := mcp.NewStdioTransport(clientReader, clientWriter)

	errCh := make(chan error, 1)
	go func() {
		errCh <- server.Run(ctx, serverTransport)
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "1.0.0"}, nil)
	session, err := client.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	// Test ListTools
	tools, err := session.Tools(ctx, nil)
	if err != nil {
		t.Fatalf("Failed to list tools: %v", err)
	}

	found := false
	for tool, err := range tools {
		if err != nil {
			t.Fatalf("Error iterating tools: %v", err)
		}
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("Tool 'hello_world' not found")
	}

	// Test CallTool
	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("Failed to call tool: %v", err)
	}

	if len(result.Content) != 1 {
		t.Fatalf("Expected 1 content item, got %d", len(result.Content))
	}

	textContent, ok := result.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", result.Content[0])
	}

	expected := "Hello, MCP World!"
	if textContent.Text != expected {
		t.Errorf("Expected %q, got %q", expected, textContent.Text)
	}
}
