	"os/exec"

	"github.com/example/mcp-hello/internal/mcp"
	mcpsdk "github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	cmd := exec.Command("./bin/server")
	transport := &mcpsdk.CommandTransport{Command: cmd}

	if err := mcp.RunClient(ctx, transport, *listTools, *callTool, os.Stdout); err != nil {
		log.Fatal(err)
	}
}
