{"content":"package mcp

import (
	"bytes"
	"context"
	"strings"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestRunClient(t *testing.T) {
	server := NewHelloServer()
	ctx := context.Background()
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	go func() {
		_ = server.Run(ctx, serverTransport)
	}()

	t.Run("ListTools", func(t *testing.T) {
		var out bytes.Buffer
		err := RunClient(ctx, clientTransport, true, "", &out)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
		if !strings.Contains(out.String(), "hello_world") {
			t.Errorf("Expected output to contain 'hello_world', got %q", out.String())
		}
	})

	// Reconnect because Connect closes the transport on session close
	serverTransport, clientTransport = mcp.NewInMemoryTransports()
	go func() {
		_ = server.Run(ctx, serverTransport)
	}()

	t.Run("CallTool", func(t *testing.T) {
		var out bytes.Buffer
		err := RunClient(ctx, clientTransport, false, "hello_world", &out)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
		if !strings.Contains(out.String(), "Hello, MCP World!") {
			t.Errorf("Expected output to contain 'Hello, MCP World!', got %q", out.String())
		}
	})
}
