{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/user/mcp-hello-world/pkg/client"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	c := client.NewClient("hello-client")

	transport := &mcp.CommandTransport{
		Command: exec.CommandContext(ctx, "./bin/server"),
	}

	if err := c.Connect(ctx, transport); err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer c.Close()

	if *listTools {
		tools, err := c.ListTools(ctx)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, name := range tools {
			fmt.Println(name)
		}
	}

	if *callTool != "" {
		output, err := c.CallTool(ctx, *callTool)
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		fmt.Println(output)
	}
}
