{"content":"package client

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/user/mcp-hello-world/pkg/server"
)

func TestClient(t *testing.T) {
	s := server.NewHelloServer()
	ctx := context.Background()
	clientTransport, serverTransport := mcp.NewInMemoryTransports()

	go func() {
		if err := s.Run(ctx, serverTransport); err != nil && err != mcp.ErrConnectionClosed {
			t.Errorf("Server run failed: %v", err)
		}
	}()

	c := NewClient("test-client")
	if err := c.Connect(ctx, clientTransport); err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer c.Close()

	tools, err := c.ListTools(ctx)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}

	found := false
	for _, name := range tools {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("hello_world tool not found")
	}

	output, err := c.CallTool(ctx, "hello_world")
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}

	if output != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got '%s'", output)
	}
}
