	// Using a closed transport or something that fails
	_, transport := mcp.NewInMemoryTransports()
	// if we don't start the other end, it might fail or hang.
	// Actually mcp.NewInMemoryTransports() returns two ends of a pipe.
	// If we close one, Connect should fail.
	transport.Close()

	err := c.Connect(ctx, transport)
	if err == nil {
