{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func RunClient(ctx context.Context, listTools bool, callTool string) error {
	c := NewClient("hello-client")

	transport := &mcp.CommandTransport{
		Command: exec.CommandContext(ctx, "./bin/server"),
	}

	if err := c.Connect(ctx, transport); err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer c.Close()

	if listTools {
		tools, err := c.ListTools(ctx)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, name := range tools {
			fmt.Println(name)
		}
	}

	if callTool != "" {
		output, err := c.CallTool(ctx, callTool)
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		fmt.Println(output)
	}
	return nil
}
