{"content":"package myclient

import (
	"context"
	"fmt"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func ListTools(ctx context.Context, cs *mcp.ClientSession) error {
	tools := cs.Tools(ctx, nil)
	for t, err := range tools {
		if err != nil {
			return err
		}
		fmt.Println(t.Name)
	}
	return nil
}

func CallTool(ctx context.Context, cs *mcp.ClientSession, toolName string) error {
	res, err := cs.CallTool(ctx, &mcp.CallToolParams{
		Name: toolName,
	})
	if err != nil {
		return err
	}

	if res.IsError {
		return fmt.Errorf("tool call returned error")
	}

	for _, content := range res.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			fmt.Println(text.Text)
		}
	}
	return nil
}
","file_path":"pkg/myclient/client.go"}

