{"content":"package main

import (
	"context"
	"flag"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-server-client/pkg/myclient"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	cmd := exec.Command("./bin/server")
	if _, err := os.Stat("./bin/server"); os.IsNotExist(err) {
		cmd = exec.Command("go", "run", "cmd/server/main.go")
	}

	transport := &mcp.CommandTransport{Command: cmd}
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "mcp-client",
		Version: "1.0.0",
	}, nil)

	cs, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer cs.Close()

	if *listTools {
		if err := myclient.ListTools(ctx, cs); err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
	}

	if *callTool != "" {
		if err := myclient.CallTool(ctx, cs, *callTool); err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
	}
}
