{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
	session   *mcp.Session
}

func NewClient(ctx context.Context, serverCommand string, serverArgs ...string) (*Client, error) {
	cmd := exec.Command(serverCommand, serverArgs...)
	transport := &mcp.CommandTransport{Command: cmd}
	mcpClient := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-world-client",
		Version: "1.0.0",
	}, nil)

	session, err := mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}

	return &Client{
		mcpClient: mcpClient,
		session:   session,
	}, nil
}

func (c *Client) Close() error {
	return c.session.Close()
}

func (c *Client) ListTools(ctx context.Context) ([]string, error) {
	var toolNames []string
	for tool, err := range c.session.Tools(ctx, nil) {
		if err != nil {
			return nil, err
		}
		toolNames = append(toolNames, tool.Name)
	}
	return toolNames, nil
}

func (c *Client) CallTool(ctx context.Context, name string) (string, error) {
	result, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return "", err
	}

	if len(result.Content) == 0 {
		return "", fmt.Errorf("no content in result")
	}

	textContent, ok := result.Content[0].(*mcp.TextContent)
	if !ok {
		return "", fmt.Errorf("unexpected content type: %T", result.Content[0])
	}

	return textContent.Text, nil
}
