{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"mcp-example/internal/client"
	"os"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")

	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	// In a real scenario, we might want to pass the server path.
	// For this task, we assume the server is at ./bin/server
	c, err := client.NewClient(ctx, "./bin/server")
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer c.Close()

	if *listTools {
		tools, err := c.ListTools(ctx)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, t := range tools {
			fmt.Println(t)
		}
	}

	if *callTool != "" {
		result, err := c.CallTool(ctx, *callTool)
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		fmt.Println(result)
	}
}
","filename":"cmd/client/main.go"}

{"content":"package server

import (
	"context"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func NewHelloServer() *mcp.Server {
	s := mcp.NewServer(&mcp.Implementation{
		Name:    "hello-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(s, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns 'Hello, MCP World!'",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				mcp.TextContent{Text: "Hello, MCP World!"},
			},
		}, nil, nil
	})

	return s
}
","filename":"internal/server/server.go"}

{"content":"package server

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldServer(t *testing.T) {
	ctx := context.Background()
	s := NewHelloWorldServer()
	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)

	t1, t2 := mcp.NewInMemoryTransports()

	serverSession, err := s.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer serverSession.Close()

	clientSession, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer clientSession.Close()

	// List tools
	tools := []mcp.Tool{}
	for tool, err := range clientSession.Tools(ctx, nil) {
		if err != nil {
			t.Fatal(err)
		}
		tools = append(tools, *tool)
	}

	found := false
	for _, tool := range tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("hello_world tool not found")
	}

	// Call tool
	result, err := clientSession.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatal(err)
	}

	if len(result.Content) == 0 {
		t.Fatal("no content in result")
	}

	textContent, ok := result.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("unexpected content type: %T", result.Content[0])
	}

	expected := "Hello, MCP World!"
	if textContent.Text != expected {
		t.Errorf("expected %q, got %q", expected, textContent.Text)
	}
}
","filename":"internal/server/server_test.go"}

{"content":"package main

import (
	"bytes"
	"context"
	"os"
	"os/exec"
	"strings"
	"testing"
	"time"
)

func TestIntegration(t *testing.T) {
	// Ensure bin directory exists
	_ = os.Mkdir("bin", 0755)

	// Build binaries
	buildServer := exec.Command("go", "build", "-o", "./bin/server", "./cmd/server")
	if out, err := buildServer.CombinedOutput(); err != nil {
		t.Fatalf("failed to build server: %v\nOutput: %s", err, out)
	}
	buildClient := exec.Command("go", "build", "-o", "./bin/client", "./cmd/client")
	if out, err := buildClient.CombinedOutput(); err != nil {
		t.Fatalf("failed to build client: %v\nOutput: %s", err, out)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	// Test --list-tools
	cmd := exec.CommandContext(ctx, "./bin/client", "--list-tools")
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		t.Fatalf("client --list-tools failed: %v\nStderr: %s", err, stderr.String())
	}
	if !strings.Contains(stdout.String(), "hello_world") {
		t.Errorf("expected hello_world in output, got %q", stdout.String())
	}

	// Test --call-tool hello_world
	stdout.Reset()
	stderr.Reset()
	cmd = exec.CommandContext(ctx, "./bin/client", "--call-tool", "hello_world")
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		t.Fatalf("client --call-tool hello_world failed: %v\nStderr: %s", err, stderr.String())
	}
	if !strings.Contains(stdout.String(), "Hello, MCP World!") {
		t.Errorf("expected 'Hello, MCP World!' in output, got %q", stdout.String())
	}
}
