{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type HelloClient struct {
	client  *mcp.Client
	session *mcp.ClientSession
}

func NewHelloClient(serverPath string) (*HelloClient, error) {
	c := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	transport := &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}

	session, err := c.Connect(context.Background(), transport, nil)
	if err != nil {
		return nil, err
	}

	return &HelloClient{
		client:  c,
		session: session,
	}, nil
}

func (c *HelloClient) ListTools(ctx context.Context) ([]string, error) {
	res, err := c.session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}

	var names []string
	for _, t := range res.Tools {
		names = append(names, t.Name)
	}
	return names, nil
}

func (c *HelloClient) CallTool(ctx context.Context, name string) (string, error) {
	res, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return "", err
	}

	if len(res.Content) == 0 {
		return "", fmt.Errorf("no content in result")
	}

	textContent, ok := res.Content[0].(mcp.TextContent)
	if !ok {
		return "", fmt.Errorf("expected text content, got %T", res.Content[0])
	}

	return textContent.Text, nil
}

func (c *HelloClient) Close() error {
	return c.session.Close()
}
","filename":"internal/client/client.go"}

