{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"mcp-example/internal/client"
	"os"
	"path/filepath"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	// Determine server path. Default to ./bin/server
	serverPath := "./bin/server"
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		// Try to find it in the same directory as the client
		exePath, _ := os.Executable()
		serverPath = filepath.Join(filepath.Dir(exePath), "server")
	}

	c, err := client.NewHelloClient(serverPath)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer c.Close()

	ctx := context.Background()

	if *listTools {
		tools, err := c.ListTools(ctx)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, t := range tools {
			fmt.Println(t)
		}
	} else if *callTool != "" {
		res, err := c.CallTool(ctx, *callTool)
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		fmt.Println(res)
	} else {
		flag.Usage()
	}
}
