func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	cmd := exec.Command("./bin/server")
	if _, err := os.Stat("./bin/server"); os.IsNotExist(err) {
		cmd = exec.Command("go", "run", "cmd/server/main.go")
	}

	transport := &mcp.CommandTransport{Command: cmd}
	if err := myclient.RunClient(ctx, transport, *listTools, *callTool); err != nil {
		log.Fatalf("Client failed: %v", err)
	}
}
