func TestClientServerInMemory(t *testing.T) {
	st, ct := mcp.NewInMemoryTransports()

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	errCh := make(chan error, 1)
	go func() {
		errCh <- myserver.RunServer(ctx, st)
	}()

	// Test ListTools
	client := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "1.0.0"}, nil)
	cs, err := client.Connect(ctx, ct, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}

	if err := ListTools(ctx, cs); err != nil {
		t.Errorf("ListTools failed: %v", err)
	}

	if err := CallTool(ctx, cs, "hello_world"); err != nil {
		t.Errorf("CallTool failed: %v", err)
	}

	cs.Close()

	// RunClient test
	st2, ct2 := mcp.NewInMemoryTransports()
	go func() {
		_ = myserver.RunServer(ctx, st2)
	}()

	if err := RunClient(ctx, ct2, true, "hello_world"); err != nil {
		t.Errorf("RunClient failed: %v", err)
	}
}
