{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	// We run the server from the bin directory or relative path
	serverPath := "./bin/server"
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		// Fallback to go run if bin/server doesn't exist yet (for testing during development)
		serverPath = "go"
		// but the prompt says build it as ./bin/server, so we should expect it there.
	}

	var cmd *exec.Cmd
	if serverPath == "go" {
		cmd = exec.Command("go", "run", "./cmd/server/main.go")
	} else {
		cmd = exec.Command(serverPath)
	}

	transport := &mcp.CommandTransport{Command: cmd}
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	cs, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer cs.Close()

	if *listTools {
		tools := cs.Tools(ctx, nil)
		fmt.Println("tools:")
		for t, err := range tools {
			if err != nil {
				log.Fatalf("Error listing tools: %v", err)
			}
			fmt.Printf("- %s\n", t.Name)
		}
	}

	if *callTool != "" {
		result, err := cs.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			log.Fatalf("Error calling tool: %v", err)
		}
		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
}
