func RunCLI(ctx context.Context, c *HelloClient, listTools bool, callTool string, stdout io.Writer) error {
	if listTools {
		tools, err := c.ListTools(ctx)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, t := range tools {
			fmt.Fprintln(stdout, t)
		}
	} else if callTool != "" {
		res, err := c.CallTool(ctx, callTool)
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		fmt.Fprintln(stdout, res)
	}
	return nil
}
