func TestHelloClient_Errors(t *testing.T) {
	s := server.NewHelloServer()
	st, ct := mcp.NewInMemoryTransports()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		if err := s.Run(ctx, st); err != nil && err != context.Canceled {
			t.Errorf("Server.Run failed: %v", err)
		}
	}()

	hc, err := NewHelloClientWithTransport(ctx, ct)
	if err != nil {
		t.Fatalf("Connect failed: %v", err)
	}
	defer hc.Close()

	// Call non-existent tool
	_, err = hc.CallTool(ctx, "non_existent")
	if err == nil {
		t.Error("Expected error calling non-existent tool, got nil")
	}

	// RunCLI error
	err = RunCLI(ctx, hc, false, "non_existent", io.Discard)
	if err == nil {
		t.Error("Expected error from RunCLI, got nil")
	}
}
