	return server
}

func HelloWorldHandler(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
	return &mcp.CallToolResult{
		Content: []mcp.Content{
			&mcp.TextContent{
				Text: "Hello, MCP World!",
			},
		},
	}, nil, nil
}

type ClientOptions struct {
	ListTools bool
	CallTool  string
	ServerBin string
}

func RunClient(ctx context.Context, opts ClientOptions) error {
	if !opts.ListTools && opts.CallTool == "" {
		return fmt.Errorf("no flags specified")
	}

	serverPath := opts.ServerBin
	if serverPath == "" {
		serverPath = "./bin/server"
	}

	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		return fmt.Errorf("server binary not found: %s", serverPath)
	}

	cmd := exec.Command(serverPath)
	transport := &mcp.CommandTransport{Command: cmd}
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	cs, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer cs.Close()

	if opts.ListTools {
		tools := cs.Tools(ctx, nil)
		fmt.Println("tools:")
		for t, err := range tools {
			if err != nil {
				return fmt.Errorf("error listing tools: %w", err)
			}
			fmt.Printf("- %s\n", t.Name)
		}
	}

	if opts.CallTool != "" {
		result, err := cs.CallTool(ctx, &mcp.CallToolParams{
			Name: opts.CallTool,
		})
		if err != nil {
			return fmt.Errorf("error calling tool: %w", err)
		}
		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
	return nil
}
