{"content":"package main

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// HelloWorld implementation duplicated for testing in root package or imported if exported.
// Since it's in cmd/server/main.go it's not exported.
// I'll just use the same logic or move it to a internal package.
// For simplicity, I'll just re-define it here or move it to a shared package.

func HelloWorldInternal(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
	return &mcp.CallToolResult{
		Content: []mcp.Content{
			&mcp.TextContent{
				Text: "Hello, MCP World!",
			},
		},
	}, nil, nil
}

func TestIntegration(t *testing.T) {
	ctx := context.Background()
	clientTransport, serverTransport := mcp.NewInMemoryTransports()

	server := mcp.NewServer(&mcp.Implementation{Name: "test-server", Version: "v0"}, nil)
	mcp.AddTool(server, &mcp.Tool{Name: "hello_world"}, HelloWorldInternal)

	serverSession, err := server.Connect(ctx, serverTransport, nil)
	if err != nil {
		t.Fatalf("failed to connect server: %v", err)
	}
	defer serverSession.Wait()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "v0"}, nil)
	clientSession, err := client.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("failed to connect client: %v", err)
	}
	defer clientSession.Close()

	// Test ListTools
	resList, err := clientSession.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}
	found := false
	for _, tool := range resList.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("hello_world tool not found in ListTools response")
	}

	// Test CallTool
	resCall, err := clientSession.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}
	if len(resCall.Content) != 1 {
		t.Fatalf("expected 1 content, got %d", len(resCall.Content))
	}
	tc, ok := resCall.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("expected TextContent, got %T", resCall.Content[0])
	}
	if tc.Text != "Hello, MCP World!" {
		t.Errorf("expected 'Hello, MCP World!', got %q", tc.Text)
	}
}
