{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func runClient(ctx context.Context, serverPath string, listTools bool, callTool string) error {
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	transport := &mcp.CommandTransport{
		Command: exec.CommandContext(ctx, serverPath),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}

		if res.IsError {
			fmt.Println("Error calling tool")
			for _, content := range res.Content {
				if tc, ok := content.(*mcp.TextContent); ok {
					fmt.Println(tc.Text)
				}
			}
			return fmt.Errorf("tool returned error")
		}

		for _, content := range res.Content {
			switch c := content.(type) {
			case *mcp.TextContent:
				fmt.Println(c.Text)
			default:
				fmt.Printf("%+v\n", c)
			}
		}
	}
	return nil
}

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	if err := runClient(ctx, *serverPath, *listTools, *callTool); err != nil {
		log.Fatal(err)
	}
}
","filename":"cmd/client/main.go"}

