func (c *Client) Run(ctx context.Context, serverPath string, listTools bool, callTool string) error {
	client := mcp.NewClient(c.Implementation, nil)

	transport := &mcp.CommandTransport{
		Command: exec.CommandContext(ctx, serverPath),
	}

