{"content":"package client

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestClient_RunWithTransport(t *testing.T) {
	ctx := context.Background()
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	server := mcp.NewServer(&mcp.Implementation{
		Name:    "test-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(server, &mcp.Tool{
		Name: "test_tool",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{&mcp.TextContent{Text: "test result"}},
		}, nil, nil
	})

	go func() {
		_, _ = server.Connect(ctx, serverTransport, nil)
	}()

	c := NewClient()

	t.Run("list tools", func(t *testing.T) {
		err := c.RunWithTransport(ctx, clientTransport, true, "")
		if err != nil {
			t.Errorf("RunWithTransport failed: %v", err)
		}
	})

	// Re-connect for another test because session might be closed
	serverTransport, clientTransport = mcp.NewInMemoryTransports()
	go func() {
		_, _ = server.Connect(ctx, serverTransport, nil)
	}()

	t.Run("call tool", func(t *testing.T) {
		err := c.RunWithTransport(ctx, clientTransport, false, "test_tool")
		if err != nil {
			t.Errorf("RunWithTransport failed: %v", err)
		}
	})
}
