{"filename":"cmd/client/main.go","new_content":"func RunClient(ctx context.Context, serverPath string, listTools bool, callTool string) error {
	cmd := exec.Command(serverPath)
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return fmt.Errorf("failed to get stdin pipe: %w", err)
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return fmt.Errorf("failed to get stdout pipe: %w", err)
	}

	if err := cmd.Start(); err != nil {
		return fmt.Errorf("failed to start server: %w", err)
	}

	defer func() {
		_ = cmd.Process.Kill()
	}()

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-world-client",
		Version: "v0.0.1",
	}, nil)

	transport := &mcp.IOTransport{
		Reader: stdout,
		Writer: stdin,
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if listTools {
		res, err := session.ListTools(ctx, nil)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, tool := range res.Tools {
			fmt.Println(tool.Name)
		}
	}

	if callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range res.Content {
			if tc, ok := content.(*mcp.TextContent); ok {
				fmt.Println(tc.Text)
			}
		}
	}
	return nil
}

func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		fmt.Println("Please specify either --list-tools or --call-tool <name>")
		flag.Usage()
		os.Exit(1)
	}

	if err := RunClient(context.Background(), *serverPath, *listTools, *callTool); err != nil {
		fmt.Fprintf(os.Stderr, "Client error: %v\n", err)
		os.Exit(1)
	}
}
","old_content":"func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		fmt.Println("Please specify either --list-tools or --call-tool <name>")
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()

	cmd := exec.Command(*serverPath)
	stdin, err := cmd.StdinPipe()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to get stdin pipe: %v\n", err)
		os.Exit(1)
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to get stdout pipe: %v\n", err)
		os.Exit(1)
	}

	if err := cmd.Start(); err != nil {
		fmt.Fprintf(os.Stderr, "Failed to start server: %v\n", err)
		os.Exit(1)
	}

	defer func() {
		_ = cmd.Process.Kill()
	}()

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-world-client",
		Version: "v0.0.1",
	}, nil)

	transport := &mcp.IOTransport{
		Reader: stdout,
		Writer: stdin,
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to connect to server: %v\n", err)
		os.Exit(1)
	}
	defer session.Close()

	if *listTools {
		res, err := session.ListTools(ctx, nil)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Failed to list tools: %v\n", err)
			os.Exit(1)
		}
		for _, tool := range res.Tools {
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			fmt.Fprintf(os.Stderr, "Failed to call tool: %v\n", err)
			os.Exit(1)
		}
		for _, content := range res.Content {
			if tc, ok := content.(*mcp.TextContent); ok {
				fmt.Println(tc.Text)
			}
		}
	}
}
"}

{"content":"package main

import (
	"context"
	"os"
	"path/filepath"
	"testing"
)

func TestRunClient(t *testing.T) {
	// Assuming the binary is already built in ../../bin/server
	// We can use a relative path from the test location.
	// Tests run in the directory of the _test.go file.
	serverPath := filepath.Join("..", "..", "bin", "server")

	// Check if server exists, if not skip or fail
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		t.Skipf("server binary not found at %s, skipping", serverPath)
	}

	ctx := context.Background()

	t.Run("list-tools", func(t *testing.T) {
		err := RunClient(ctx, serverPath, true, "")
		if err != nil {
			t.Errorf("RunClient failed: %v", err)
		}
	})

	t.Run("call-tool", func(t *testing.T) {
		err := RunClient(ctx, serverPath, false, "hello_world")
		if err != nil {
			t.Errorf("RunClient failed: %v", err)
		}
	})

	t.Run("invalid-server", func(t *testing.T) {
		err := RunClient(ctx, "./non-existent", true, "")
		if err == nil {
			t.Error("expected error for non-existent server, got nil")
		}
	})
}
