func RunClient(ctx context.Context, listTools bool, callTool string, transport mcp.Transport) error {
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-world-client",
		Version: "v0.0.1",
	}, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if callTool != "" {
		params := &mcp.CallToolParams{
			Name:      callTool,
			Arguments: map[string]any{},
		}
		res, err := session.CallTool(ctx, params)
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range res.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
	return nil
}

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	transport := &mcp.CommandTransport{
		Command: exec.Command("./bin/server"),
	}

	if err := RunClient(ctx, *listTools, *callTool, transport); err != nil {
		log.Fatal(err)
	}
}
