{"content":"package main

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestRunClient(t *testing.T) {
	clientTransport, serverTransport := mcp.NewInMemoryTransports()
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Setup a mock server
	server := mcp.NewServer(&mcp.Implementation{Name: "mock-server"}, nil)
	mcp.AddTool(server, &mcp.Tool{Name: "hello_world"}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{&mcp.TextContent{Text: "Hello, MCP World!"}},
		}, nil, nil
	})

	go func() {
		if err := server.Run(ctx, serverTransport); err != nil && err != context.Canceled {
			t.Errorf("Server failed: %v", err)
		}
	}()

	// Test ListTools
	if err := RunClient(ctx, true, "", clientTransport); err != nil {
		t.Errorf("RunClient(listTools=true) failed: %v", err)
	}

	// Test CallTool
	if err := RunClient(ctx, false, "hello_world", clientTransport); err != nil {
		t.Errorf("RunClient(callTool=hello_world) failed: %v", err)
	}
}
