{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// App represents the client application logic.
type App struct {
	ServerPath string
}

// ListTools lists tools from the server.
func (a *App) ListTools(ctx context.Context) ([]string, error) {
	session, err := a.connect(ctx)
	if err != nil {
		return nil, err
	}
	defer session.Close()

	var toolNames []string
	for tool, err := range session.Tools(ctx, nil) {
		if err != nil {
			return nil, err
		}
		toolNames = append(toolNames, tool.Name)
	}
	return toolNames, nil
}

// CallTool calls a tool on the server.
func (a *App) CallTool(ctx context.Context, name string) (string, error) {
	session, err := a.connect(ctx)
	if err != nil {
		return "", err
	}
	defer session.Close()

	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return "", err
	}

	var output string
	for _, content := range result.Content {
		if textContent, ok := content.(*mcp.TextContent); ok {
			output += textContent.Text
		}
	}
	return output, nil
}

func (a *App) connect(ctx context.Context) (*mcp.ClientSession, error) {
	cmd := exec.Command(a.ServerPath)
	transport := &mcp.CommandTransport{Command: cmd}

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	return client.Connect(ctx, transport, nil)
}
