func TestApp(t *testing.T) {
	cwd, err := os.Getwd()
	if err != nil {
		t.Fatalf("Failed to get cwd: %v", err)
	}
	// Go up two levels to find bin/server
	serverPath := filepath.Join(cwd, "..", "..", "bin", "server")

	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		t.Skip("Server binary not found, skipping integration test")
	}

	app := &App{ServerPath: serverPath}
	ctx := context.Background()

	t.Run("ListTools", func(t *testing.T) {
		tools, err := app.ListTools(ctx)
		if err != nil {
			t.Fatalf("ListTools failed: %v", err)
		}
		found := false
		for _, name := range tools {
			if name == "hello_world" {
				found = true
				break
			}
		}
		if !found {
			t.Error("Expected tool hello_world not found")
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		output, err := app.CallTool(ctx, "hello_world")
		if err != nil {
			t.Fatalf("CallTool failed: %v", err)
		}
		expected := "Hello, MCP World!"
		if output != expected {
			t.Errorf("Expected %q, got %q", expected, output)
		}
	})
}
