func TestRunClient(t *testing.T) {
	// We need the server binary to be built.
	// Since we are running in a CI-like environment, we can assume it's built or build it here.
	serverPath := filepath.Join("..", "..", "bin", "server")
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		t.Skip("server binary not found, skipping integration test")
	}

	ctx := context.Background()

	t.Run("list tools", func(t *testing.T) {
		var stdout bytes.Buffer
		err := RunClient(ctx, serverPath, true, "", &stdout)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
		if !strings.Contains(stdout.String(), "hello_world") {
			t.Errorf("Expected output to contain 'hello_world', got: %s", stdout.String())
		}
	})

	t.Run("call tool", func(t *testing.T) {
		var stdout bytes.Buffer
		err := RunClient(ctx, serverPath, false, "hello_world", &stdout)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
		if !strings.Contains(stdout.String(), "Hello, MCP World!") {
			t.Errorf("Expected output to contain 'Hello, MCP World!', got: %s", stdout.String())
		}
	})
}
