{"content":"package server

import (
	"context"
	"io"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestRunServerWithTransport(t *testing.T) {
	s := NewHelloServer()

	// Create a pipe to simulate stdio
	r1, w1 := io.Pipe()
	r2, w2 := io.Pipe()

	transport := mcp.NewPipeTransport(r1, w2)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	errCh := make(chan error, 1)
	go func() {
		errCh <- s.Run(ctx, transport)
	}()

	// Close the other end of the pipe to trigger EOF/shutdown
	w1.Close()
	r2.Close()

	cancel()
	err := <-errCh
	if err != nil && err != context.Canceled {
		t.Errorf("Unexpected error: %v", err)
	}
}
