)

func TestNewHelloServer(t *testing.T) {
	s := NewHelloServer()
	if s == nil {
		t.Fatal("Expected server to be non-nil")
	}
}

func TestRunServerWithTransport(t *testing.T) {
	s := NewHelloServer()

	// Create a pipe to simulate stdio
	r1, w1 := io.Pipe()
	r2, w2 := io.Pipe()

	transport := &mcp.IOTransport{
		Reader: r1,
		Writer: w2,
	}

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	errCh := make(chan error, 1)
	go func() {
		errCh <- s.Run(ctx, transport)
	}()

	// Signal shutdown by canceling context
	cancel()

	err := <-errCh
	if err != nil && err != context.Canceled {
		t.Errorf("Unexpected error: %v", err)
	}

	w1.Close()
	r2.Close()
}
