	ctx := context.Background()
	t1, t2 := mcp.NewInMemoryTransports()

	s := server.NewHelloWorldServer()
	go s.Connect(ctx, t1, nil)

	app := &ClientApp{
		Transport: t2,
	}

	t.Run("ListTools", func(t *testing.T) {
		err := app.ListTools(ctx)
		if err != nil {
			t.Errorf("ListTools failed: %v", err)
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		err := app.CallTool(ctx, "hello_world")
		if err != nil {
			t.Errorf("CallTool failed: %v", err)
		}
	})

	t.Run("CallToolNonExistent", func(t *testing.T) {
		err := app.CallTool(ctx, "non_existent")
		if err == nil {
			t.Error("expected error for non-existent tool, got nil")
		}
	})
}
"}

