func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	cwd, err := os.Getwd()
	if err != nil {
		log.Fatalf("Failed to get current directory: %v", err)
	}
	serverPath := filepath.Join(cwd, "bin", "server")

	ctx := context.Background()
	if err := client.RunClient(ctx, serverPath, *listTools, *callTool); err != nil {
		log.Fatalf("Error: %v", err)
	}
}
