import (
	"context"
	"log"

	"github.com/example/mcp-hello-world/internal/hello"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func CreateServer() *mcp.Server {
	server := mcp.NewServer(
		&mcp.Implementation{
			Name:    "hello-world-server",
			Version: "1.0.0",
		},
		nil,
	)

	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns a hello world message",
	}, HelloWorldHandler)

	return server
}

func HelloWorldHandler(ctx context.Context, req *mcp.CallToolRequest, input any) (*mcp.CallToolResult, any, error) {
	return &mcp.CallToolResult{
		Content: []mcp.Content{
			&mcp.TextContent{
				Text: hello.HelloWorld(),
			},
		},
	}, nil, nil
}

func main() {
	server := CreateServer()
	if err := server.Run(context.Background(), &mcp.StdioTransport{}); err != nil {
		log.Fatal(err)
	}
}
