func TestClient_Errors(t *testing.T) {
	ctx := context.Background()
	_, t2 := mcp.NewInMemoryTransports()
	// t2 is not connected to anything
	c, err := NewClient(ctx, t2)
	// NewClient might succeed but calls will fail because it's not connected to a server
	// Actually Connect will wait for initialize
	if err == nil {
		// If it succeeded, try calling something
		_, err = c.ListTools(ctx)
		if err == nil {
			t.Errorf("expected error for disconnected client")
		}
