{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-world-client",
		Version: "1.0.0",
	}, nil)

	// Assuming the server is built as ./bin/server
	transport := &mcp.CommandTransport{
		Command: exec.Command("./bin/server"),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer session.Close()

	if *listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		for _, content := range result.Content {
			if tc, ok := content.(*mcp.TextContent); ok {
				fmt.Println(tc.Text)
			}
		}
	}
}
","filename":"cmd/client/main.go"}

{"content":"package client

import (
	"context"
	"mcp-example/internal/server"
	"testing"
	"time"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestClient(t *testing.T) {
	ctx := context.Background()
	s := server.NewHelloWorldServer()

	t1, t2 := mcp.NewInMemoryTransports()

	serverSession, err := s.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer serverSession.Close()

	c, err := NewClient(ctx, t2)
	if err != nil {
		t.Fatal(err)
	}
	defer c.Close()

	// ListTools
	tools, err := c.ListTools(ctx)
	if err != nil {
		t.Fatal(err)
	}

	found := false
	for _, toolName := range tools {
		if toolName == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("hello_world tool not found in %v", tools)
	}

	// CallTool
	result, err := c.CallTool(ctx, "hello_world")
	if err != nil {
		t.Fatal(err)
	}

	expected := "Hello, MCP World!"
	if result != expected {
		t.Errorf("expected %q, got %q", expected, result)
	}

	// CallTool error
	_, err = c.CallTool(ctx, "non_existent")
	if err == nil {
		t.Errorf("expected error for non_existent tool")
	}
}

func TestNewClientWithCommand(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	// Use the built binary if it exists
	serverPath := "../../bin/server"
	c, err := NewClientWithCommand(ctx, serverPath)
	if err != nil {
		t.Skip("bin/server not found or failed to start, skipping integration test")
		return
	}
	defer c.Close()

	tools, err := c.ListTools(ctx)
	if err != nil {
		t.Fatal(err)
	}

	if len(tools) == 0 {
		t.Error("expected at least one tool")
	}
}
