{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	cmd := exec.Command(*serverPath)
	transport := &mcp.CommandTransport{Command: cmd}

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "v1.0.0",
	}, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer session.Close()

	if *listTools {
		tools, err := session.Tools(ctx, nil)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		fmt.Println("tools:")
		for tool, err := range tools {
			if err != nil {
				log.Fatalf("Error iterating tools: %v", err)
			}
			fmt.Printf("\t%s\n", tool.Name)
		}
	}

	if *callTool != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolRequest{
			Params: struct {
				Name      string `json:"name"`
				Arguments any    `json:"arguments,omitempty"`
			}{
				Name: *callTool,
			},
		}, nil)
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}

		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
}
","filename":"cmd/client/main.go"}

{"content":"package server

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldTool(t *testing.T) {
	s := NewHelloWorldServer()

	ctx := context.Background()
	t1, t2 := mcp.NewInMemoryTransports()

	go func() {
		if err := s.Run(ctx, t1); err != nil && err != context.Canceled {
			// We might get an error when t2 closes, that's fine for this test
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "test-client",
		Version: "1.0.0",
	}, nil)

	session, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	// Test ListTools
	tools, err := session.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}

	found := false
	for _, tool := range tools.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("hello_world tool not found in list")
	}

	// Test CallTool
	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}

	if len(result.Content) != 1 {
		t.Fatalf("Expected 1 content item, got %d", len(result.Content))
	}

	tc, ok := result.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", result.Content[0])
	}

	if tc.Text != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got '%s'", tc.Text)
	}
}
