{"content":"package client

import (
	"context"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	session *mcp.ClientSession
}

func NewClient(ctx context.Context, transport mcp.Transport) (*Client, error) {
	mcpClient := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-world-client",
		Version: "1.0.0",
	}, nil)

	session, err := mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}

	return &Client{
		session: session,
	}, nil
}

func (c *Client) ListTools(ctx context.Context) ([]string, error) {
	tools, err := c.session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}
	names := make([]string, 0, len(tools.Tools))
	for _, t := range tools.Tools {
		names = append(names, t.Name)
	}
	return names, nil
}

func (c *Client) CallTool(ctx context.Context, name string) (string, error) {
	result, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return "", err
	}
	var output string
	for _, content := range result.Content {
		if tc, ok := content.(*mcp.TextContent); ok {
			output += tc.Text
		}
	}
	return output, nil
}

func (c *Client) Close() error {
	return c.session.Close()
}
","filename":"pkg/client/client.go"}

{"content":"package client

import (
	"context"
	"fmt"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type HelloClient struct {
	client  *mcp.Client
	session *mcp.ClientSession
}

func NewHelloClient(ctx context.Context, transport mcp.Transport) (*HelloClient, error) {
	c := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	session, err := c.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}

	return &HelloClient{
		client:  c,
		session: session,
	}, nil
}

func (c *HelloClient) Close() error {
	return c.session.Close()
}

func (c *HelloClient) ListTools(ctx context.Context) ([]string, error) {
	var names []string
	for tool, err := range c.session.Tools(ctx, nil) {
		if err != nil {
			return nil, err
		}
		names = append(names, tool.Name)
	}
	return names, nil
}

func (c *HelloClient) CallHelloWorld(ctx context.Context) (string, error) {
	result, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		return "", err
	}

	for _, content := range result.Content {
		if textContent, ok := content.(*mcp.TextContent); ok {
			return textContent.Text, nil
		}
	}
	return "", fmt.Errorf("no text content in result")
}
