{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/example/mcp-hello/pkg/client"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server", "./bin/server", "Path to the MCP server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()

	if _, err := os.Stat(*serverPath); os.IsNotExist(err) {
		log.Fatalf("Server binary not found at %s. Please build it first.", *serverPath)
	}

	cmd := exec.Command(*serverPath)
	transport := &mcp.CommandTransport{Command: cmd}

	hc, err := client.NewHelloClient(ctx, transport)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer hc.Close()

	if *listTools {
		names, err := hc.ListTools(ctx)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, name := range names {
			fmt.Println(name)
		}
	}

	if *callTool == "hello_world" {
		text, err := hc.CallHelloWorld(ctx)
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		fmt.Println(text)
	} else if *callTool != "" {
		log.Fatalf("Unknown tool: %s", *callTool)
	}
}
