{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server", "./bin/server", "Path to the MCP server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	cmd := exec.Command(*serverPath)
	transport := &mcp.CommandTransport{Command: cmd}

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	cs, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer cs.Close()

	if *listTools {
		tools := cs.Tools(ctx, nil)
		for tool, err := range tools {
			if err != nil {
				log.Fatalf("Error listing tools: %v", err)
			}
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		result, err := cs.CallTool(ctx, *callTool, nil)
		if err != nil {
			log.Fatalf("Error calling tool: %v", err)
		}
		for _, content := range result.Content {
			if tc, ok := content.(*mcp.TextContent); ok {
				fmt.Println(tc.Text)
			}
		}
	}
}
","filename":"cmd/client/main.go"}

{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"io"
	"log"
	"os"
	"os/exec"

	"mcp-example/pkg/client"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	if err := run(os.Args, os.Stdout); err != nil {
		fmt.Fprintf(os.Stderr, "%v\n", err)
		os.Exit(1)
	}
}

func run(args []string, out io.Writer) error {
	fs := flag.NewFlagSet("client", flag.ContinueOnError)
	listTools := fs.Bool("list-tools", false, "List available tools")
	callTool := fs.String("call-tool", "", "Call a tool by name")
	if err := fs.Parse(args[1:]); err != nil {
		return err
	}

	if !*listTools && *callTool == "" {
		fs.Usage()
		return nil
	}

	ctx := context.Background()
	transport := &mcp.CommandTransport{
		Command: exec.Command("./bin/server"),
	}
	c, err := client.NewClient(ctx, transport)
	if err != nil {
		return fmt.Errorf("failed to create client: %w", err)
	}
	defer c.Close()

	if *listTools {
		names, err := c.ListTools(ctx)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, name := range names {
			fmt.Fprintln(out, name)
		}
	}

	if *callTool != "" {
		output, err := c.CallTool(ctx, *callTool)
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		fmt.Fprintln(out, output)
	}
	return nil
}
","filename":"cmd/client/main.go"}

{"content":"package client

import (
	"context"
	"io"
	"testing"

	"github.com/example/mcp-hello/pkg/server"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloClient(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Create pipes for communication
	r1, w1 := io.Pipe()
	r2, w2 := io.Pipe()

	clientTransport := &mcp.IOTransport{Reader: r1, Writer: w2}
	serverTransport := &mcp.IOTransport{Reader: r2, Writer: w1}

	s := server.NewHelloServer()
	go func() {
		if err := s.Run(ctx, serverTransport); err != nil && err != io.EOF {
			// t.Logf("Server exited: %v", err)
		}
	}()

	hc, err := NewHelloClient(ctx, clientTransport)
	if err != nil {
		t.Fatalf("Failed to create client: %v", err)
	}
	defer hc.Close()

	t.Run("ListTools", func(t *testing.T) {
		tools, err := hc.ListTools(ctx)
		if err != nil {
			t.Fatalf("Failed to list tools: %v", err)
		}
		found := false
		for _, name := range tools {
			if name == "hello_world" {
				found = true
				break
			}
		}
		if !found {
			t.Errorf("Tool hello_world not found in %v", tools)
		}
	})

	t.Run("CallHelloWorld", func(t *testing.T) {
		text, err := hc.CallHelloWorld(ctx)
		if err != nil {
			t.Fatalf("Failed to call tool: %v", err)
		}
		expected := "Hello, MCP World!"
		if text != expected {
			t.Errorf("Expected %q, got %q", expected, text)
		}
	})
}
