{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()

	// Create a new client.
	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "1.0.0",
		},
		nil,
	)

	// Connect to the server using CommandTransport.
	transport := &mcp.CommandTransport{
		Command: exec.Command(*serverPath),
	}
	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer session.Close()

	if *listTools {
		res, err := session.ListTools(ctx, nil)
		if err != nil {
			log.Fatalf("ListTools failed: %v", err)
		}
		for _, tool := range res.Tools {
			fmt.Printf("- %s: %s\n", tool.Name, tool.Description)
		}
	}

	if *callTool != "" {
		params := &mcp.CallToolParams{
			Name:      *callTool,
			Arguments: map[string]any{},
		}
		res, err := session.CallTool(ctx, params)
		if err != nil {
			log.Fatalf("CallTool failed: %v", err)
		}

		if res.IsError {
			log.Fatalf("Tool returned an error")
		}

		for _, content := range res.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			} else if structured, ok := content.(*mcp.EmbeddedRes); ok {
                // Handle structured output if necessary, but for this task TextContent is expected or JSON
                _ = structured
            }
		}

        // The SDK might pack the structured output into Content if result.Content was nil.
        // Let's also check if we can just print the whole result content as text if it's not empty.
	}
}
","file_path":"cmd/client/main.go"}

{"content":"package clientlib

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Config struct {
	ListTools  bool
	CallTool   string
	ServerPath string
}

func RunClient(ctx context.Context, cfg Config) error {
	cmd := exec.Command(cfg.ServerPath)
	transport := &mcp.CommandTransport{Command: cmd}

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "v1.0.0",
	}, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if cfg.ListTools {
		tools := session.Tools(ctx, nil)
		fmt.Println("tools:")
		for tool, err := range tools {
			if err != nil {
				return fmt.Errorf("error iterating tools: %w", err)
			}
			fmt.Printf("\t%s\n", tool.Name)
		}
	}

	if cfg.CallTool != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: cfg.CallTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}

		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
	return nil
}
","filename":"internal/clientlib/client.go"}

