{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"os"
	"os/exec"

	"github.com/example/mcp-hello/pkg/client"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func run(args []string) error {
	f := flag.NewFlagSet("client", flag.ContinueOnError)
	listTools := f.Bool("list-tools", false, "List available tools")
	callTool := f.String("call-tool", "", "Call a tool by name")
	serverPath := f.String("server", "./bin/server", "Path to the MCP server binary")

	if err := f.Parse(args); err != nil {
		return err
	}

	if !*listTools && *callTool == "" {
		return fmt.Errorf("either -list-tools or -call-tool must be provided")
	}

	ctx := context.Background()

	if _, err := os.Stat(*serverPath); os.IsNotExist(err) {
		return fmt.Errorf("server binary not found at %s. Please build it first", *serverPath)
	}

	cmd := exec.Command(*serverPath)
	transport := &mcp.CommandTransport{Command: cmd}

	hc, err := client.NewHelloClient(ctx, transport)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %v", err)
	}
	defer hc.Close()

	if *listTools {
		names, err := hc.ListTools(ctx)
		if err != nil {
			return fmt.Errorf("failed to list tools: %v", err)
		}
		for _, name := range names {
			fmt.Println(name)
		}
	}

	if *callTool == "hello_world" {
		text, err := hc.CallHelloWorld(ctx)
		if err != nil {
			return fmt.Errorf("failed to call tool: %v", err)
		}
		fmt.Println(text)
	} else if *callTool != "" {
		return fmt.Errorf("unknown tool: %s", *callTool)
	}
	return nil
}

func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
}
","file_path":"cmd/client/main.go"}

{"content":"package clientlib

import (
	"context"
	"mcp-hello-world/internal/hello"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestRunClient(t *testing.T) {
	clientTransport, serverTransport := mcp.NewInMemoryTransports()

	server := hello.NewHelloServer()
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		if err := server.Run(ctx, serverTransport); err != nil {
			// server might return error on close, ignore it for now
		}
	}()

	t.Run("ListTools", func(t *testing.T) {
		cfg := Config{
			ListTools: true,
		}
		if err := RunClient(ctx, cfg, clientTransport); err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
	})

	// InMemoryTransport can only be used once.
	// So I need a new pair for the next test.
	clientTransport2, serverTransport2 := mcp.NewInMemoryTransports()
	go func() {
		_ = server.Run(ctx, serverTransport2)
	}()

	t.Run("CallTool", func(t *testing.T) {
		cfg := Config{
			CallTool: "hello_world",
		}
		if err := RunClient(ctx, cfg, clientTransport2); err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
	})
}
","filename":"internal/clientlib/client_test.go"}

