)

func runServer(ctx context.Context, t mcp.Transport) error {
	s := server.NewHelloServer()
	return s.Run(ctx, t)
}

func main() {
	if err := runServer(context.Background(), &mcp.StdioTransport{}); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}
