{"content":"package main

import (
	"context"
	"flag"
	"log"
	"os"
	"os/exec"

	"mcp-hello-world/pkg/client"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listToolsFlag := flag.Bool("list-tools", false, "List all available tools")
	callToolFlag := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listToolsFlag && *callToolFlag == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()

	mcpClient := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "1.0.0",
		},
		nil,
	)

	transport := &mcp.CommandTransport{
		Command: exec.Command(*serverPath),
	}
	session, err := mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer session.Close()

	if *listToolsFlag {
		if err := client.ListTools(ctx, session); err != nil {
			log.Fatalf("ListTools failed: %v", err)
		}
	}

	if *callToolFlag != "" {
		if err := client.CallTool(ctx, session, *callToolFlag); err != nil {
			log.Fatalf("CallTool failed: %v", err)
		}
	}
}
