func TestIntegration(t *testing.T) {
	ctx := context.Background()

	// Create server
	s := server.CreateServer()

	// Create client
	c := mcp.NewClient(
		&mcp.Implementation{
			Name:    "test-client",
			Version: "1.0.0",
		},
		nil,
	)

	// Create in-memory transports
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	// Start server in a goroutine
	go func() {
		if err := s.Run(ctx, serverTransport); err != nil {
			// This might happen on close, so just log it if we really wanted to
		}
	}()

	// Connect client
	session, err := c.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("failed to connect: %v", err)
	}
	defer session.Close()

	// Test ListTools
	err = ListTools(ctx, session)
	if err != nil {
		t.Errorf("ListTools failed: %v", err)
	}

	// Test CallTool
	err = CallTool(ctx, session, "hello_world")
	if err != nil {
		t.Errorf("CallTool failed: %v", err)
	}

    // Test CallTool with non-existent tool
    err = CallTool(ctx, session, "non_existent")
    if err == nil {
        t.Errorf("expected error for non-existent tool, got nil")
    }
}
