	w io.WriteCloser
}

func (t *pipeTransport) Read(ctx context.Context) (mcp.JSONRPCMessage, error) {
	// Simple mock read is hard to implement correctly for real MCP server
	// but we can just test if RunServer finishes when context is canceled.
	<-ctx.Done()
	return nil, ctx.Err()
}

func (t *pipeTransport) Write(ctx context.Context, msg mcp.JSONRPCMessage) error {
	return nil
}

func (t *pipeTransport) Close() error {
	return nil
}

func TestRunServer(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()

	transport := &pipeTransport{}
	err := RunServer(ctx, transport)

	if err != nil && err != context.DeadlineExceeded && err != context.Canceled {
		t.Errorf("Unexpected error: %v", err)
	}
}
