func TestRunClient(t *testing.T) {
	// Build the server first
	tmpDir, err := os.MkdirTemp("", "mcp-test")
	if err != nil {
		t.Fatal(err)
	}
	defer os.RemoveAll(tmpDir)

	serverPath := filepath.Join(tmpDir, "server")
	// We need to build the server from cmd/server
	// Assuming we are in pkg/client
	cmd := exec.Command("go", "build", "-o", serverPath, "../../cmd/server/main.go")
	if output, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("failed to build server: %v\n%s", err, output)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	// Test list tools
	err = RunClient(ctx, serverPath, true, "")
	if err != nil {
		t.Errorf("RunClient(listTools=true) failed: %v", err)
	}

	// Test call tool
	err = RunClient(ctx, serverPath, false, "hello_world")
	if err != nil {
		t.Errorf("RunClient(callTool=hello_world) failed: %v", err)
	}
}
