{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
	session   *mcp.ClientSession
}

func NewClient(name, version string) *Client {
	return &Client{
		mcpClient: mcp.NewClient(&mcp.Implementation{
			Name:    name,
			Version: version,
		}, nil),
	}
}

func (c *Client) Connect(ctx context.Context, command string, args ...string) error {
	transport := &mcp.CommandTransport{
		Command: exec.Command(command, args...),
	}
	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	c.session = session
	return nil
}

func (c *Client) ConnectTransport(ctx context.Context, transport mcp.Transport) error {
	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	c.session = session
	return nil
}

func (c *Client) Close() error {
	if c.session != nil {
		return c.session.Close()
	}
	return nil
}

func (c *Client) ListTools(ctx context.Context) ([]string, error) {
	tools, err := c.session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, t := range tools.Tools {
		names = append(names, t.Name)
	}
	return names, nil
}

func (c *Client) CallTool(ctx context.Context, name string) (string, error) {
	result, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name:      name,
		Arguments: map[string]any{},
	})
	if err != nil {
		return "", err
	}

	var out string
	for _, content := range result.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			out += text.Text
		}
	}
	return out, nil
}
","filename":"internal/client/client.go"}

