func Run(listTools bool, callTool string) {
	ctx := context.Background()
	c := NewClient("hello-world-client", "1.0.0")

	err := c.Connect(ctx, "./bin/server")
	if err != nil {
		log.Fatal(err)
	}
	defer c.Close()

	if listTools {
		tools, err := c.ListTools(ctx)
		if err != nil {
			log.Fatal(err)
		}
		for _, name := range tools {
			fmt.Println(name)
		}
	}

	if callTool != "" {
		out, err := c.CallTool(ctx, callTool)
		if err != nil {
			log.Fatal(err)
		}
		fmt.Println(out)
	}
}

