func GetServer() *mcp.Server {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "hello-world-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns a hello world message",
	}, HandleHelloWorld)

	return server
}

func HandleHelloWorld(ctx context.Context, req *mcp.CallToolRequest, args struct{}) (*mcp.CallToolResult, any, error) {
	return &mcp.CallToolResult{
		Content: []mcp.Content{
			&mcp.TextContent{
				Text: "Hello, MCP World!",
			},
		},
	}, nil, nil
}
