{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
	serverCmd string
}

func NewClient(serverCmd string) *Client {
	return &Client{
		mcpClient: mcp.NewClient(&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "1.0.0",
		}, nil),
		serverCmd: serverCmd,
	}
}

func (c *Client) ListTools(ctx context.Context) ([]string, error) {
	cmd := exec.Command(c.serverCmd)
	transport := &mcp.CommandTransport{Command: cmd}

	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}
	defer session.Close()

	result, err := session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}

	var names []string
	for _, tool := range result.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

func (c *Client) CallTool(ctx context.Context, name string) ([]string, error) {
	cmd := exec.Command(c.serverCmd)
	transport := &mcp.CommandTransport{Command: cmd}

	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}
	defer session.Close()

	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return nil, err
	}

	var contents []string
	for _, content := range result.Content {
		if textContent, ok := content.(*mcp.TextContent); ok {
			contents = append(contents, textContent.Text)
		}
	}
	return contents, nil
}
