		Message:	"This should fail",
		RequestedSchema: &jsonschema.Schema{
			Type:	"object",
			Properties: map[string]*jsonschema.Schema{
				"test": {Type: "string"},
			},
		},
	})
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println(res.Content["test"])

