import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
)

func TestClient(t *testing.T) {
	// Build server if not exists
	serverPath := filepath.Join("..", "..", "bin", "server")
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		cmd := exec.Command("go", "build", "-o", serverPath, "../../cmd/server")
		if err := cmd.Run(); err != nil {
			t.Fatalf("failed to build server: %v", err)
		}
	}

	c := NewClient(serverPath)
	ctx := context.Background()

	t.Run("ListTools", func(t *testing.T) {
		tools, err := c.ListTools(ctx)
		if err != nil {
			t.Fatalf("ListTools failed: %v", err)
		}
		found := false
		for _, name := range tools {
			if name == "hello_world" {
				found = true
				break
			}
		}
		if !found {
			t.Errorf("hello_world tool not found in %v", tools)
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		contents, err := c.CallTool(ctx, "hello_world")
		if err != nil {
			t.Fatalf("CallTool failed: %v", err)
		}
		expected := "Hello, MCP World!"
		found := false
		for _, text := range contents {
			if text == expected {
				found = true
				break
			}
		}
		if !found {
			t.Errorf("Expected content %q not found in %v", expected, contents)
		}
	})
}
