{"content":"package client

import (
	"context"
	"fmt"
	"io"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type ClientOptions struct {
	ServerPath string
	ListTools  bool
	CallTool   string
}

func RunClient(ctx context.Context, out io.Writer, opts ClientOptions) error {
	cmd := exec.Command(opts.ServerPath)
	transport := &mcp.CommandTransport{Command: cmd}

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	cs, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer cs.Close()

	if opts.ListTools {
		tools := cs.Tools(ctx, nil)
		for tool, err := range tools {
			if err != nil {
				return fmt.Errorf("error listing tools: %w", err)
			}
			fmt.Fprintf(out, "Tool: %s - %s\n", tool.Name, tool.Description)
		}
	}

	if opts.CallTool != "" {
		result, err := cs.CallTool(ctx, &mcp.CallToolParams{
			Name: opts.CallTool,
		})
		if err != nil {
			return fmt.Errorf("error calling tool: %w", err)
		}

		for _, content := range result.Content {
			if textContent, ok := content.(*mcp.TextContent); ok {
				fmt.Fprintln(out, textContent.Text)
			}
		}
	}

	return nil
}
