{"content":"package clientlib

import (
	"context"
	"fmt"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type ClientApp struct {
	Session *mcp.ClientSession
}

func NewClientApp(ctx context.Context, serverPath string) (*ClientApp, error) {
	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-mcp-client",
			Version: "1.0.0",
		},
		nil,
	)

	transport := &mcp.CommandTransport{
		Command: &mcp.Command{
			Command: serverPath,
		},
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}
	return &ClientApp{Session: session}, nil
}

// In-memory version for testing
func NewClientAppWithTransport(ctx context.Context, transport mcp.Transport) (*ClientApp, error) {
	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-mcp-client",
			Version: "1.0.0",
		},
		nil,
	)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}
	return &ClientApp{Session: session}, nil
}

func (a *ClientApp) ListTools(ctx context.Context) ([]string, error) {
	tools, err := a.Session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, tool := range tools.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

func (a *ClientApp) CallHelloWorld(ctx context.Context) (string, error) {
	res, err := a.Session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		return "", err
	}
	for _, content := range res.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			return text.Text, nil
		}
	}
	return "", fmt.Errorf("no text content found")
}
