func TestHelloServer(t *testing.T) {
	server := NewHelloServer()
	if server == nil {
		t.Fatal("Expected server to be non-nil")
	}

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	t1, t2 := mcp.NewInMemoryTransports()

	go func() {
		if err := RunServer(ctx, server, t1); err != nil && err != context.Canceled {
			// t.Errorf might be called after test finished if we are not careful
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)
	session, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	tools, err := session.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("Failed to list tools: %v", err)
	}

	found := false
	for _, tool := range tools.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("Expected tool hello_world not found")
	}
}
