func TestClientApp(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	sTransport, cTransport := mcp.NewInMemoryTransports()
	server := serverlib.NewHelloServer()

	go func() {
		_ = serverlib.RunServer(ctx, server, sTransport)
	}()

	app, err := NewClientAppWithTransport(ctx, cTransport)
	if err != nil {
		t.Fatalf("Failed to create client app: %v", err)
	}
	defer app.Session.Close()

	tools, err := app.ListTools(ctx)
	if err != nil {
		t.Fatalf("Failed to list tools: %v", err)
	}

	found := false
	for _, name := range tools {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("Expected tool hello_world not found")
	}

	msg, err := app.CallHelloWorld(ctx)
	if err != nil {
		t.Fatalf("Failed to call hello world: %v", err)
	}

	expected := "Hello, MCP World!"
	if msg != expected {
		t.Errorf("Expected %q, got %q", expected, msg)
	}
}
