func TestRunClient(t *testing.T) {
	// We need to find the bin/server. 
	// Since we are in pkg/client, it's ../../bin/server
	cwd, _ := os.Getwd()
	serverPath := filepath.Join(cwd, "..", "..", "bin", "server")

	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		t.Skip("Server binary not found at", serverPath)
	}

	ctx := context.Background()

	t.Run("ListTools", func(t *testing.T) {
		var out bytes.Buffer
		opts := ClientOptions{
			ServerPath: serverPath,
			ListTools:  true,
		}
		err := RunClient(ctx, &out, opts)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
		if !strings.Contains(out.String(), "hello_world") {
			t.Errorf("Expected output to contain 'hello_world', got %q", out.String())
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		var out bytes.Buffer
		opts := ClientOptions{
			ServerPath: serverPath,
			CallTool:   "hello_world",
		}
		err := RunClient(ctx, &out, opts)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
		if !strings.Contains(out.String(), "Hello, MCP World!") {
			t.Errorf("Expected output to contain 'Hello, MCP World!', got %q", out.String())
		}
	})
}
