{"content":"package client

import (
	"context"
	"fmt"
	"io"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Config struct {
	ListTools bool
	CallTool  string
	ServerBin string
}

func RunClient(ctx context.Context, cfg Config, out io.Writer) error {
	cmd := exec.Command(cfg.ServerBin)
	transport := &mcp.CommandTransport{Command: cmd}

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	cs, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer cs.Close()

	if cfg.ListTools {
		for t, err := range cs.Tools(ctx, nil) {
			if err != nil {
				return fmt.Errorf("error iterating tools: %w", err)
			}
			fmt.Fprintln(out, t.Name)
		}
	}

	if cfg.CallTool != "" {
		result, err := cs.CallTool(ctx, &mcp.CallToolParams{
			Name: cfg.CallTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range result.Content {
			if tc, ok := content.(*mcp.TextContent); ok {
				fmt.Fprintln(out, tc.Text)
			}
		}
	}

	return nil
}
","file_path":"pkg/client/client.go"}

