	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		fmt.Println("Usage: client [--list-tools] [--call-tool <tool_name>]")
		return
	}

	cfg := client.Config{
		ListTools: *listTools,
		CallTool:  *callTool,
		ServerBin: "./bin/server",
	}

	if err := client.RunClient(context.Background(), cfg, os.Stdout); err != nil {
		log.Fatal(err)
	}
}
