func TestRunClient_Integration(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	cfg := Config{
		ListTools: true,
		CallTool:  "hello_world",
		ServerBin: "../../bin/server",
	}

	// Use a pipe to capture output
	pr, pw := io.Pipe()

	// Run client in a goroutine because we want to read from the pipe
	errCh := make(chan error, 1)
	go func() {
		defer pw.Close()
		errCh <- RunClient(ctx, cfg, pw)
	}()

	output, err := io.ReadAll(pr)
	if err != nil {
		t.Fatalf("Failed to read output: %v", err)
	}

	if err := <-errCh; err != nil {
		t.Fatalf("RunClient failed: %v", err)
	}

	outStr := string(output)
	if !contains(outStr, "hello_world") {
		t.Errorf("Expected output to contain 'hello_world', got %q", outStr)
	}
	if !contains(outStr, "Hello, MCP World!") {
		t.Errorf("Expected output to contain 'Hello, MCP World!', got %q", outStr)
	}
}

func contains(s, substr string) bool {
	return len(s) >= len(substr) && (s == substr || stringContains(s, substr))
}

func stringContains(s, substr string) bool {
	for i := 0; i <= len(s)-len(substr); i++ {
		if s[i:i+len(substr)] == substr {
			return true
		}
	}
	return false
}
"}

