func TestRunClient(t *testing.T) {
	ctx := context.Background()

	// Setup a dummy server
	s := mcp.NewServer(&mcp.Implementation{Name: "test", Version: "1.0.0"}, nil)
	mcp.AddTool(s, &mcp.Tool{Name: "hello_world"}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{&mcp.TextContent{Text: "Hello, MCP World!"}},
		}, nil, nil
	})

	t1, t2 := mcp.NewInMemoryTransports()
	go func() {
		_, _ = s.Connect(ctx, t1, nil)
	}()

	// Test list tools
	err := RunClient(true, "", t2)
	if err != nil {
		t.Errorf("RunClient(true, \"\") failed: %v", err)
	}

	// Connect again for the next call because RunClient closes the session
	t3, t4 := mcp.NewInMemoryTransports()
	go func() {
		_, _ = s.Connect(ctx, t3, nil)
	}()
	err = RunClient(false, "hello_world", t4)
	if err != nil {
		t.Errorf("RunClient(false, \"hello_world\") failed: %v", err)
	}
}
