{"content":"package main

import (
	"context"
	"flag"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-hello-world/pkg/hello"
)

func run(args []string) error {
	fs := flag.NewFlagSet("client", flag.ExitOnError)
	listTools := fs.Bool("list-tools", false, "List available tools")
	callTool := fs.String("call-tool", "", "Call a tool by name")
	serverPath := fs.String("server-path", "./bin/server", "Path to the server binary")
	if err := fs.Parse(args); err != nil {
		return err
	}

	if !*listTools && *callTool == "" {
		fs.Usage()
		return nil
	}

	ctx := context.Background()
	cmd := exec.Command(*serverPath)
	transport := &mcp.CommandTransport{Command: cmd}

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-world-client",
		Version: "1.0.0",
	}, nil)

	cs, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	defer cs.Close()

	if *listTools {
		if err := hello.ListTools(ctx, cs); err != nil {
			return err
		}
	}

	if *callTool != "" {
		if *callTool == "hello_world" {
			if err := hello.CallHelloWorld(ctx, cs); err != nil {
				return err
			}
		} else {
			log.Printf("Unknown tool: %s", *callTool)
		}
	}
	return nil
}

func main() {
	if err := run(os.Args[1:]); err != nil {
		log.Fatalf("Client failed: %v", err)
	}
}
