{"content":"package server

import (
	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-server/internal/tools"
)

func NewHelloServer() *mcp.Server {
	s := mcp.NewServer(&mcp.Implementation{
		Name:    "hello-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(s, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns a hello world message",
	}, tools.HelloWorldHandler)

	return s
}
","filename":"internal/server/server.go"}

{"content":"package main

import (
	"context"
	"flag"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-hello-world/pkg/hello"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	cmd := exec.Command(*serverPath)
	transport := &mcp.CommandTransport{Command: cmd}

	if err := hello.RunClient(ctx, transport, *listTools, *callTool); err != nil {
		log.Fatalf("Client failed: %v", err)
	}
}
","file_path":"cmd/client/main.go"}

