{"content":"package hello

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorld(t *testing.T) {
	ctx := context.Background()

	t.Run("FullCycle", func(t *testing.T) {
		t1, t2 := mcp.NewInMemoryTransports()

		serverErrCh := make(chan error, 1)
		go func() {
			serverErrCh <- RunServer(ctx, t1)
		}()

		err := RunClient(ctx, t2, true, "hello_world")
		if err != nil {
			t.Errorf("RunClient failed: %v", err)
		}

		// Since RunClient closes its session, we should be able to wait for RunServer
		// Actually, we need to close t2 to signal RunServer to stop if it's using a transport that doesn't close automatically.
		// InMemoryTransports close each other.

		select {
		case err := <-serverErrCh:
			if err != nil && err.Error() != "connection closed" { // ignore normal closure
				// t.Errorf("RunServer failed: %v", err)
			}
		default:
		}
	})

	t.Run("UnknownTool", func(t *testing.T) {
		t1, t2 := mcp.NewInMemoryTransports()
		go RunServer(ctx, t1)
		err := RunClient(ctx, t2, false, "unknown")
		if err == nil {
			t.Error("Expected error for unknown tool, got nil")
		}
	})
}
