{"content":"package main

import (
	"context"
	"flag"
	"log"
	"mcp-server/internal/client"
	"os"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()

	if *listTools {
		if err := client.ListTools(ctx, *serverPath); err != nil {
			log.Fatal(err)
		}
	}

	if *callTool != "" {
		if err := client.CallTool(ctx, *serverPath, *callTool); err != nil {
			log.Fatal(err)
		}
	}
}
","filename":"cmd/client/main.go"}

{"content":"package client

import (
	"context"
	"fmt"
	"io"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func ListTools(ctx context.Context, session *mcp.ClientSession, out io.Writer) error {
	tools := session.Tools(ctx, nil)
	for tool, err := range tools {
		if err != nil {
			return err
		}
		fmt.Fprintln(out, tool.Name)
	}
	return nil
}

func CallTool(ctx context.Context, session *mcp.ClientSession, name string, out io.Writer) error {
	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return err
	}

	for _, content := range result.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			fmt.Fprintln(out, text.Text)
		}
	}
	return nil
}
","filename":"internal/client/client.go"}

{"content":"package server

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestNewHelloServer(t *testing.T) {
	s := NewHelloServer()
	if s == nil {
		t.Fatal("expected server, got nil")
	}

	ctx := context.Background()
	t1, t2 := mcp.NewInMemoryTransports()

	_, err := s.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatalf("failed to connect server: %v", err)
	}

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)
	session, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("failed to connect client: %v", err)
	}
	defer session.Close()

	tools, err := session.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("failed to list tools: %v", err)
	}

	found := false
	for _, tool := range tools.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("hello_world tool not found")
	}
}
","filename":"internal/server/server_test.go"}

