{"content":"package client

import (
	"bytes"
	"context"
	"strings"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestClient(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	server := mcp.NewServer(&mcp.Implementation{Name: "test-server", Version: "1.0.0"}, nil)
	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns 'Hello, MCP World!'",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args struct{}) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				&mcp.TextContent{Text: "Hello, MCP World!"},
			},
		}, nil, nil
	})

	go func() {
		if err := server.Run(ctx, serverTransport); err != nil {
			// server might be closed by cancel()
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "1.0.0"}, nil)
	session, err := client.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("failed to connect: %v", err)
	}
	defer session.Close()

	t.Run("ListTools", func(t *testing.T) {
		var out bytes.Buffer
		if err := ListTools(ctx, session, &out); err != nil {
			t.Fatalf("ListTools failed: %v", err)
		}
		if !strings.Contains(out.String(), "hello_world") {
			t.Errorf("expected output to contain hello_world, got %q", out.String())
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		var out bytes.Buffer
