func TestClient(t *testing.T) {
	// Find server binary
	wd, _ := os.Getwd()
	serverPath := filepath.Join(wd, "..", "..", "bin", "server")

	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		t.Skip("server binary not found, skip integration test")
	}

	ctx := context.Background()

	t.Run("ListTools", func(t *testing.T) {
		err := ListTools(ctx, serverPath)
		if err != nil {
			t.Fatalf("ListTools failed: %v", err)
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		err := CallTool(ctx, serverPath, "hello_world")
		if err != nil {
			t.Fatalf("CallTool failed: %v", err)
		}
	})

	t.Run("CallToolNotFound", func(t *testing.T) {
		err := CallTool(ctx, serverPath, "non_existent")
		if err == nil {
			t.Fatal("expected error for non_existent tool, got nil")
		}
	})
}
