{"content":"package client

import (
	"context"
	"fmt"
	"io"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func ListTools(ctx context.Context, session *mcp.ClientSession, out io.Writer) error {
	tools := session.Tools(ctx, nil)
	for tool, err := range tools {
		if err != nil {
			return err
		}
		fmt.Fprintln(out, tool.Name)
	}
	return nil
}

func CallTool(ctx context.Context, session *mcp.ClientSession, name string, out io.Writer) error {
	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return err
	}

	for _, content := range result.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			fmt.Fprintln(out, text.Text)
		}
	}
	return nil
}

func RunClient(ctx context.Context, listTools bool, callToolName string, serverCmd string, out io.Writer) error {
	cmd := exec.Command(serverCmd)
	transport := &mcp.CommandTransport{Command: cmd}

	mcpClient := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	session, err := mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	defer session.Close()

	if listTools {
		if err := ListTools(ctx, session, out); err != nil {
			return err
		}
	}

	if callToolName != "" {
		if err := CallTool(ctx, session, callToolName, out); err != nil {
			return err
		}
	}
	return nil
}
","filename":"internal/client/client.go"}

