{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type ClientApp struct {
	ServerBinary string
}

func (a *ClientApp) ListTools(ctx context.Context) ([]string, error) {
	cmd := exec.Command(a.ServerBinary)
	transport := &mcp.CommandTransport{Command: cmd}

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "v0.1.0",
	}, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return nil, fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	tools := session.Tools(ctx, nil)
	var toolNames []string
	for tool, err := range tools {
		if err != nil {
			return nil, fmt.Errorf("error listing tools: %w", err)
		}
		toolNames = append(toolNames, tool.Name)
	}
	return toolNames, nil
}

func (a *ClientApp) CallTool(ctx context.Context, toolName string) (string, error) {
	cmd := exec.Command(a.ServerBinary)
	transport := &mcp.CommandTransport{Command: cmd}

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "v0.1.0",
	}, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return "", fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: toolName,
	})
	if err != nil {
		return "", fmt.Errorf("error calling tool: %w", err)
	}

	var output string
	for _, content := range res.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			output += text.Text
		}
	}
	return output, nil
}
","filename":"internal/client/client.go"}

{"content":"package main

import (
	"context"
	"log"
	"os"
	"os/signal"
	"syscall"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/petruzalek/mcp-hello-world/pkg/hello"
)

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	server := mcp.NewServer(
		&mcp.Implementation{
			Name:    "hello-server",
			Version: "1.0.0",
		},
		nil,
	)

	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns a hello world message",
	}, hello.HelloWorld)

	transport := &mcp.StdioTransport{}
	session, err := server.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}

	// Wait for the context to be canceled (e.g., via SIGTERM or SIGINT)
	// The session will automatically close when the context is done if Connect handled it,
	// but usually we wait for it.
	<-ctx.Done()
	session.Wait()
}
