{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools in the server")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()

	// Assume the server is at ./bin/server relative to the execution directory
	cmd := exec.Command("./bin/server")
	// Redirect stderr of the server to client's stderr for easier debugging
	cmd.Stderr = os.Stderr

	transport := &mcp.CommandTransport{Command: cmd}
	client := mcp.NewClient(&mcp.Implementation{Name: "hello-client", Version: "1.0.0"}, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer session.Close()

	if *listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		fmt.Println("tools:")
		for _, tool := range tools.Tools {
			fmt.Printf("- %s\n", tool.Name)
		}
	}

	if *callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			log.Fatalf("Failed to call tool %s: %v", *callTool, err)
		}

		for _, content := range res.Content {
			if textContent, ok := content.(*mcp.TextContent); ok {
				fmt.Println(textContent.Text)
			}
		}
	}
}
