{"content":"package client

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
)

func TestClientApp(t *testing.T) {
	// Build the server binary for testing
	tmpDir, err := os.MkdirTemp("", "mcp-test-*")
	if err != nil {
		t.Fatalf("failed to create temp dir: %v", err)
	}
	defer os.RemoveAll(tmpDir)

	serverBinary := filepath.Join(tmpDir, "server")
	// We need to point to the correct path for cmd/server/main.go
	// Since we are in internal/client, it's ../../cmd/server/main.go
	cmd := exec.Command("go", "build", "-o", serverBinary, "../../cmd/server/main.go")
	if output, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("failed to build server: %v, output: %s", err, output)
	}

	app := &ClientApp{
		ServerBinary: serverBinary,
	}

	ctx := context.Background()

	t.Run("ListTools", func(t *testing.T) {
		tools, err := app.ListTools(ctx)
		if err != nil {
			t.Fatalf("ListTools failed: %v", err)
		}
		found := false
		for _, tool := range tools {
			if tool == "hello_world" {
				found = true
				break
			}
		}
		if !found {
			t.Errorf("expected to find hello_world tool, got %v", tools)
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		res, err := app.CallTool(ctx, "hello_world")
		if err != nil {
			t.Fatalf("CallTool failed: %v", err)
		}
		if res != "Hello, MCP World!" {
			t.Errorf("expected 'Hello, MCP World!', got %q", res)
		}
	})

	t.Run("CallToolNotFound", func(t *testing.T) {
		_, err := app.CallTool(ctx, "non_existent")
		if err == nil {
			t.Error("expected error calling non-existent tool, got nil")
		}
	})
}
