	}
	defer session.Close()

	hc := &HelloClient{Session: session}

	tools, err := hc.ListTools(ctx)
	if err != nil {
		t.Fatalf("failed to list tools: %v", err)
	}
	found := false
	for _, name := range tools {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("expected to find hello_world tool")
	}

	res, err := hc.CallHelloWorld(ctx)
	if err != nil {
		t.Fatalf("failed to call hello_world: %v", err)
	}
	if res != "Hello, MCP World!" {
		t.Errorf("expected 'Hello, MCP World!', got '%s'", res)
	}
