{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"mcp-hello/pkg/client"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server", "./bin/server", "Path to the server executable")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()

	mcpClient := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	transport := &mcp.CommandTransport{
		Command: exec.Command(*serverPath),
	}

	session, err := mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	hc := &client.HelloClient{Session: session}

	if *listTools {
		names, err := hc.ListTools(ctx)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, name := range names {
			fmt.Println(name)
		}
	}

	if *callTool != "" {
		if *callTool == "hello_world" {
			res, err := hc.CallHelloWorld(ctx)
			if err != nil {
				log.Fatalf("Failed to call hello_world: %v", err)
			}
			fmt.Println(res)
		} else {
			log.Fatalf("Unknown tool: %s", *callTool)
		}
	}
}
","filename":"cmd/client/main.go"}

{"content":"package server

import (
	"context"
	"io"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloServer(t *testing.T) {
	s := NewHelloServer()

	// Create pipes for communication
	r1, w1 := io.Pipe()
	r2, w2 := io.Pipe()

	serverTransport := mcp.NewStdioTransport(r1, w2)
	clientTransport := mcp.NewStdioTransport(r2, w1)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Run server in a goroutine
	go func() {
		if err := s.Run(ctx, serverTransport); err != nil && err != context.Canceled {
			t.Errorf("Server failed: %v", err)
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)
	cs, err := client.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer cs.Close()

	result, err := cs.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("Failed to call tool: %v", err)
	}

	if len(result.Content) != 1 {
		t.Fatalf("Expected 1 content block, got %d", len(result.Content))
	}

	text, ok := result.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", result.Content[0])
	}

	if text.Text != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got %q", text.Text)
	}
}
