func TestRunClient(t *testing.T) {
	// Need to find the server binary. Assuming we are in pkg/client/
	serverPath := "../../bin/server"
	if _, err := os.Stat(serverPath); err != nil {
		// Try absolute path if relative fails, but let's just skip if not found
		// in a real CI it should be there.
		t.Skip("server binary not found at", serverPath)
	}

	absPath, err := filepath.Abs(serverPath)
	if err != nil {
		t.Fatalf("failed to get abs path: %v", err)
	}

	ctx := context.Background()

	t.Run("list-tools", func(t *testing.T) {
		err := RunClient(ctx, absPath, true, "")
		if err != nil {
			t.Errorf("RunClient failed: %v", err)
		}
	})

	t.Run("call-tool", func(t *testing.T) {
		err := RunClient(ctx, absPath, false, "hello_world")
		if err != nil {
			t.Errorf("RunClient failed: %v", err)
		}
	})

	t.Run("unknown-tool", func(t *testing.T) {
		err := RunClient(ctx, absPath, false, "unknown")
		if err == nil {
			t.Error("expected error for unknown tool, got nil")
		}
	})
}
