{"content":"package client

import (
	"context"
	"fmt"
	"io"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
	session   *mcp.ClientSession
}

func NewClient() *Client {
	return &Client{
		mcpClient: mcp.NewClient(&mcp.Implementation{
			Name:    "hello-mcp-client",
			Version: "1.0.0",
		}, nil),
	}
}

func (c *Client) Connect(ctx context.Context, transport mcp.Transport) error {
	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	c.session = session
	return nil
}

func (c *Client) Close() error {
	if c.session != nil {
		return c.session.Close()
	}
	return nil
}

func (c *Client) ListTools(ctx context.Context, out io.Writer) error {
	fmt.Fprintln(out, "tools:")
	for t, err := range c.session.Tools(ctx, nil) {
		if err != nil {
			return err
		}
		fmt.Fprintf(out, "- %s\n", t.Name)
	}
	return nil
}

func (c *Client) CallTool(ctx context.Context, name string, out io.Writer) error {
	result, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return err
	}

	for _, content := range result.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			fmt.Fprintln(out, text.Text)
		}
	}
	return nil
}
