func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools in the server")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	cfg := client.Config{
		ServerPath: "./bin/server",
	}
	c := client.NewClient(cfg)

	if err := c.Run(context.Background(), *listTools, *callTool); err != nil {
		log.Fatal(err)
	}
}
