{"content":"package main

import (
	"context"
	"fmt"
	"log"
	"os"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	server := mcp.NewServer(
		&mcp.Implementation{
			Name:    "hello-server",
			Version: "1.0.0",
		},
		nil,
	)

	// Define the tool
	tool := &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns Hello, MCP World!",
	}

	// Add the tool to the server
	// We use any as we don't need input arguments for this tool
	mcp.AddTool(server, tool, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				&mcp.TextContent{
					Text: "Hello, MCP World!",
				},
			},
		}, nil, nil
	})

	// Run the server on stdio transport
	if err := server.Run(context.Background(), &mcp.StdioTransport{}); err != nil {
		fmt.Fprintf(os.Stderr, "Server failed: %v\n", err)
		os.Exit(1)
	}
}
