{"content":"package client

import (
	"bytes"
	"context"
	"io"
	"strings"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-server-client/internal/server"
)

func TestClient(t *testing.T) {
	s := server.NewHelloServer()

	// Create pipes for communication
	r1, w1 := io.Pipe()
	r2, w2 := io.Pipe()

	serverTransport := &mcp.IOTransport{
		Reader: r1,
		Writer: w2,
	}
	clientTransport := &mcp.IOTransport{
		Reader: r2,
		Writer: w1,
	}

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Run server in a goroutine
	go func() {
		if err := s.Run(ctx, serverTransport); err != nil && err != context.Canceled {
			t.Errorf("Server failed: %v", err)
		}
	}()

	c := NewClient()
	if err := c.Connect(ctx, clientTransport); err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer c.Close()

	t.Run("ListTools", func(t *testing.T) {
		var buf bytes.Buffer
		if err := c.ListTools(ctx, &buf); err != nil {
			t.Fatalf("ListTools failed: %v", err)
		}
		got := buf.String()
		if !strings.Contains(got, "hello_world") {
			t.Errorf("Expected output to contain 'hello_world', got %q", got)
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		var buf bytes.Buffer
		if err := c.CallTool(ctx, "hello_world", &buf); err != nil {
			t.Fatalf("CallTool failed: %v", err)
		}
		got := strings.TrimSpace(buf.String())
		if got != "Hello, MCP World!" {
			t.Errorf("Expected 'Hello, MCP World!', got %q", got)
		}
	})
}
