{"content":"package client

import (
	"context"
	"fmt"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// Config holds the client configuration.
type Config struct {
	ServerPath string
}

// Client represents an MCP client.
type Client struct {
	cfg    Config
	mcpCli *mcp.Client
}

// NewClient creates a new MCP client.
func NewClient(cfg Config) *Client {
	return &Client{
		cfg: cfg,
		mcpCli: mcp.NewClient(&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		}, nil),
	}
}

// Run executes the client logic using the configured ServerPath.
func (c *Client) Run(ctx context.Context, listTools bool, callTool string) error {
	cmd := exec.Command(c.cfg.ServerPath)
	cmd.Stderr = os.Stderr
	transport := &mcp.CommandTransport{Command: cmd}
	return c.RunWithTransport(ctx, transport, listTools, callTool)
}

// RunWithTransport executes the client logic using the provided transport.
func (c *Client) RunWithTransport(ctx context.Context, transport mcp.Transport, listTools bool, callTool string) error {
	session, err := c.mcpCli.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	if listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		fmt.Println("tools:")
		for _, tool := range tools.Tools {
			fmt.Printf("- %s\n", tool.Name)
		}
	}

	if callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool %s: %w", callTool, err)
		}

		for _, content := range res.Content {
			if textContent, ok := content.(*mcp.TextContent); ok {
				fmt.Println(textContent.Text)
			}
		}
	}

	return nil
}
