func TestClient_RunWithTransport(t *testing.T) {
	ctx := context.Background()
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	s := server.NewHelloServer()
	serverSession, err := s.Connect(ctx, serverTransport, nil)
	if err != nil {
		t.Fatalf("Failed to connect server: %v", err)
	}
	defer serverSession.Close()

	c := NewClient(Config{})

	t.Run("ListTools", func(t *testing.T) {
		err := c.RunWithTransport(ctx, clientTransport, true, "")
		if err != nil {
			t.Errorf("RunWithTransport failed: %v", err)
		}
	})

	// Reconnect for the second test because session.Close() is called in RunWithTransport
	serverTransport2, clientTransport2 := mcp.NewInMemoryTransports()
	serverSession2, _ := s.Connect(ctx, serverTransport2, nil)
	defer serverSession2.Close()

	t.Run("CallTool", func(t *testing.T) {
		err := c.RunWithTransport(ctx, clientTransport2, false, "hello_world")
		if err != nil {
			t.Errorf("RunWithTransport failed: %v", err)
		}
	})
}
