}

func Run(ctx context.Context, args []string, out io.Writer) error {
	fs := flag.NewFlagSet("client", flag.ContinueOnError)
	listTools := fs.Bool("list-tools", false, "List available tools")
	callTool := fs.String("call-tool", "", "Call a tool by name")
	if err := fs.Parse(args); err != nil {
		return err
	}

	if !*listTools && *callTool == "" {
		fs.Usage()
		return fmt.Errorf("no flags provided")
	}

	// Connect to the server using stdio
	// We assume the server binary is at ./bin/server
	cmd := exec.Command("./bin/server")
	transport := &mcp.CommandTransport{Command: cmd}

	c := client.NewClient()
	if err := c.Connect(ctx, transport); err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer c.Close()

	if *listTools {
		if err := c.ListTools(ctx, out); err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
	}

	if *callTool != "" {
		if err := c.CallTool(ctx, *callTool, out); err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
	}
	return nil
}
