{"content":"package client

import (
	"context"
	"fmt"
	"io"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type HelloClient struct {
	mcpClient *mcp.Client
}

func NewHelloClient() *HelloClient {
	return &HelloClient{
		mcpClient: mcp.NewClient(
			&mcp.Implementation{
				Name:    "hello-client",
				Version: "1.0.0",
			},
			nil,
		),
	}
}

func (c *HelloClient) ListTools(ctx context.Context, transport mcp.Transport, w io.Writer) error {
	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	defer session.Close()

	result, err := session.ListTools(ctx, nil)
	if err != nil {
		return err
	}

	for _, tool := range result.Tools {
		fmt.Fprintln(w, tool.Name)
	}
	return nil
}

func (c *HelloClient) CallTool(ctx context.Context, transport mcp.Transport, toolName string, w io.Writer) error {
	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	defer session.Close()

	params := &mcp.CallToolParams{
		Name: toolName,
	}
	result, err := session.CallTool(ctx, params)
	if err != nil {
		return err
	}

	for _, content := range result.Content {
		if textContent, ok := content.(*mcp.TextContent); ok {
			fmt.Fprint(w, textContent.Text)
		}
	}
	fmt.Fprintln(w)
	return nil
}
