func TestHelloClient(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	t1, t2 := mcp.NewInMemoryTransports()

	// Start a real server on t1
	s := server.NewHelloServer()
	go func() {
		_ = s.Run(ctx, t1)
	}()

	hc := NewHelloClient()

	t.Run("ListTools", func(t *testing.T) {
		var buf bytes.Buffer
		if err := hc.ListTools(ctx, t2, &buf); err != nil {
			t.Fatalf("ListTools failed: %v", err)
		}
		expected := "hello_world\n"
		if buf.String() != expected {
			t.Errorf("Expected %q, got %q", expected, buf.String())
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		var buf bytes.Buffer
		// Need new transport as previous one might be closed or consumed
		// Actually t2 is linked to t1, if session.Close() was called, we might need new ones.
		// My HelloClient calls session.Close() in each method.
		// So I need to reconnect. NewInMemoryTransports are one-shot usually?
		// Let's check if I can reuse or need new ones.
	})
}
