{"content":"package client

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-hello-world/internal/server"
)

func TestClient(t *testing.T) {
	ctx := context.Background()

	// Create server and client
	s := server.NewHelloServer()
	c := NewClient("test-client", "1.0.0")

	// Use in-memory transports
	t1, t2 := mcp.NewInMemoryTransports()

	// Connect server
	ss, err := s.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatalf("failed to connect server: %v", err)
	}
	defer ss.Close()

	// Connect client
	cs, err := c.mcpClient.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("failed to connect client: %v", err)
	}
	c.session = cs
	defer c.Close()

	// Test ListTools
	tools, err := c.ListTools(ctx)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}
	found := false
	for _, name := range tools {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("hello_world tool not found")
	}

	// Test CallTool
	contents, err := c.CallTool(ctx, "hello_world")
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}
	if len(contents) != 1 {
		t.Fatalf("expected 1 content, got %d", len(contents))
	}
	if contents[0] != "Hello, MCP World!" {
		t.Errorf("expected %q, got %q", "Hello, MCP World!", contents[0])
	}
}
