func run() error {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server", "./bin/server", "Path to server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		return fmt.Errorf("either --list-tools or --call-tool must be provided")
	}

	ctx := context.Background()
	c := client.NewClient("hello-client", "1.0.0")

	if err := c.Connect(ctx, *serverPath); err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer c.Close()

	if *listTools {
		names, err := c.ListTools(ctx)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, name := range names {
			fmt.Println(name)
		}
	}

	if *callTool != "" {
		contents, err := c.CallTool(ctx, *callTool)
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range contents {
			fmt.Println(content)
		}
	}
	return nil
}
