{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()

	// Assuming the server binary is in ./bin/server relative to the execution context
	// or we can just use the path to the binary.
	// For the sake of this task, let's assume it's in the same directory or ./bin/server.
	serverPath := "./bin/server"
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		serverPath = "server" // Try PATH
	}

	cmd := exec.Command(serverPath)
	cmd.Stderr = os.Stderr // Pass through stderr for debugging

	transport := &mcp.CommandTransport{
		Command: cmd,
	}

	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "1.0.0",
		},
		nil,
	)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer session.Close()

	if *listTools {
		result, err := session.ListTools(ctx, nil)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, tool := range result.Tools {
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		params := &mcp.CallToolParams{
			Name:      *callTool,
			Arguments: map[string]any{},
		}
		result, err := session.CallTool(ctx, params)
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}

		for _, content := range result.Content {
			if text, ok := content.(mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
}
