{"filename":"internal/server/server_test.go","new_content":"func TestHelloWorldTool(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	sTransport, cTransport := mcp.NewInMemoryTransports()

	s := NewHelloWorldServer()
	go func() {
		if err := s.Run(ctx, sTransport); err != nil && err != context.Canceled {
			t.Errorf("Server failed: %v", err)
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "1.0.0"}, nil)
	session, err := client.Connect(ctx, cTransport, nil)
	if err != nil {
		t.Fatalf("Failed to connect client: %v", err)
	}
	defer session.Close()

	// Call the hello_world tool
	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("Failed to call tool: %v", err)
	}

	if len(result.Content) != 1 {
		t.Fatalf("Expected 1 content item, got %d", len(result.Content))
	}

	textContent, ok := result.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", result.Content[0])
	}

	expected := "Hello, MCP World!"
	if textContent.Text != expected {
		t.Errorf("Expected %q, got %q", expected, textContent.Text)
	}
}
