{"content":"package hello

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func RunClient(ctx context.Context, listTools bool, callTool string) error {
	// Use the binary path relative to the current directory
	cmd := exec.Command("./bin/server")
	transport := &mcp.CommandTransport{Command: cmd}

	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-mcp-client",
			Version: "1.0.0",
		},
		nil,
	)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	if listTools {
		tools := session.Tools(ctx, nil)
		fmt.Println("tools:")
		for tool, err := range tools {
			if err != nil {
				return fmt.Errorf("error iterating tools: %w", err)
			}
			fmt.Printf("- %s\n", tool.Name)
		}
	}

	if callTool != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range result.Content {
			if tc, ok := content.(*mcp.TextContent); ok {
				fmt.Println(tc.Text)
			}
		}
	}
	return nil
}
","filename":"pkg/hello/client.go"}

