}

func (c *ResourceLink) MarshalJSON() ([]byte, error) {
        return json.Marshal(&wireContent{
                Type:        "resource_link",
                URI:         c.URI,
                Name:        c.Name,
                Title:       c.Title,
                Description: c.Description,
                MIMEType:    c.MIMEType,
