{"content":"package client

import (
	"bytes"
	"context"
	"strings"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestRunClient(t *testing.T) {
	ctx := context.Background()
	clientTransport, serverTransport := mcp.NewInMemoryTransports()

	// Setup a simple server
	server := mcp.NewServer(
		&mcp.Implementation{
			Name:    "test-server",
			Version: "1.0.0",
		},
		nil,
	)
	server.AddTool(&mcp.Tool{Name: "hello_world"}, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				&mcp.TextContent{Text: "Hello, MCP World!"},
			},
		}, nil
	})

	go func() {
		_ = server.Run(ctx, serverTransport)
	}()

	t.Run("list tools", func(t *testing.T) {
		var out bytes.Buffer
		err := RunClient(ctx, clientTransport, true, "", &out)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
		if !strings.Contains(out.String(), "hello_world") {
			t.Errorf("Expected output to contain hello_world, got %q", out.String())
		}
	})

	// Re-connect for next test because transport is used once
	clientTransport, serverTransport = mcp.NewInMemoryTransports()
	go func() {
		_ = server.Run(ctx, serverTransport)
	}()

	t.Run("call tool", func(t *testing.T) {
		var out bytes.Buffer
		err := RunClient(ctx, clientTransport, false, "hello_world", &out)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
		if !strings.Contains(out.String(), "Hello, MCP World!") {
			t.Errorf("Expected output to contain Hello, MCP World!, got %q", out.String())
		}
	})
}
