{"content":"package client

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-example/internal/server"
)

func TestRunClient(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	clientTransport, serverTransport := mcp.NewInMemoryTransports()

	s := server.SetupServer()
	go func() {
		_ = s.Run(ctx, serverTransport)
	}()

	// Testing both list and call in one run since RunClient closes the session.
	if err := RunClient(ctx, clientTransport, true, "hello_world"); err != nil {
		t.Errorf("RunClient failed: %v", err)
	}
}

func TestRunClient_ConnectError(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Use a transport that fails or is already closed.
	_, serverTransport := mcp.NewInMemoryTransports()
	// clientTransport is not used here, we want it to fail.

    // Actually, let's just use a nil transport if allowed or something that fails.
    err := RunClient(ctx, nil, false, "")
    if err == nil {
        t.Error("expected error with nil transport")
    }
}
