func TestRunClient(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	sTransport, cTransport := mcp.NewInMemoryTransports()

	s := server.NewHelloWorldServer()
	go func() {
		if err := s.Run(ctx, sTransport); err != nil && err != context.Canceled {
			t.Errorf("Server failed: %v", err)
		}
	}()

	t.Run("list tools", func(t *testing.T) {
		var stdout bytes.Buffer
		err := RunClient(ctx, cTransport, true, "", &stdout)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}

		output := stdout.String()
		if !strings.Contains(output, "hello_world") {
			t.Errorf("Expected output to contain 'hello_world', got %q", output)
		}
	})

	// Note: We need a new transport for the next call because transports are one-time use
	sTransport2, cTransport2 := mcp.NewInMemoryTransports()
	go func() {
		if err := s.Run(ctx, sTransport2); err != nil && err != context.Canceled {
			t.Errorf("Server failed: %v", err)
		}
	}()

	t.Run("call tool", func(t *testing.T) {
		var stdout bytes.Buffer
		err := RunClient(ctx, cTransport2, false, "hello_world", &stdout)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}

		output := strings.TrimSpace(stdout.String())
		expected := "Hello, MCP World!"
		if output != expected {
			t.Errorf("Expected %q, got %q", expected, output)
		}
	})
}
