{"content":"package client

import (
	"context"
	"fmt"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// RunClient performs client operations using the provided transport.
func RunClient(ctx context.Context, transport mcp.Transport, listTools bool, callTool string) error {
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "example-client",
		Version: "1.0.0",
	}, nil)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	if listTools {
		res, err := session.ListTools(ctx, nil)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, tool := range res.Tools {
			fmt.Println(tool.Name)
		}
	}

	if callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range res.Content {
			if tc, ok := content.(*mcp.TextContent); ok {
				fmt.Println(tc.Text)
			}
		}
	}
	return nil
}

// RunClientWithSubprocess starts a server process and runs the client against it.
func RunClientWithSubprocess(ctx context.Context, serverPath string, listTools bool, callTool string) error {
	cmd := exec.Command(serverPath)
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return err
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return err
	}
	cmd.Stderr = os.Stderr

	if err := cmd.Start(); err != nil {
		return err
	}
	defer func() {
		_ = cmd.Process.Kill()
	}()

	transport := &mcp.IOTransport{
		Reader: stdout,
		Writer: stdin,
	}

	return RunClient(ctx, transport, listTools, callTool)
}
