// NewHelloWorldServer creates a new MCP server with a hello_world tool.
func NewHelloWorldServer() *mcp.Server {
	s := mcp.NewServer(
		&mcp.Implementation{
			Name:    "hello-world-server",
			Version: "1.0.0",
		},
		nil,
	)

	tool := &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns 'Hello, MCP World!'",
		InputSchema: map[string]any{
			"type": "object",
		},
	}

	s.AddTool(tool, HelloWorldHandler)
	return s
}

// HelloWorldHandler is the handler for the hello_world tool.
func HelloWorldHandler(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
	return &mcp.CallToolResult{
		Content: []mcp.Content{
			&mcp.TextContent{
				Text: "Hello, MCP World!",
			},
		},
	}, nil
}
