{"content":"package client

import (
	"context"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// ListTools lists tool names using the provided MCP session.
func ListTools(ctx context.Context, session *mcp.ClientSession) ([]string, error) {
	res, err := session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, t := range res.Tools {
		names = append(names, t.Name)
	}
	return names, nil
}

// CallTool calls a tool by name and returns the text result.
func CallTool(ctx context.Context, session *mcp.ClientSession, name string) (string, error) {
	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return "", err
	}
	var result string
	for _, content := range res.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			result += text.Text
		}
	}
	return result, nil
}
