{"content":"package client

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/user/mcp-hello-world/pkg/server"
)

func TestClient(t *testing.T) {
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	s := server.NewHelloWorldServer()
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		_ = s.Run(ctx, serverTransport)
	}()

	c := mcp.NewClient(&mcp.Implementation{Name: "test", Version: "1"}, nil)
	session, err := c.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("failed to connect: %v", err)
	}
	defer session.Close()

	tools, err := ListTools(ctx, session)
	if err != nil {
		t.Fatalf("failed to list tools: %v", err)
	}

	found := false
	for _, name := range tools {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("expected to find hello_world tool")
	}

	result, err := CallTool(ctx, session, "hello_world")
	if err != nil {
		t.Fatalf("failed to call tool: %v", err)
	}
	if result != "Hello, MCP World!" {
		t.Errorf("expected 'Hello, MCP World!', got %q", result)
	}
}
