{"content":"package main

import (
	"context"
	"fmt"
	"os"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
}

func run() error {
	ctx := context.Background()

	server := mcp.NewServer(
		&mcp.Implementation{
			Name:    "hello-server",
			Version: "v0.1.0",
		},
		nil,
	)

	server.AddTool(&mcp.Tool{
		Name:        "hello_world",
		Description: "Returns a hello world message",
		InputSchema: mcp.EmptySchema,
	}, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				mcp.TextContent{Text: "Hello, MCP World!"},
			},
		}, nil
	})

	transport := &mcp.StdioTransport{}
	session, err := server.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	defer session.Close()

	// The session will run until it's closed or the context is cancelled.
	// Since it's using StdioTransport, it will read from Stdin.
	<-session.Done()
	return nil
}
