{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	if err := run(*listTools, *callTool, *serverPath); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
}

func run(listTools bool, callToolName string, serverPath string) error {
	ctx := context.Background()

	// Start the server process
	cmd := exec.Command(serverPath)
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return err
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return err
	}
	// Redirect stderr to our stderr so we can see server errors
	cmd.Stderr = os.Stderr

	if err := cmd.Start(); err != nil {
		return fmt.Errorf("failed to start server: %w", err)
	}
	defer func() {
		_ = cmd.Process.Kill()
	}()

	// Create client
	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-client",
			Version: "v0.1.0",
		},
		nil,
	)

	// Connect to server using IOTransport
	transport := &mcp.IOTransport{
		Reader: stdout,
		Writer: stdin,
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if callToolName != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callToolName,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool %s: %w", err)
		}

		for _, content := range result.Content {
			if textContent, ok := content.(mcp.TextContent); ok {
				fmt.Println(textContent.Text)
			} else if textContent, ok := content.(*mcp.TextContent); ok {
                fmt.Println(textContent.Text)
            }
		}
	}

	return nil
}
