{"content":"package mcpapp

import (
	"context"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func NewHelloWorldServer() *mcp.Server {
	server := mcp.NewServer(
		&mcp.Implementation{
			Name:    "hello-server",
			Version: "v0.1.0",
		},
		nil,
	)

	server.AddTool(&mcp.Tool{
		Name:        "hello_world",
		Description: "Returns a hello world message",
		InputSchema: mcp.EmptySchema,
	}, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				mcp.TextContent{Text: "Hello, MCP World!"},
			},
		}, nil
	})

	return server
}

type Client struct {
	Session *mcp.ClientSession
}

func NewClient(ctx context.Context, transport mcp.Transport) (*Client, error) {
	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-client",
			Version: "v0.1.0",
		},
		nil,
	)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}

	return &Client{Session: session}, nil
}

func (c *Client) ListTools(ctx context.Context) ([]string, error) {
	tools, err := c.Session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, tool := range tools.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

func (c *Client) CallHelloWorld(ctx context.Context) (string, error) {
	result, err := c.Session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		return "", err
	}

	var output string
	for _, content := range result.Content {
		switch v := content.(type) {
		case mcp.TextContent:
			output += v.Text
		case *mcp.TextContent:
			output += v.Text
		}
	}
	return output, nil
}
