{"content":"package hello

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloHandler(t *testing.T) {
	ctx := context.Background()
	res, extra, err := HelloHandler(ctx, nil, struct{}{})
	if err != nil {
		t.Fatalf("Unexpected error: %v", err)
	}
	if extra != nil {
		t.Errorf("Expected extra to be nil, got %v", extra)
	}

	if len(res.Content) != 1 {
		t.Fatalf("Expected 1 content item, got %d", len(res.Content))
	}

	text, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", res.Content[0])
	}

	expected := "Hello, MCP World!"
	if text.Text != expected {
		t.Errorf("Expected %q, got %q", expected, text.Text)
	}
}

func TestNewHelloServer(t *testing.T) {
	server := NewHelloServer()
	if server == nil {
		t.Fatal("Expected server to be non-nil")
	}
}
