{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// App runs the client application logic.
func App(listTools bool, callTool string, serverPath string) error {
	cmd := exec.Command(serverPath)
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return fmt.Errorf("stdin pipe: %w", err)
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return fmt.Errorf("stdout pipe: %w", err)
	}

	if err := cmd.Start(); err != nil {
		return fmt.Errorf("start server: %w", err)
	}
	defer func() {
		_ = cmd.Process.Kill()
	}()

	transport := &mcp.IOTransport{
		Reader: stdout,
		Writer: stdin,
	}

	c := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "1.0.0",
		},
		nil,
	)

	ctx := context.Background()
	session, err := c.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("connect: %w", err)
	}
	defer session.Close()

	if listTools {
		tools, err := ListTools(ctx, session)
		if err != nil {
			return fmt.Errorf("list tools: %w", err)
		}
		for _, name := range tools {
			fmt.Println(name)
		}
	}

	if callTool != "" {
		result, err := CallTool(ctx, session, callTool)
		if err != nil {
			return fmt.Errorf("call tool: %w", err)
		}
		fmt.Println(result)
	}
	return nil
}
","file_path":"pkg/client/app.go"}

{"filename":"cmd/client/main.go","new_content":"func run(listTools bool, callToolName string, serverPath string) error {
	ctx := context.Background()

	// Start the server process
	cmd := exec.Command(serverPath)
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return err
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return err
	}
	// Redirect stderr to our stderr so we can see server errors
	cmd.Stderr = os.Stderr

	if err := cmd.Start(); err != nil {
		return fmt.Errorf("failed to start server: %w", err)
	}
	defer func() {
		_ = cmd.Process.Kill()
	}()

	// Connect to server using IOTransport
	transport := &mcp.IOTransport{
		Reader: stdout,
		Writer: stdin,
	}

	client, err := mcpapp.NewClient(ctx, transport)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer client.Session.Close()

	if listTools {
		names, err := client.ListTools(ctx)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, name := range names {
			fmt.Println(name)
		}
	}

	if callToolName == "hello_world" {
		output, err := client.CallHelloWorld(ctx)
		if err != nil {
			return fmt.Errorf("failed to call tool %s: %w", err)
		}
		fmt.Println(output)
	} else if callToolName != "" {
		return fmt.Errorf("unknown tool: %s", callToolName)
	}

	return nil
}
