{"content":"package mcpapp

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorld(t *testing.T) {
	ctx := context.Background()
	server := NewHelloWorldServer()

	t1, t2 := mcp.NewInMemoryTransports()

	// Connect server
	serverSession, err := server.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatalf("failed to connect server: %v", err)
	}
	defer serverSession.Close()

	// Connect client
	client, err := NewClient(ctx, t2)
	if err != nil {
		t.Fatalf("failed to connect client: %v", err)
	}
	defer client.Session.Close()

	// Test ListTools
	tools, err := client.ListTools(ctx)
	if err != nil {
		t.Errorf("ListTools failed: %v", err)
	}
	found := false
	for _, name := range tools {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("tool hello_world not found in %v", tools)
	}

	// Test CallHelloWorld
	result, err := client.CallHelloWorld(ctx)
	if err != nil {
		t.Errorf("CallHelloWorld failed: %v", err)
	}
	expected := "Hello, MCP World!"
	if result != expected {
		t.Errorf("expected %q, got %q", expected, result)
	}
}
