{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "v1.0.0",
	}, nil)

	// In a real scenario, we might want to point to the server binary.
	// For this task, the client will start the server.
	transport := &mcp.CommandTransport{
		Command: exec.Command("./bin/server"),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer session.Close()

	if *listTools {
		// Use the Tools iterator or ListTools if available.
		// Looking at the SDK, it seems to use iterators for listing.
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}

		for _, content := range res.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
}
