	cwd, _ := os.Getwd()
	serverPath := filepath.Join(cwd, "..", "..", "bin", "server")

	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		t.Skip("bin/server not found, skipping App test")
	}

	err := App(true, "hello_world", serverPath)
	if err != nil {
		t.Fatalf("App failed: %v", err)
	}
}
