{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/user/mcp-hello-world/pkg/hello"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	cmd := exec.Command(*serverPath)
	transport := &mcp.CommandTransport{Command: cmd}

	client, err := hello.NewClient(ctx, transport)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer client.Close()

	if *listTools {
		tools := client.ListTools(ctx)
		fmt.Println("tools:")
		for tool, err := range tools {
			if err != nil {
				log.Fatalf("Error iterating tools: %v", err)
			}
			fmt.Printf("\t%s\n", tool.Name)
		}
	}

	if *callTool != "" {
		// For the sake of the requirement, if callTool is hello_world, use CallHello
		if *callTool == "hello_world" {
			msg, err := client.CallHello(ctx)
			if err != nil {
				log.Fatalf("Failed to call tool: %v", err)
			}
			fmt.Println(msg)
		} else {
			// Generic call
			result, err := client.Session.CallTool(ctx, &mcp.CallToolParams{
				Name: *callTool,
			})
			if err != nil {
				log.Fatalf("Failed to call tool: %v", err)
			}
			for _, content := range result.Content {
				if text, ok := content.(*mcp.TextContent); ok {
					fmt.Println(text.Text)
				}
			}
		}
	}
}
