{"content":"package hello

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestClientServer(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	server := NewHelloServer()
	go func() {
		if err := server.Run(ctx, serverTransport); err != nil {
			// ignore error on shutdown
		}
	}()

	client, err := NewClient(ctx, clientTransport)
	if err != nil {
		t.Fatalf("Failed to create client: %v", err)
	}
	defer client.Close()

	// Test ListTools
	tools := client.ListTools(ctx)
	found := false
	for tool, err := range tools {
		if err != nil {
			t.Fatalf("Error listing tools: %v", err)
		}
		if tool.Name == "hello_world" {
			found = true
		}
	}
	if !found {
		t.Error("hello_world tool not found")
	}

	// Test CallHello
	msg, err := client.CallHello(ctx)
	if err != nil {
		t.Fatalf("Failed to call hello_world: %v", err)
	}
	expected := "Hello, MCP World!"
	if msg != expected {
		t.Errorf("Expected %q, got %q", expected, msg)
	}
}
