{"content":"package hello

import (
	"context"
	"fmt"
	"iter"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	Session *mcp.ClientSession
}

func NewClient(ctx context.Context, transport mcp.Transport) (*Client, error) {
	mcpClient := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	cs, err := mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}

	return &Client{Session: cs}, nil
}

func (c *Client) Close() error {
	return c.Session.Close()
}

func (c *Client) ListTools(ctx context.Context) iter.Seq2[*mcp.Tool, error] {
	return c.Session.Tools(ctx, nil)
}

func (c *Client) CallHello(ctx context.Context) (string, error) {
	result, err := c.Session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		return "", err
	}

	for _, content := range result.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			return text.Text, nil
		}
	}
	return "", fmt.Errorf("no text content in result")
}

func RunClient(ctx context.Context, serverPath string, listTools bool, callTool string) error {
	cmd := exec.Command(serverPath)
	transport := &mcp.CommandTransport{Command: cmd}

	client, err := NewClient(ctx, transport)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer client.Close()

	if listTools {
		tools := client.ListTools(ctx)
		fmt.Println("tools:")
		for tool, err := range tools {
			if err != nil {
				return fmt.Errorf("error iterating tools: %w", err)
			}
			fmt.Printf("\t%s\n", tool.Name)
		}
	}

	if callTool != "" {
		if callTool == "hello_world" {
			msg, err := client.CallHello(ctx)
			if err != nil {
				return fmt.Errorf("failed to call tool: %w", err)
			}
			fmt.Println(msg)
		} else {
			result, err := client.Session.CallTool(ctx, &mcp.CallToolParams{
				Name: callTool,
			})
			if err != nil {
				return fmt.Errorf("failed to call tool: %w", err)
			}
			for _, content := range result.Content {
				if text, ok := content.(*mcp.TextContent); ok {
					fmt.Println(text.Text)
				}
			}
		}
	}
	return nil
}
