{"content":"package client

import (
	"context"
	"fmt"
	"io"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
	session   *mcp.Session
}

func NewClient(name, version string) *Client {
	return &Client{
		mcpClient: mcp.NewClient(&mcp.Implementation{
			Name:    name,
			Version: version,
		}, nil),
	}
}

func (c *Client) Connect(ctx context.Context, serverPath string, stderr io.Writer) error {
	cmd := exec.CommandContext(ctx, serverPath)
	cmd.Stderr = stderr
	transport := &mcp.CommandTransport{
		Command: cmd,
	}

	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	c.session = session
	return nil
}

func (c *Client) Close() error {
	if c.session != nil {
		return c.session.Close()
	}
	return nil
}

func (c *Client) ListTools(ctx context.Context) ([]mcp.Tool, error) {
	res, err := c.session.ListTools(ctx, &mcp.ListToolsParams{})
	if err != nil {
		return nil, err
	}
	return res.Tools, nil
}

func (c *Client) CallTool(ctx context.Context, name string) ([]string, error) {
	res, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return nil, err
	}
	if res.IsError {
		return nil, fmt.Errorf("tool returned error")
	}
	var results []string
	for _, content := range res.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			results = append(results, text.Text)
		}
	}
	return results, nil
}
