{"content":"package server

import (
	"context"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// HelloWorldHandler is the implementation of the hello_world tool.
func HelloWorldHandler(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
	return &mcp.CallToolResult{
		Content: []mcp.Content{
			&mcp.TextContent{Text: "Hello, MCP World!"},
		},
	}, nil, nil
}

// NewHelloWorldServer creates a new MCP server with the hello_world tool.
func NewHelloWorldServer() *mcp.Server {
	s := mcp.NewServer(&mcp.Implementation{
		Name:    "hello-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(s, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns a hello message",
	}, HelloWorldHandler)

	return s
}
