{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"os"

	"mcp-hello-world/internal/client"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	c := client.NewClient("hello-world-client", "1.0.0")

	if err := c.Connect(ctx, *serverPath, os.Stderr); err != nil {
		fmt.Fprintf(os.Stderr, "Failed to connect to server: %v\n", err)
		os.Exit(1)
	}
	defer c.Close()

	if *listTools {
		tools, err := c.ListTools(ctx)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Failed to list tools: %v\n", err)
			os.Exit(1)
		}
		for _, tool := range tools {
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		results, err := c.CallTool(ctx, *callTool)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Failed to call tool: %v\n", err)
			os.Exit(1)
		}
		for _, res := range results {
			fmt.Println(res)
		}
	}
}
