{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "mcp-client",
		Version: "1.0.0",
	}, nil)

	transport := &mcp.CommandTransport{
		Command: exec.Command(*serverPath),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("failed to connect: %v", err)
	}
	defer session.Close()

	if *listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			log.Fatalf("failed to list tools: %v", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		params := &mcp.CallToolParams{
			Name: *callTool,
		}
		res, err := session.CallTool(ctx, params)
		if err != nil {
			log.Fatalf("failed to call tool: %v", err)
		}
		for _, content := range res.Content {
			if textContent, ok := content.(mcp.TextContent); ok {
				fmt.Println(textContent.Text)
			} else if textContentPtr, ok := content.(*mcp.TextContent); ok {
				fmt.Println(textContentPtr.Text)
			}
		}
	}
}
","filename":"cmd/client/main.go"}

{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type ClientApp struct {
	mcpClient *mcp.Client
	serverCmd string
}

func NewClientApp(serverCmd string) *ClientApp {
	return &ClientApp{
		mcpClient: mcp.NewClient(&mcp.Implementation{
			Name:    "demo-client",
			Version: "1.0.0",
		}, nil),
		serverCmd: serverCmd,
	}
}

func (c *ClientApp) ListTools(ctx context.Context) ([]string, error) {
	transport := &mcp.CommandTransport{
		Command: exec.Command(c.serverCmd),
	}
	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}
	defer session.Close()

	res, err := session.ListTools(ctx, &mcp.ListToolsParams{})
	if err != nil {
		return nil, err
	}

	var names []string
	for _, t := range res.Tools {
		names = append(names, t.Name)
	}
	return names, nil
}

func (c *ClientApp) CallTool(ctx context.Context, name string) ([]string, error) {
	transport := &mcp.CommandTransport{
		Command: exec.Command(c.serverCmd),
	}
	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}
	defer session.Close()

	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return nil, err
	}

	var contents []string
	for _, content := range res.Content {
		if tc, ok := content.(*mcp.TextContent); ok {
			contents = append(contents, tc.Text)
		}
	}
	return contents, nil
}
