{"content":"package client

import (
	"context"
	"os"
	"testing"
)

func TestClientIntegration(t *testing.T) {
	serverPath := "../../bin/server"
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		t.Skip("Server binary not found, skipping integration test")
	}

	ctx := context.Background()
	c := NewClient("test-client", "1.0.0")

	err := c.Connect(ctx, serverPath, os.Stderr)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer c.Close()

	tools, err := c.ListTools(ctx)
	if err != nil {
		t.Fatalf("Failed to list tools: %v", err)
	}

	found := false
	for _, tool := range tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("hello_world tool not found")
	}

	results, err := c.CallTool(ctx, "hello_world")
	if err != nil {
		t.Fatalf("Failed to call tool: %v", err)
	}

	found = false
	for _, res := range results {
		if res == "Hello, MCP World!" || res == `{"message":"Hello, MCP World!"}` {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("Expected greeting not found in results: %v", results)
	}
}
","file_path":"internal/client/client_test.go"}

{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "v1.0.0",
	}, nil)

	// In a real scenario, the server path might be configurable.
	// For this task, we assume the server is built at ./bin/server
	transport := &mcp.CommandTransport{
		Command: exec.Command("./bin/server"),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer session.Close()

	if *listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		for _, content := range res.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
}
