	"context"
	"testing"
)

func TestClientApp(t *testing.T) {
	ctx := context.Background()
	// Use the binary we built
	app := NewClientApp("../../bin/server")

	// Test ListTools
	names, err := app.ListTools(ctx)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}

	found := false
	for _, name := range names {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("Tool 'hello_world' not found in %v", names)
	}

	// Test CallTool
	contents, err := app.CallTool(ctx, "hello_world")
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}

	expected := "Hello, MCP World!"
	foundContent := false
	for _, c := range contents {
		if c == expected {
			foundContent = true
			break
		}
	}
	if !foundContent {
		t.Errorf("Expected content %q not found in %v", expected, contents)
	}
}
