{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"io"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func run(args []string, stdout io.Writer) error {
	fs := flag.NewFlagSet("mcp-client", flag.ContinueOnError)
	listTools := fs.Bool("list-tools", false, "List available tools")
	callTool := fs.String("call-tool", "", "Call a tool by name")
	serverPath := fs.String("server-path", "./bin/server", "Path to the server binary")

	if err := fs.Parse(args); err != nil {
		return err
	}

	if !*listTools && *callTool == "" {
		return fmt.Errorf("either -list-tools or -call-tool must be provided")
	}

	ctx := context.Background()
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "mcp-client",
		Version: "1.0.0",
	}, nil)

	transport := &mcp.CommandTransport{
		Command: exec.Command(*serverPath),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	if *listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, tool := range tools.Tools {
			fmt.Fprintln(stdout, tool.Name)
		}
	}

	if *callTool != "" {
		params := &mcp.CallToolParams{
			Name: *callTool,
		}
		res, err := session.CallTool(ctx, params)
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range res.Content {
			if textContent, ok := content.(*mcp.TextContent); ok {
				fmt.Fprintln(stdout, textContent.Text)
			}
		}
	}

	return nil
}

func main() {
	if err := run(os.Args[1:], os.Stdout); err != nil {
		log.Fatal(err)
	}
}
","filename":"cmd/client/main.go"}

