import (
	"context"
	"testing"
	"time"
)

func TestNewServer(t *testing.T) {
	s := NewServer("test-server", "1.0.0")
	if s == nil {
		t.Fatal("Expected server to be non-nil")
	}
}

func TestRunServer(t *testing.T) {
	s := NewServer("test-server", "1.0.0")
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()

	// RunServer will block until ctx is done or an error occurs.
	// Since StdioTransport will likely fail in a test environment without real stdin/stdout,
	// we just want to see it called.
	err := RunServer(ctx, s)
	if err != nil && err != context.DeadlineExceeded && err != context.Canceled {
		// It might return an error because of EOF on stdin, that's fine for coverage.
		t.Logf("RunServer returned error: %v", err)
	}
}
