{"content":"package main

import (
	"context"
	"strings"
	"testing"

	"mcp-example/pkg/handler"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestIntegration(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Setup Server
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "test-server",
		Version: "1.0.0",
	}, nil)
	mcp.AddTool(server, &mcp.Tool{
		Name: "hello_world",
	}, handler.HelloWorldHandler)

	t1, t2 := mcp.NewInMemoryTransports()

	go func() {
		if err := server.Connect(ctx, t1, nil); err != nil {
			t.Errorf("server connect error: %v", err)
		}
	}()

	// Setup Client
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "test-client",
		Version: "1.0.0",
	}, nil)

	session, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("client connect error: %v", err)
	}
	defer session.Close()

	// Test ListTools
	tools, err := session.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("ListTools error: %v", err)
	}

	found := false
	for _, tool := range tools.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("hello_world tool not found")
	}

	// Test CallTool
	res, err := session.CallTool(ctx, &mcp.CallToolParams{Name: "hello_world"})
	if err != nil {
		t.Fatalf("CallTool error: %v", err)
	}

	if len(res.Content) != 1 {
		t.Fatalf("expected 1 content item, got %d", len(res.Content))
	}

	textContent, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("expected *mcp.TextContent, got %T", res.Content[0])
	}

	if textContent.Text != "Hello, MCP World!" {
		t.Errorf("expected 'Hello, MCP World!', got %q", textContent.Text)
	}
}

func TestRunErrors(t *testing.T) {
	err := run([]string{}, nil)
	if err == nil {
		t.Error("expected error for empty args")
	}

	if !strings.Contains(err.Error(), "either -list-tools or -call-tool must be provided") {
		t.Errorf("unexpected error message: %v", err)
	}
}
