func TestHelloWorldHandler(t *testing.T) {
	ctx := context.Background()
	req := &mcp.CallToolRequest{}
	input := EmptyInput{}

	result, extra, err := HelloWorldHandler(ctx, req, input)
	if err != nil {
		t.Fatalf("Expected no error, got %v", err)
	}

	if extra != nil {
		t.Errorf("Expected extra to be nil, got %v", extra)
	}

	if result == nil {
		t.Fatal("Expected result to be non-nil")
	}

	if len(result.Content) != 1 {
		t.Fatalf("Expected 1 content item, got %d", len(result.Content))
	}

	textContent, ok := result.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatal("Expected content to be TextContent")
	}

	if textContent.Text != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got %q", textContent.Text)
	}
