func TestRunServer(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()

	t1, _ := mcp.NewInMemoryTransports()

	// RunServer will block until ctx is done or transport is closed.
	// Since we are using InMemoryTransport, we can just start it.
	err := RunServer(ctx, t1)
	if err != nil && err != context.DeadlineExceeded {
		t.Fatalf("RunServer failed: %v", err)
	}
}
