func TestRunClient(t *testing.T) {
	// Find the server binary. We assume it's in ../../bin/server
	serverPath := filepath.Join("..", "..", "bin", "server")
	if _, err := os.Stat(serverPath); err != nil {
		t.Skip("bin/server not found, skipping integration test")
	}

	ctx := context.Background()

	t.Run("list-tools", func(t *testing.T) {
		err := RunClient(ctx, serverPath, true, "")
		if err != nil {
			t.Errorf("RunClient(listTools=true) failed: %v", err)
		}
	})

	t.Run("call-tool", func(t *testing.T) {
		err := RunClient(ctx, serverPath, false, "hello_world")
		if err != nil {
			t.Errorf("RunClient(callTool=hello_world) failed: %v", err)
		}
	})
}
