func main() {
	server := mcp.NewServer(
		&mcp.Implementation{
			Name:    "hello-server",
			Version: "1.0.0",
		},
		&mcp.ServerOptions{
			Capabilities: &mcp.ServerCapabilities{
				Tools: &mcp.ToolCapabilities{ListChanged: true},
			},
		},
	)

	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
