{"content":"package main

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloServer(t *testing.T) {
	ctx := context.Background()
	server := NewHelloServer()

	// Use in-memory transports for testing
	t1, t2 := mcp.NewInMemoryTransports()

	go func() {
		if _, err := server.Connect(ctx, t1, nil); err != nil {
			panic(err)
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "1.0.0"}, nil)
	session, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("failed to connect: %v", err)
	}
	defer session.Close()

	// Test listing tools
	tools := session.Tools(ctx, nil)
	found := false
	for tool, err := range tools {
		if err != nil {
			t.Fatalf("failed to list tools: %v", err)
		}
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("tool hello_world not found")
	}

	// Test calling tool
	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("failed to call tool: %v", err)
	}

	if len(res.Content) == 0 {
		t.Fatalf("no content in result")
	}

	textContent, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("expected text content, got %T", res.Content[0])
	}

	if textContent.Text != "Hello, MCP World!" {
		t.Errorf("expected 'Hello, MCP World!', got '%s'", textContent.Text)
	}
}
