{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// ListTools lists available tools from the MCP server.
func ListTools(ctx context.Context, serverPath string) error {
	c := mcp.NewClient(&mcp.Implementation{Name: "demo-client", Version: "1.0.0"}, nil)
	transport := &mcp.CommandTransport{
		Command: exec.CommandContext(ctx, serverPath),
	}
	session, err := c.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	res, err := session.ListTools(ctx, &mcp.ListToolsParams{})
	if err != nil {
		return fmt.Errorf("failed to list tools: %w", err)
	}

	for _, tool := range res.Tools {
		fmt.Println(tool.Name)
	}
	return nil
}

// CallTool calls a specific tool on the MCP server.
func CallTool(ctx context.Context, serverPath string, toolName string) error {
	c := mcp.NewClient(&mcp.Implementation{Name: "demo-client", Version: "1.0.0"}, nil)
	transport := &mcp.CommandTransport{
		Command: exec.CommandContext(ctx, serverPath),
	}
	session, err := c.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: toolName,
	})
	if err != nil {
		return fmt.Errorf("failed to call tool: %w", err)
	}

	for _, content := range res.Content {
		switch c := content.(type) {
		case mcp.TextContent:
			fmt.Println(c.Text)
		case *mcp.TextContent:
			fmt.Println(c.Text)
		}
	}
	return nil
}
