{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"github.com/user/mcp-demo/internal/client"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	// Default server path
	serverPath := "./bin/server"
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		// Try absolute path if relative fails
		cwd, _ := os.Getwd()
		serverPath = filepath.Join(cwd, "bin", "server")
	}

	ctx := context.Background()

	if *listTools {
		if err := client.ListTools(ctx, serverPath); err != nil {
			log.Fatalf("Error listing tools: %v", err)
		}
		return
	}

	if *callTool != "" {
		if err := client.CallTool(ctx, serverPath, *callTool); err != nil {
			log.Fatalf("Error calling tool: %v", err)
		}
		return
	}

	flag.Usage()
	os.Exit(1)
}
