{"content":"package server

import (
	"context"
	"testing"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestNewServer(t *testing.T) {
	s := NewServer()
	if s == nil {
		t.Fatal("expected server to be non-nil")
	}

	ctx := context.Background()
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	go func() {
		if err := s.Run(ctx, serverTransport); err != nil {
			// server might return error on close, which is fine in test
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "1.0.0"}, nil)
	session, err := client.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("failed to connect: %v", err)
	}
	defer session.Close()

	res, err := session.ListTools(ctx, &mcp.ListToolsParams{})
	if err != nil {
		t.Fatalf("failed to list tools: %v", err)
	}

	found := false
	for _, tool := range res.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}

	if !found {
		t.Error("hello_world tool not found")
	}

	callRes, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("failed to call tool: %v", err)
	}

	if len(callRes.Content) == 0 {
		t.Fatal("expected content in call result")
	}

	content := callRes.Content[0]
	var text string
	switch c := content.(type) {
	case mcp.TextContent:
		text = c.Text
	case *mcp.TextContent:
		text = c.Text
	default:
		t.Fatalf("unexpected content type: %T", content)
	}

	expected := "Hello, MCP World!"
	if text != expected {
		t.Errorf("expected %q, got %q", expected, text)
	}
}
