func TestClient(t *testing.T) {
	ctx := context.Background()

	s := server.NewHelloWorldServer()

	client := NewClient("test-client", "1.0.0")

	t1, t2 := mcp.NewInMemoryTransports()

	_, err := s.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatalf("failed to connect server: %v", err)
	}

	session, err := client.mcpClient.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("failed to connect client: %v", err)
	}
	client.session = session
	defer client.Close()

	tools, err := client.ListTools(ctx)
	if err != nil {
		t.Fatalf("failed to list tools: %v", err)
	}

	found := false
	for _, name := range tools {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("hello_world tool not found")
	}

	text, err := client.CallHelloWorld(ctx)
	if err != nil {
		t.Fatalf("failed to call hello_world: %v", err)
	}

	if text != "Hello, MCP World!" {
		t.Errorf("expected 'Hello, MCP World!', got %q", text)
	}
}

func TestNewClient(t *testing.T) {
	c := NewClient("name", "v1")
	if c == nil {
		t.Fatal("expected client to be non-nil")
	}
