func TestClient_Errors(t *testing.T) {
	ctx := context.Background()
	client := NewClient("test-client", "1.0.0")

	// Test ListTools without session
	_, err := client.ListTools(ctx)
	if err == nil {
		t.Error("expected error listing tools without session")
	}

	// Test CallHelloWorld without session
	_, err = client.CallHelloWorld(ctx)
	if err == nil {
		t.Error("expected error calling hello_world without session")
	}

	// Test Close without session
	err = client.Close()
	if err != nil {
		t.Errorf("unexpected error closing without session: %v", err)
	}
}

func TestClient_ConnectError(t *testing.T) {
	ctx := context.Background()
	client := NewClient("test-client", "1.0.0")

	// Test connect to non-existent server
