{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	transport := &mcp.CommandTransport{
		Command: exec.Command("./bin/server"),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	if *listTools {
		result, err := session.ListTools(ctx, nil)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, tool := range result.Tools {
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
}
","filename":"cmd/client/main.go"}

{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	ctx := context.Background()

	client := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		},
		nil,
	)

	// Since we are using stdio transport, we need to run the server as a subprocess
	// but the requirement says "Create a client that connects with the server over stdio".
	// Usually this means the client spawns the server.
	// However, if the client is just using its own stdin/stdout to talk to something that spawned it,
	// it would also use StdioTransport.
	// Given the prompt: "./bin/client --list-tools", it seems the client should start the server.

	// But wait, the SDK's StdioTransport uses os.Stdin and os.Stdout.
	// If I want to spawn a subprocess, I should probably use something else or configure it.

	// Let's check if there is a way to pass a command to a transport.
	// Looking at transport.go again, I see IOTransport which takes Reader and Writer.

	serverCmd := "./bin/server"
	if _, err := os.Stat(serverCmd); os.IsNotExist(err) {
		// If bin/server doesn't exist, maybe we are running from source or it's not built yet.
		// For the purpose of the client, we'll assume it's there.
	}

	importPath := "github.com/modelcontextprotocol/go-sdk/mcp"
	_ = importPath

	// To talk to the server over stdio, we spawn it and use its pipes.

	if *listTools || *callTool != "" {
		runClient(ctx, client, serverCmd, *listTools, *callTool)
	} else {
		flag.Usage()
	}
}

func runClient(ctx context.Context, client *mcp.Client, serverPath string, list bool, call string) {
	// Start server process
	cmd := os.CommandContext(ctx, serverPath)
	stdin, err := cmd.StdinPipe()
	if err != nil {
		log.Fatal(err)
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		log.Fatal(err)
	}
	stderr, err := cmd.StderrPipe()
	if err != nil {
		log.Fatal(err)
	}
	// Pipe stderr to our stderr for debugging
	go func() {
		// Use a simple copy, we don't care about errors here
		_, _ = os.Stderr.ReadFrom(stderr)
	}()

	if err := cmd.Start(); err != nil {
		log.Fatalf("failed to start server: %v", err)
	}
	defer cmd.Process.Kill()

	transport := &mcp.IOTransport{
		Reader: stdout,
		Writer: stdin,
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("failed to connect to server: %v", err)
	}
	defer session.Close()

	if list {
		for tool, err := range session.Tools(ctx, nil) {
			if err != nil {
				log.Fatal(err)
			}
			fmt.Println(tool.Name)
		}
	}

	if call != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: call,
		})
		if err != nil {
			log.Fatal(err)
		}
		for _, content := range res.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
}
","filename":"cmd/client/main.go"}

