func Run() {
	if err := run(context.Background(), os.Args[1:], os.Stdout, os.Stderr); err != nil {
		fmt.Fprintf(os.Stderr, "%v\n", err)
		os.Exit(1)
	}
}

func run(ctx context.Context, args []string, out io.Writer, errOut io.Writer) error {
	fs := flag.NewFlagSet("client", flag.ContinueOnError)
	fs.SetOutput(errOut)
	listTools := fs.Bool("list-tools", false, "List available tools")
	callTool := fs.String("call-tool", "", "Call a tool by name")
	serverPath := fs.String("server-path", "./bin/server", "Path to the server binary")

	if err := fs.Parse(args); err != nil {
		return err
	}

	if !*listTools && *callTool == "" {
		fs.Usage()
		return fmt.Errorf("either --list-tools or --call-tool must be provided")
	}

	c := NewClient("hello-world-client", "1.0.0")

	if err := c.Connect(ctx, *serverPath); err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer c.Close()

	if *listTools {
		tools, err := c.ListTools(ctx)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, name := range tools {
			fmt.Fprintln(out, name)
		}
	}

	if *callTool != "" {
		if *callTool == "hello_world" {
			text, err := c.CallHelloWorld(ctx)
			if err != nil {
				return fmt.Errorf("failed to call tool: %w", err)
			}
			fmt.Fprintln(out, text)
		} else {
			return fmt.Errorf("unknown tool: %s", *callTool)
		}
	}
	return nil
