{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type ClientApp struct {
	ServerPath string
	Implementation *mcp.Implementation
}

func NewClientApp(serverPath string) *ClientApp {
	return &ClientApp{
		ServerPath: serverPath,
		Implementation: &mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		},
	}
}

func (app *ClientApp) ListTools(ctx context.Context) ([]string, error) {
	client := mcp.NewClient(app.Implementation, nil)
	transport := &mcp.CommandTransport{
		Command: exec.Command(app.ServerPath),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}
	defer session.Close()

	result, err := session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}

	var names []string
	for _, tool := range result.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

func (app *ClientApp) CallTool(ctx context.Context, toolName string) ([]string, error) {
	client := mcp.NewClient(app.Implementation, nil)
	transport := &mcp.CommandTransport{
		Command: exec.Command(app.ServerPath),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}
	defer session.Close()

	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: toolName,
	})
	if err != nil {
		return nil, err
	}

	var contents []string
	for _, content := range result.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			contents = append(contents, text.Text)
		}
	}
	return contents, nil
}
