{"content":"package client

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-server-client/pkg/hello"
)

func TestClientApp(t *testing.T) {
	ctx := context.Background()
	t1, t2 := mcp.NewInMemoryTransports()

	server := mcp.NewServer(&mcp.Implementation{Name: "test-server", Version: "1.0.0"}, nil)
	mcp.AddTool(server, &mcp.Tool{Name: "hello_world"}, hello.HelloWorldHandler)

	go func() {
		if _, err := server.Connect(ctx, t1, nil); err != nil {
			panic(err)
		}
	}()

	app := NewClientApp("")

	// Test ListTools
	names, err := app.ListTools(ctx, t2)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}
	found := false
	for _, name := range names {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("hello_world tool not found")
	}

	// Re-create transports for next call because Connect might consume them or session might be closed
	t1, t2 = mcp.NewInMemoryTransports()
	go func() {
		if _, err := server.Connect(ctx, t1, nil); err != nil {
			panic(err)
		}
	}()

	// Test CallTool
	contents, err := app.CallTool(ctx, t2, "hello_world")
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}
	if len(contents) == 0 || contents[0] != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got %v", contents)
	}
}
