{"content":"package main

import (
	"context"
	"flag"
	"log"
	"os"

	"mcp-example/internal/clientapp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	ctx := context.Background()
	app := clientapp.NewClientApp("./bin/server")

	if *listTools || *callTool != "" {
		err := app.Run(ctx, *listTools, *callTool, os.Stdout)
		if err != nil {
			log.Fatal(err)
		}
	} else {
		flag.Usage()
	}
}
