func TestRunServer(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 1*time.Second)
	defer cancel()

	t1, _ := mcp.NewInMemoryTransports()

	// RunServer will block until ctx is done or transport is closed.
	// Since we are using InMemoryTransport, we can just let it run and then cancel ctx.
	errChan := make(chan error, 1)
	go func() {
		errChan <- RunServer(ctx, t1)
	}()

	cancel()
	err := <-errChan
	if err != nil && err != context.Canceled {
		t.Fatalf("RunServer failed: %v", err)
	}
}
