{"content":"package clientapp

import (
	"context"
	"fmt"
	"io"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type ClientApp struct {
	Client     *mcp.Client
	ServerPath string
}

func NewClientApp(serverPath string) *ClientApp {
	return &ClientApp{
		Client: mcp.NewClient(
			&mcp.Implementation{
				Name:    "hello-client",
				Version: "1.0.0",
			},
			nil,
		),
		ServerPath: serverPath,
	}
}

func (a *ClientApp) RunWithTransport(ctx context.Context, transport mcp.Transport, list bool, call string, stdout io.Writer) error {
	session, err := a.Client.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	defer session.Close()

	if list {
		for tool, err := range session.Tools(ctx, nil) {
			if err != nil {
				return err
			}
			fmt.Fprintln(stdout, tool.Name)
		}
	}

	if call != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: call,
		})
		if err != nil {
			return err
		}
		for _, content := range res.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Fprintln(stdout, text.Text)
			}
		}
	}
	return nil
}

func (a *ClientApp) Run(ctx context.Context, list bool, call string, stdout io.Writer) error {
	cmd := exec.CommandContext(ctx, a.ServerPath)
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return err
	}
	serverStdout, err := cmd.StdoutPipe()
	if err != nil {
		return err
	}
	serverStderr, err := cmd.StderrPipe()
	if err != nil {
		return err
	}
	go func() {
		_, _ = io.Copy(os.Stderr, serverStderr)
	}()

	if err := cmd.Start(); err != nil {
		return err
	}
	defer cmd.Process.Kill()

	transport := &mcp.IOTransport{
		Reader: serverStdout,
		Writer: stdin,
	}

	return a.RunWithTransport(ctx, transport, list, call, stdout)
}
