func TestClientApp_RunWithTransport(t *testing.T) {
	ctx := context.Background()
	server := serverapp.NewHelloServer()

	clientTransport, serverTransport := mcp.NewInMemoryTransports()

	// Start server in a goroutine
	go func() {
		_, _ = server.Connect(ctx, serverTransport, nil)
	}()

	app := NewClientApp("")
	var buf bytes.Buffer

	// Test list tools
	err := app.RunWithTransport(ctx, clientTransport, true, "", &buf)
	if err != nil {
		t.Fatalf("RunWithTransport failed: %v", err)
	}

	if !bytes.Contains(buf.Bytes(), []byte("hello_world")) {
		t.Errorf("Expected output to contain hello_world, got %q", buf.String())
	}

	// Test call tool
	// We need a new connection because session.Close() was called in RunWithTransport
	clientTransport2, serverTransport2 := mcp.NewInMemoryTransports()
	go func() {
		_, _ = server.Connect(ctx, serverTransport2, nil)
	}()

	buf.Reset()
	err = app.RunWithTransport(ctx, clientTransport2, false, "hello_world", &buf)
	if err != nil {
		t.Fatalf("RunWithTransport failed: %v", err)
	}

	if !bytes.Contains(buf.Bytes(), []byte("Hello, MCP World!")) {
		t.Errorf("Expected output to contain Hello, MCP World!, got %q", buf.String())
	}
}
