// HelloWorldHandler is the handler for the hello_world tool.
func HelloWorldHandler(ctx context.Context, req *mcp.CallToolRequest, _ any) (*mcp.CallToolResult, any, error) {
	return &mcp.CallToolResult{
		Content: []mcp.Content{
			&mcp.TextContent{Text: "Hello, MCP World!"},
		},
	}, nil, nil
}

// NewHelloWorldServer creates a new MCP server with the hello_world tool.
func NewHelloWorldServer() *mcp.Server {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "hello-server",
		Version: "1.0.0",
	}, nil)

	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns 'Hello, MCP World!'",
	}, HelloWorldHandler)

	return server
}
