{"content":"package mcp

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// HelloWorldClient wraps the MCP client.
type HelloWorldClient struct {
	client  *mcp.Client
	session *mcp.ClientSession
}

// NewHelloWorldClient creates and connects a new MCP client.
func NewHelloWorldClient(serverPath string) (*HelloWorldClient, error) {
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	transport := &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}

	ctx := context.Background()
	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return nil, err
	}

	return &HelloWorldClient{
		client:  client,
		session: session,
	}, nil
}

// Close closes the client session.
func (c *HelloWorldClient) Close() error {
	return c.session.Close()
}

// ListTools lists all available tools.
func (c *HelloWorldClient) ListTools(ctx context.Context) ([]string, error) {
	tools, err := c.session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}

	var names []string
	for _, tool := range tools.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

// CallTool calls a tool by name and returns the text results.
func (c *HelloWorldClient) CallTool(ctx context.Context, name string) ([]string, error) {
	result, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return nil, err
	}

	var results []string
	for _, content := range result.Content {
		if tc, ok := content.(*mcp.TextContent); ok {
			results = append(results, tc.Text)
		} else {
			// Some content might be marshaled to map[string]any if not properly typed
			// but with the SDK we expect *mcp.TextContent
			results = append(results, fmt.Sprintf("%v", content))
		}
	}
	return results, nil
}
