{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"

	mcp_pkg "mcp-example/pkg/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List all available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	// Assume bin/server is already built or use the path
	client, err := mcp_pkg.NewHelloWorldClient("./bin/server")
	if err != nil {
		log.Fatalf("Failed to create client: %v", err)
	}
	defer client.Close()

	ctx := context.Background()

	if *listTools {
		names, err := client.ListTools(ctx)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, name := range names {
			fmt.Println(name)
		}
	}

	if *callTool != "" {
		results, err := client.CallTool(ctx, *callTool)
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		for _, res := range results {
			fmt.Println(res)
		}
	}
}
