{"content":"package mcp

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldHandler(t *testing.T) {
	ctx := context.Background()
	req := &mcp.CallToolRequest{}

	result, _, err := HelloWorldHandler(ctx, req, nil)
	if err != nil {
		t.Fatalf("HelloWorldHandler failed: %v", err)
	}

	if len(result.Content) != 1 {
		t.Fatalf("Expected 1 content item, got %d", len(result.Content))
	}

	tc, ok := result.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", result.Content[0])
	}

	expected := "Hello, MCP World!"
	if tc.Text != expected {
		t.Errorf("Expected %q, got %q", expected, tc.Text)
	}
}

func TestNewHelloWorldServer(t *testing.T) {
	server := NewHelloWorldServer()
	if server == nil {
		t.Fatal("NewHelloWorldServer returned nil")
	}
}
