func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()

	// Connect to the server using CommandTransport
	transport := &mcp.CommandTransport{
		Command: exec.Command("./bin/server"),
	}

	c := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "1.0.0",
		},
		nil,
	)

	session, err := c.Connect(ctx, transport, nil)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to connect to server: %v\n", err)
		os.Exit(1)
	}
	defer session.Close()

	if *listTools {
		names, err := client.ListTools(ctx, session)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Failed to list tools: %v\n", err)
			os.Exit(1)
		}
		for _, name := range names {
			fmt.Println(name)
		}
	}

	if *callTool != "" {
		text, err := client.CallTool(ctx, session, *callTool)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Failed to call tool: %v\n", err)
			os.Exit(1)
		}
		fmt.Println(text)
	}
}
