func TestClientServer(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	sTransport, cTransport := mcp.NewInMemoryTransports()

	s := server.CreateServer()
	go func() {
		_ = s.Run(ctx, sTransport)
	}()

	c := mcp.NewClient(
		&mcp.Implementation{
			Name:    "test-client",
			Version: "1.0.0",
		},
		nil,
	)

	session, err := c.Connect(ctx, cTransport, nil)
	if err != nil {
		t.Fatalf("failed to connect: %v", err)
	}
	defer session.Close()

	// Test ListTools
	names, err := ListTools(ctx, session)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}
	found := false
	for _, name := range names {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("hello_world tool not found in list")
	}

	// Test CallTool
	text, err := CallTool(ctx, session, "hello_world")
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}
	if text != "Hello, MCP World!" {
		t.Errorf("expected 'Hello, MCP World!', got '%s'", text)
	}
}
