{"content":"package mcp

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// HelloWorldClient wraps the MCP client.
type HelloWorldClient struct {
	client  *mcp.Client
	session *mcp.ClientSession
}

// NewHelloWorldClient creates a new HelloWorldClient instance.
func NewHelloWorldClient() *HelloWorldClient {
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	return &HelloWorldClient{
		client: client,
	}
}

// Connect connects the client to a server using the given transport.
func (c *HelloWorldClient) Connect(ctx context.Context, transport mcp.Transport) error {
	session, err := c.client.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	c.session = session
	return nil
}

// ConnectCommand connects using a command (e.g. ./bin/server).
func (c *HelloWorldClient) ConnectCommand(ctx context.Context, serverPath string) error {
	transport := &mcp.CommandTransport{
		Command: exec.Command(serverPath),
	}
	return c.Connect(ctx, transport)
}

// Close closes the client session.
func (c *HelloWorldClient) Close() error {
	if c.session == nil {
		return nil
	}
	return c.session.Close()
}

// ListTools lists all available tools.
func (c *HelloWorldClient) ListTools(ctx context.Context) ([]string, error) {
	if c.session == nil {
		return nil, fmt.Errorf("not connected")
	}
	tools, err := c.session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}

	var names []string
	for _, tool := range tools.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

// CallTool calls a tool by name and returns the text results.
func (c *HelloWorldClient) CallTool(ctx context.Context, name string) ([]string, error) {
	if c.session == nil {
		return nil, fmt.Errorf("not connected")
	}
	result, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return nil, err
	}

	var results []string
	for _, content := range result.Content {
		if tc, ok := content.(*mcp.TextContent); ok {
			results = append(results, tc.Text)
		} else {
			results = append(results, fmt.Sprintf("%v", content))
		}
	}
	return results, nil
}
