{"content":"package mcp

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestIntegration(t *testing.T) {
	ctx := context.Background()
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	server := NewHelloWorldServer()
	go func() {
		if _, err := server.Connect(ctx, serverTransport, nil); err != nil {
			// t.Errorf might be called from another goroutine, but it's okay in recent Go
		}
	}()

	client := NewHelloWorldClient()
	if err := client.Connect(ctx, clientTransport); err != nil {
		t.Fatalf("Failed to connect client: %v", err)
	}
	defer client.Close()

	// Test ListTools
	names, err := client.ListTools(ctx)
	if err != nil {
		t.Fatalf("Failed to list tools: %v", err)
	}

	found := false
	for _, name := range names {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("hello_world tool not found in list")
	}

	// Test CallTool
	results, err := client.CallTool(ctx, "hello_world")
	if err != nil {
		t.Fatalf("Failed to call tool: %v", err)
	}

	if len(results) != 1 {
		t.Fatalf("Expected 1 result item, got %d", len(results))
	}

	if results[0] != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got %q", results[0])
	}

	// Test error cases
	_, err = client.CallTool(ctx, "non_existent")
	if err == nil {
		t.Error("Expected error for non-existent tool, got nil")
	}
}

func TestClientErrors(t *testing.T) {
	client := NewHelloWorldClient()
	ctx := context.Background()

	_, err := client.ListTools(ctx)
	if err == nil {
		t.Error("Expected error for non-connected client in ListTools")
	}

	_, err = client.CallTool(ctx, "any")
	if err == nil {
		t.Error("Expected error for non-connected client in CallTool")
	}

	err = client.Close()
	if err != nil {
		t.Errorf("Close should not fail for non-connected client, got %v", err)
	}
}
