{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func RunCLI(serverCmd string, listTools bool, callTool string) error {
	ctx := context.Background()

	// Connect to the server using CommandTransport
	transport := &mcp.CommandTransport{
		Command: exec.Command(serverCmd),
	}

	c := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "1.0.0",
		},
		nil,
	)

	session, err := c.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if listTools {
		names, err := ListTools(ctx, session)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, name := range names {
			fmt.Println(name)
		}
	}

	if callTool != "" {
		text, err := CallTool(ctx, session, callTool)
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		fmt.Println(text)
	}
	return nil
}
