{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
}

func NewClient() *Client {
	return &Client{
		mcpClient: mcp.NewClient(&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		}, nil),
	}
}

func (c *Client) ListTools(ctx context.Context, serverPath string) ([]string, error) {
	session, err := c.connect(ctx, serverPath)
	if err != nil {
		return nil, err
	}
	defer session.Close()

	tools, err := session.ListTools(ctx, &mcp.ListToolsParams{})
	if err != nil {
		return nil, err
	}

	var names []string
	for _, tool := range tools.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

func (c *Client) CallTool(ctx context.Context, serverPath string, toolName string) ([]string, error) {
	session, err := c.connect(ctx, serverPath)
	if err != nil {
		return nil, err
	}
	defer session.Close()

	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: toolName,
	})
	if err != nil {
		return nil, err
	}

	var messages []string
	for _, content := range result.Content {
		if textPtr, ok := content.(*mcp.TextContent); ok {
			messages = append(messages, textPtr.Text)
		}
	}
	return messages, nil
}

func (c *Client) connect(ctx context.Context, serverPath string) (*mcp.ClientSession, error) {
	var cmd *exec.Cmd
	if serverPath == "./bin/server" {
		cmd = exec.Command(serverPath)
	} else {
		cmd = exec.Command("go", "run", "./cmd/server/main.go")
	}

	transport := &mcp.CommandTransport{
		Command: cmd,
	}

	return c.mcpClient.Connect(ctx, transport, nil)
}

func (c *Client) RunWithSession(ctx context.Context, transport mcp.Transport, f func(*mcp.ClientSession) error) error {
	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	defer session.Close()
	return f(session)
}
","filename":"internal/client/client.go"}

{"content":"package client

import (
	"context"
	"fmt"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
	session   *mcp.ClientSession
}

func NewClient() *Client {
	mcpClient := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)
	return &Client{mcpClient: mcpClient}
}

func (c *Client) Connect(ctx context.Context, transport mcp.Transport) error {
	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	c.session = session
	return nil
}

func (c *Client) Close() error {
	if c.session != nil {
		return c.session.Close()
	}
	return nil
}

func (c *Client) ListTools(ctx context.Context) error {
	tools := c.session.Tools(ctx, nil)
	fmt.Println("tools:")
	for t, err := range tools {
		if err != nil {
			return err
		}
		fmt.Printf("\t%s\n", t.Name)
	}
	return nil
}

func (c *Client) CallTool(ctx context.Context, name string) error {
	result, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return err
	}

	for _, content := range result.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			fmt.Println(text.Text)
		}
	}
	return nil
}
","file_path":"internal/client/client.go"}

