{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-hello-world/internal/client"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		fmt.Println("Please specify --list-tools or --call-tool <name>")
		os.Exit(1)
	}

	ctx := context.Background()
	cmd := exec.Command("./bin/server")
	transport := &mcp.CommandTransport{Command: cmd}

	c := client.NewClient()
	if err := c.Connect(ctx, transport); err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer c.Close()

	if *listTools {
		if err := c.ListTools(ctx); err != nil {
