func TestClient(t *testing.T) {
	s := server.NewHelloServer()
	clientTransport, serverTransport := mcp.NewInMemoryTransports()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		if err := s.Run(ctx, serverTransport); err != nil && err != context.Canceled {
			t.Errorf("Server run failed: %v", err)
		}
	}()

	c := NewClient()

	err := c.RunWithSession(ctx, clientTransport, func(session *mcp.ClientSession) error {
		// Test ListTools
		tools, err := session.ListTools(ctx, &mcp.ListToolsParams{})
		if err != nil {
			return err
		}

		found := false
		for _, tool := range tools.Tools {
			if tool.Name == "hello_world" {
				found = true
				break
			}
		}
		if !found {
			t.Error("hello_world tool not found")
		}

		// Test CallTool
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: "hello_world",
		})
		if err != nil {
			return err
		}

		if len(result.Content) == 0 {
			t.Fatal("Expected content in result")
		}

		textPtr, ok := result.Content[0].(*mcp.TextContent)
		if !ok {
			t.Fatalf("Expected *mcp.TextContent, got %T", result.Content[0])
		}

		expected := "Hello, MCP World!"
		if textPtr.Text != expected {
			t.Errorf("Expected %q, got %q", expected, textPtr.Text)
		}
		return nil
	})

	if err != nil {
		t.Fatalf("RunWithSession failed: %v", err)
	}
}
