	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloServer(t *testing.T) {
	s := NewHelloServer()
	ct, st := mcp.NewInMemoryTransports()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		if err := s.Run(ctx, st); err != nil && err != context.Canceled {
			t.Errorf("Server run failed: %v", err)
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)
	cs, err := client.Connect(ctx, ct, nil)
	if err != nil {
		t.Fatalf("Client connect failed: %v", err)
	}
	defer cs.Close()

	tools := cs.Tools(ctx, nil)
	found := false
	for tool, err := range tools {
		if err != nil {
			t.Fatalf("Error listing tools: %v", err)
		}
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}

	if !found {
		t.Error("hello_world tool not found")
	}

	result, err := cs.CallTool(ctx, &mcp.CallToolParams{Name: "hello_world"})
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}

	if len(result.Content) != 1 {
		t.Fatalf("Expected 1 content, got %d", len(result.Content))
	}

	textContent, ok := result.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", result.Content[0])
	}

	if textContent.Text != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got %q", textContent.Text)
	}
}
