func TestClient(t *testing.T) {
	ct, st := mcp.NewInMemoryTransports()

	// Setup a simple server
	server := mcp.NewServer(&mcp.Implementation{Name: "test-server"}, nil)
	mcp.AddTool(server, &mcp.Tool{Name: "test_tool"}, func(ctx context.Context, req *mcp.CallToolRequest, args struct{}) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{&mcp.TextContent{Text: "test-response"}},
		}, nil, nil
	})

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go func() {
		if err := server.Run(ctx, st); err != nil && err != context.Canceled {
			t.Errorf("Server failed: %v", err)
		}
	}()

	c := NewClient()
	if err := c.Connect(ctx, ct); err != nil {
		t.Fatalf("Connect failed: %v", err)
	}
	defer c.Close()

	// We can't easily capture stdout from the client methods without redirecting os.Stdout,
	// but we can at least verify they don't return errors.
	if err := c.ListTools(ctx); err != nil {
		t.Errorf("ListTools failed: %v", err)
	}

	if err := c.CallTool(ctx, "test_tool"); err != nil {
		t.Errorf("CallTool failed: %v", err)
	}
}
