{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	// In a real world scenario, the server path might be configurable.
	// For this task, we assume ./bin/server exists.
	serverPath := "./bin/server"
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		// Fallback for development/testing if bin/server doesn't exist yet
		serverPath = "go run ./cmd/server/main.go"
		// Actually, let's just use the bin/server as required by the task.
		// If we are running tests or building, we should ensure it's there.
	}

	transport := &mcp.CommandTransport{
		Command: exec.Command("./bin/server"),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
