{"content":"package hello

import (
	"context"
	"fmt"
	"io"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// RunClient runs the client logic.
func RunClient(ctx context.Context, client *mcp.Client, transport mcp.Transport, listTools bool, callTool string, out io.Writer) error {
	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer session.Close()

	if listTools {
		result, err := session.ListTools(ctx, nil)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, tool := range result.Tools {
			fmt.Fprintln(out, tool.Name)
		}
	}

	if callTool != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}

		if result.IsError {
			return fmt.Errorf("tool error: %v", result.Content)
		}

		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Fprint(out, text.Text)
			}
		}
		fmt.Fprintln(out)
	}
	return nil
}

// NewHelloClient creates a new MCP client.
func NewHelloClient() *mcp.Client {
	return mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-world-client",
			Version: "0.1.0",
		},
		nil,
	)
}
