{"content":"package client

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
	session   *mcp.ClientSession
}

func NewClient() *Client {
	mcpClient := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)
	return &Client{mcpClient: mcpClient}
}

func (c *Client) Connect(ctx context.Context, transport mcp.Transport) error {
	session, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	c.session = session
	return nil
}

func (c *Client) Close() error {
	if c.session != nil {
		return c.session.Close()
	}
	return nil
}

func (c *Client) ListTools(ctx context.Context) error {
	tools := c.session.Tools(ctx, nil)
	fmt.Println("tools:")
	for t, err := range tools {
		if err != nil {
			return err
		}
		fmt.Printf("\t%s\n", t.Name)
	}
	return nil
}

func (c *Client) CallTool(ctx context.Context, name string) error {
	result, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return err
	}

	for _, content := range result.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			fmt.Println(text.Text)
		}
	}
	return nil
}

func Main(args []string) {
	fs := flag.NewFlagSet("client", flag.ExitOnError)
	listTools := fs.Bool("list-tools", false, "List available tools")
	callTool := fs.String("call-tool", "", "Call a tool by name")
	serverPath := fs.String("server", "./bin/server", "Path to server binary")
	fs.Parse(args)

	if !*listTools && *callTool == "" {
		fmt.Println("Please specify --list-tools or --call-tool <name>")
		os.Exit(1)
	}

	ctx := context.Background()
	cmd := exec.Command(*serverPath)
	transport := &mcp.CommandTransport{Command: cmd}

	c := NewClient()
	if err := c.Connect(ctx, transport); err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer c.Close()

	if *listTools {
		if err := c.ListTools(ctx); err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
	}

	if *callTool != "" {
		if err := c.CallTool(ctx, *callTool); err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
	}
}
