func TestNewHelloServer(t *testing.T) {
	s := NewHelloServer()
	if s == nil {
		t.Fatal("expected server to be non-nil")
	}

	// We can't easily inspect tools on the server struct because they are private.
	// But we can try to connect to it using in-memory transport.
	ctx := context.Background()
	t1, t2 := mcp.NewInMemoryTransports()

	_, err := s.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatalf("failed to connect to server: %v", err)
	}

	client := mcp.NewClient(&mcp.Implementation{Name: "test-client"}, nil)
	session, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("failed to connect client: %v", err)
	}
	defer session.Close()

	tools, err := session.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("failed to list tools: %v", err)
	}

	found := false
	for _, tool := range tools.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}

	if !found {
		t.Error("hello_world tool not found in server")
	}
}
