	"log"
)

func RunCLI(args []string) {
	fs := flag.NewFlagSet("client", flag.ExitOnError)
	listTools := fs.Bool("list-tools", false, "List available tools")
	callTool := fs.String("call-tool", "", "Call a tool by name")
	err := fs.Parse(args)
	if err != nil {
		log.Fatalf("Failed to parse flags: %v", err)
	}

	if !*listTools && *callTool == "" {
		fmt.Println("Usage of client:")
		fs.PrintDefaults()
		return
	}

	ctx := context.Background()
	session, err := ConnectToServer(ctx, "./bin/server")
	if err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	if *listTools {
		if err := ListTools(ctx, session); err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
	}

	if *callTool != "" {
		if *callTool == "hello_world" {
			if err := CallHelloWorld(ctx, session); err != nil {
				log.Fatalf("Failed to call tool: %v", err)
			}
		} else {
			log.Fatalf("Unknown tool: %s", *callTool)
		}
	}
}
