{"content":"package client

import (
	"context"
	"flag"
	"fmt"
	"io"
	"log"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func RunCLI(ctx context.Context, session *mcp.ClientSession, args []string, out io.Writer) error {
	fs := flag.NewFlagSet("client", flag.ContinueOnError)
	fs.SetOutput(out)
	listTools := fs.Bool("list-tools", false, "List available tools")
	callTool := fs.String("call-tool", "", "Call a tool by name")
	err := fs.Parse(args)
	if err != nil {
		return err
	}

	if !*listTools && *callTool == "" {
		fmt.Fprintln(out, "Usage of client:")
		fs.PrintDefaults()
		return nil
	}

	if *listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			return err
		}
		for _, tool := range tools.Tools {
			fmt.Fprintln(out, tool.Name)
		}
	}

	if *callTool != "" {
		if *callTool == "hello_world" {
			result, err := session.CallTool(ctx, &mcp.CallToolParams{
				Name: "hello_world",
			})
			if err != nil {
				return err
			}
			for _, content := range result.Content {
				if textContent, ok := content.(*mcp.TextContent); ok {
					fmt.Fprintln(out, textContent.Text)
				}
			}
		} else {
			return fmt.Errorf("unknown tool: %s", *callTool)
		}
	}
	return nil
}
