{"content":"package client

import (
	"bytes"
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-server-client/pkg/server"
)

func TestClientFunctions(t *testing.T) {
	ctx := context.Background()
	t1, t2 := mcp.NewInMemoryTransports()

	s := server.NewHelloServer()
	_, err := s.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatalf("failed to connect to server: %v", err)
	}

	session, err := ConnectWithTransport(ctx, t2)
	if err != nil {
		t.Fatalf("failed to connect client: %v", err)
	}
	defer session.Close()

	// Test ListTools
	err = ListTools(ctx, session)
	if err != nil {
		t.Errorf("ListTools failed: %v", err)
	}

	// Test CallHelloWorld
	err = CallHelloWorld(ctx, session)
	if err != nil {
		t.Errorf("CallHelloWorld failed: %v", err)
	}

	// Test RunCLI
	t.Run("RunCLI list-tools", func(t *testing.T) {
		var out bytes.Buffer
		err := RunCLI(ctx, session, []string{"--list-tools"}, &out)
		if err != nil {
			t.Errorf("RunCLI failed: %v", err)
		}
		if !bytes.Contains(out.Bytes(), []byte("hello_world")) {
			t.Errorf("expected output to contain 'hello_world', got %q", out.String())
		}
	})

	t.Run("RunCLI call-tool", func(t *testing.T) {
		var out bytes.Buffer
		err := RunCLI(ctx, session, []string{"--call-tool", "hello_world"}, &out)
		if err != nil {
			t.Errorf("RunCLI failed: %v", err)
		}
		if !bytes.Contains(out.Bytes(), []byte("Hello, MCP World!")) {
			t.Errorf("expected output to contain 'Hello, MCP World!', got %q", out.String())
		}
	})
}
