{"content":"package hello

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestNewHelloClient(t *testing.T) {
	client := NewHelloClient()
	if client == nil {
		t.Fatal("expected non-nil client")
	}
}

func TestNewHelloServer(t *testing.T) {
	server := NewHelloServer()
	if server == nil {
		t.Fatal("expected non-nil server")
	}
}

type errorTransport struct{}

func (t *errorTransport) Connect(ctx context.Context) (mcp.Connection, error) {
	return nil, fmt.Errorf("forced connection error")
}

func TestRunClient_ConnectError(t *testing.T) {
	client := NewHelloClient()
	err := RunClient(context.Background(), client, &errorTransport{}, false, "", nil)
	if err == nil {
		t.Fatal("expected error, got nil")
	}
}

func TestRunClient_Integration(t *testing.T) {
	// Find the server binary
	wd, _ := os.Getwd()
	serverPath := filepath.Join(wd, "../../bin/server")
	if _, err := os.Stat(serverPath); err != nil {
		t.Skip("server binary not found at", serverPath)
	}

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	client := NewHelloClient()

	t.Run("ListAndCall", func(t *testing.T) {
		cmd := exec.Command(serverPath)
		transport := &mcp.CommandTransport{Command: cmd}
		var out bytes.Buffer
		err := RunClient(ctx, client, transport, true, "hello_world", &out)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
		output := out.String()
		if !strings.Contains(output, "hello_world") {
			t.Errorf("expected output to contain hello_world, got %q", output)
		}
		if !strings.Contains(output, "Hello, MCP World!") {
			t.Errorf("expected output to contain Hello, MCP World!, got %q", output)
		}
	})

	t.Run("CallOnly", func(t *testing.T) {
		cmd := exec.Command(serverPath)
		transport := &mcp.CommandTransport{Command: cmd}
		var out bytes.Buffer
		err := RunClient(ctx, client, transport, false, "hello_world", &out)
		if err != nil {
			t.Fatalf("RunClient failed: %v", err)
		}
		if !strings.Contains(out.String(), "Hello, MCP World!") {
			t.Errorf("expected output to contain Hello, MCP World!, got %q", out.String())
		}
	})

	t.Run("NonExistentTool", func(t *testing.T) {
		cmd := exec.Command(serverPath)
		transport := &mcp.CommandTransport{Command: cmd}
		var out bytes.Buffer
		err := RunClient(ctx, client, transport, false, "non_existent", &out)
		if err == nil {
			t.Fatal("expected error calling non-existent tool, got nil")
		}
	})
}
