import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestClient(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Setup a dummy server
	server := mcp.NewServer(&mcp.Implementation{Name: "test-server"}, nil)
	mcp.AddTool(server, &mcp.Tool{Name: "hello_world"}, func(ctx context.Context, req *mcp.CallToolRequest, args any) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{&mcp.TextContent{Text: "Hello, MCP World!"}},
		}, nil, nil
	})

	c := NewClient()

	// Test ListTools
	t1, t2 := mcp.NewInMemoryTransports()
	serverSession, err := server.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatalf("Failed to connect server: %v", err)
	}
	err = c.Run(ctx, t2, true, "")
	if err != nil {
		t.Errorf("Run (listTools) failed: %v", err)
	}
	serverSession.Close()

	// Test CallTool
	t1, t2 = mcp.NewInMemoryTransports()
	serverSession, err = server.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatalf("Failed to connect server: %v", err)
	}
	err = c.Run(ctx, t2, false, "hello_world")
	if err != nil {
		t.Errorf("Run (callTool) failed: %v", err)
	}
	serverSession.Close()
}
