	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/user/mcp-hello-world/internal/server"
)

func TestClientServerInteraction(t *testing.T) {
	ctx := context.Background()
	clientTransport, serverTransport := mcp.NewInMemoryTransports()

	s := server.NewHelloWorldServer()
	go func() {
		if err := s.Run(ctx, serverTransport); err != nil {
			// t.Errorf might be called from another goroutine, which is fine in Go 1.14+
			// but we can't FailNow.
		}
	}()

	c := NewClient("test-client")
	if err := c.Connect(ctx, clientTransport); err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer c.Close()

	t.Run("ListTools", func(t *testing.T) {
		tools, err := c.ListTools(ctx)
		if err != nil {
			t.Fatalf("Failed to list tools: %v", err)
		}
		found := false
		for _, name := range tools {
			if name == "hello_world" {
				found = true
				break
			}
		}
		if !found {
			t.Error("hello_world tool not found")
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		text, err := c.CallTool(ctx, "hello_world")
		if err != nil {
			t.Fatalf("Failed to call tool: %v", err)
		}
		if text != "Hello, MCP World!" {
			t.Errorf("expected 'Hello, MCP World!', got '%s'", text)
		}
	})
}
