{"content":"package client

import (
	"context"
	"fmt"
	"io"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func Run(ctx context.Context, listTools bool, callTool string, stdout io.Writer) error {
	c := NewClient("hello-world-client")

	transport := &mcp.CommandTransport{
		Command: exec.CommandContext(ctx, "./bin/server"),
	}

	if err := c.Connect(ctx, transport); err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer c.Close()

	if listTools {
		tools, err := c.ListTools(ctx)
		if err != nil {
			return fmt.Errorf("failed to list tools: %w", err)
		}
		for _, name := range tools {
			fmt.Fprintln(stdout, name)
		}
	}

	if callTool != "" {
		text, err := c.CallTool(ctx, callTool)
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		fmt.Fprintln(stdout, text)
	}

	return nil
}
