{"content":"package server

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldTool(t *testing.T) {
	ctx := context.Background()
	s := NewHelloWorldServer()

	clientTransport, serverTransport := mcp.NewInMemoryTransports()

	go func() {
		if err := s.Run(ctx, serverTransport); err != nil {
			// This might happen on shutdown, ignore
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "test-client",
		Version: "1.0.0",
	}, nil)

	cs, err := client.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer cs.Close()

	// Test ListTools
	found := false
	for tool, err := range cs.Tools(ctx, nil) {
		if err != nil {
			t.Fatalf("Error listing tools: %v", err)
		}
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("Tool 'hello_world' not found")
	}

	// Test CallTool
	result, err := cs.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("Failed to call tool: %v", err)
	}

	if len(result.Content) != 1 {
		t.Fatalf("Expected 1 content item, got %d", len(result.Content))
	}

	textContent, ok := result.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", result.Content[0])
	}

	expected := "Hello, MCP World!"
	if textContent.Text != expected {
		t.Errorf("Expected %q, got %q", expected, textContent.Text)
	}
}
