{"content":"package main

import (
	"testing"
)

func TestNewHelloServer(t *testing.T) {
	server := NewHelloServer()
	if server == nil {
		t.Fatal("Expected server to be non-nil")
	}
	// We could potentially check if the tool is registered, but the mcp.Server doesn't expose tools easily.
