{"content":"package client

import (
	"context"
	"fmt"
	"io"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func RunClient(ctx context.Context, transport mcp.Transport, listTools bool, callTool string, stdout io.Writer) error {
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-world-client",
		Version: "1.0.0",
	}, nil)

	cs, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer cs.Close()

	if listTools {
		fmt.Fprintln(stdout, "tools:")
		for t, err := range cs.Tools(ctx, nil) {
			if err != nil {
				return fmt.Errorf("error iterating tools: %w", err)
			}
			fmt.Fprintf(stdout, "\t%s\n", t.Name)
		}
	}

	if callTool != "" {
		result, err := cs.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}
		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Fprintln(stdout, text.Text)
			}
		}
	}

	return nil
}
