	"os/exec"
	"path/filepath"
	"testing"
)

func TestRun(t *testing.T) {
	// Build the server binary first to ensure it's available for the test
	tempDir, err := os.MkdirTemp("", "mcp-test")
	if err != nil {
		t.Fatal(err)
	}
	defer os.RemoveAll(tempDir)

	serverBin := filepath.Join(tempDir, "server")
	buildCmd := exec.Command("go", "build", "-o", serverBin, "main.go")
	// Need to run from the server directory
	buildCmd.Dir = "../server"
	if out, err := buildCmd.CombinedOutput(); err != nil {
		t.Fatalf("Failed to build server: %v\nOutput: %s", err, string(out))
	}

	ctx := context.Background()

	t.Run("list-tools", func(t *testing.T) {
		err := run(ctx, true, "", serverBin)
		if err != nil {
			t.Errorf("Expected no error, got %v", err)
		}
	})

	t.Run("call-tool", func(t *testing.T) {
		err := run(ctx, false, "hello_world", serverBin)
		if err != nil {
			t.Errorf("Expected no error, got %v", err)
		}
	})
}
