import (
	"context"
	"fmt"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func ListTools(ctx context.Context, session *mcp.ClientSession) error {
	tools := session.Tools(ctx, nil)
	fmt.Println("tools:")
	for tool, err := range tools {
		if err != nil {
			return err
		}
		fmt.Printf("\t%s\n", tool.Name)
	}
	return nil
}

func CallTool(ctx context.Context, session *mcp.ClientSession, toolName string) error {
	result, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: toolName,
	})
	if err != nil {
		return err
	}

	for _, content := range result.Content {
		if text, ok := content.(*mcp.TextContent); ok {
			fmt.Println(text.Text)
		}
	}
	return nil
}
