{"content":"package client

import (
	"context"
	"io"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-hello-world/internal/hello"
)

func TestClient(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Create a pipe for client-server communication
	clientReader, serverWriter := io.Pipe()
	serverReader, clientWriter := io.Pipe()

	serverTransport := &mcp.StdioTransport{
		Reader: serverReader,
		Writer: serverWriter,
	}
	clientTransport := &mcp.StdioTransport{
		Reader: clientReader,
		Writer: clientWriter,
	}

	server := hello.NewServer()
	go func() {
		if err := server.Run(ctx, serverTransport); err != nil {
			// server closed
		}
	}()

	mcpClient := mcp.NewClient(&mcp.Implementation{
		Name:    "test-client",
		Version: "1.0.0",
	}, nil)

	session, err := mcpClient.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	// Test ListTools
	err = ListTools(ctx, session)
	if err != nil {
		t.Errorf("ListTools failed: %v", err)
	}

	// Test CallTool
	err = CallTool(ctx, session, "hello_world")
