{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	// Connect to the server
	cmd := exec.Command("./bin/server")
	transport := &mcp.CommandTransport{Command: cmd}

	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	cs, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer cs.Close()

	if *listTools {
		tools, err := cs.Tools(ctx, nil)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		fmt.Println("tools:")
		for tool, err := range tools {
			if err != nil {
				log.Fatalf("Error during tool iteration: %v", err)
			}
			fmt.Printf("\t%s\n", tool.Name)
		}
	}

	if *callTool != "" {
		result, err := cs.CallTool(ctx, &mcp.CallToolRequest{
			Params: struct {
				Name string `json:"name"`
			}{Name: *callTool},
		}, nil)
		// Wait, CallTool takes *mcp.CallToolRequest
		// Actually, CallToolRequest has Name field and Arguments.
		// Let me check the CallToolRequest struct definition in the SDK.
	}
}
