{"content":"package main

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldTool(t *testing.T) {
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "test-server",
		Version: "1.0.0",
	}, nil)

	type emptyArgs struct{}

	mcp.AddTool(server, &mcp.Tool{
		Name:        "hello_world",
		Description: "Returns a hello world message",
	}, func(ctx context.Context, req *mcp.CallToolRequest, args emptyArgs) (*mcp.CallToolResult, any, error) {
		return &mcp.CallToolResult{
			Content: []mcp.Content{
				&mcp.TextContent{
					Text: "Hello, MCP World!",
				},
			},
		}, nil, nil
	})

	// We can't easily call the handler directly because AddTool hides it.
	// But we can use the server's internal mechanisms if we had access, or just
	// mock a connection.
    // Actually, AddTool uses server.AddTool which we can't easily access.

    // Let's try to just test the logic by extracting it.
}

func GetHelloWorldResult() *mcp.CallToolResult {
	return &mcp.CallToolResult{
		Content: []mcp.Content{
			&mcp.TextContent{
				Text: "Hello, MCP World!",
			},
		},
	}
}

func TestGetHelloWorldResult(t *testing.T) {
	res := GetHelloWorldResult()
	if len(res.Content) != 1 {
		t.Fatalf("expected 1 content, got %d", len(res.Content))
	}
	text, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatal("expected TextContent")
	}
	if text.Text != "Hello, MCP World!" {
		t.Errorf("expected 'Hello, MCP World!', got %q", text.Text)
	}
}
