{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type HelloClient struct {
	client  *mcp.Client
	session *mcp.ClientSession
}

func NewHelloClient() *HelloClient {
	c := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)
	return &HelloClient{client: c}
}

func (c *HelloClient) Connect(ctx context.Context, serverPath string) error {
	transport := &mcp.CommandTransport{
		Command: exec.CommandContext(ctx, serverPath),
	}

	session, err := c.client.Connect(ctx, transport, nil)
	if err != nil {
		return err
	}
	c.session = session
	return nil
}

func (c *HelloClient) Close() error {
	if c.session != nil {
		return c.session.Close()
	}
	return nil
}

func (c *HelloClient) ListTools(ctx context.Context) ([]string, error) {
	tools, err := c.session.ListTools(ctx, nil)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, tool := range tools.Tools {
		names = append(names, tool.Name)
	}
	return names, nil
}

func (c *HelloClient) CallTool(ctx context.Context, name string) ([]string, error) {
	result, err := c.session.CallTool(ctx, &mcp.CallToolParams{
		Name: name,
	})
	if err != nil {
		return nil, err
	}

	var outputs []string
	for _, content := range result.Content {
		if textPtr, ok := content.(*mcp.TextContent); ok {
			outputs = append(outputs, textPtr.Text)
		}
	}
	return outputs, nil
}
","filename":"internal/client/client.go"}

