{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"

	"github.com/petruzalek/mcp-hello-world/internal/client"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	c := client.NewHelloClient()

	if err := c.Connect(ctx, *serverPath); err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer c.Close()

	if *listTools {
		names, err := c.ListTools(ctx)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, name := range names {
			fmt.Println(name)
		}
	}

	if *callTool != "" {
		outputs, err := c.CallTool(ctx, *callTool)
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		for _, output := range outputs {
			fmt.Println(output)
		}
	}
}
","filename":"cmd/client/main.go"}

