{"content":"package client

import (
	"context"
	"fmt"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type Client struct {
	mcpClient *mcp.Client
}

func NewClient() *Client {
	return &Client{
		mcpClient: mcp.NewClient(&mcp.Implementation{
			Name:    "hello-client",
			Version: "1.0.0",
		}, nil),
	}
}

func (c *Client) Run(ctx context.Context, serverPath string, listTools bool, callTool string) error {
	cmd := exec.Command(serverPath)
	transport := &mcp.CommandTransport{Command: cmd}

	cs, err := c.mcpClient.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer cs.Close()

	if listTools {
		tools := cs.Tools(ctx, nil)
		fmt.Println("tools:")
		for tool, err := range tools {
			if err != nil {
				return fmt.Errorf("error during tool iteration: %w", err)
			}
			fmt.Printf("\t%s\n", tool.Name)
		}
	}

	if callTool != "" {
		result, err := cs.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			return fmt.Errorf("failed to call tool: %w", err)
		}

		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}

	return nil
}
