{"content":"package integration

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/petruzalek/mcp-hello-world/internal/client"
	"github.com/petruzalek/mcp-hello-world/internal/server"
)

func TestIntegration(t *testing.T) {
	ctx := context.Background()

	s := server.NewHelloServer()
	c := client.NewHelloClient()

	t1, t2 := mcp.NewInMemoryTransports()

	// Connect server to transport t1
	go func() {
		if _, err := s.Connect(ctx, t1, nil); err != nil {
			// In a test, we can't easily return error from goroutine but we can log
		}
	}()

	// Connect client to transport t2
	if err := c.ConnectWithTransport(ctx, t2); err != nil {
		t.Fatalf("failed to connect: %v", err)
	}
	defer c.Close()

	// Test ListTools
	names, err := c.ListTools(ctx)
	if err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}

	found := false
	for _, name := range names {
		if name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Error("hello_world tool not found")
	}

	// Test CallTool
	outputs, err := c.CallTool(ctx, "hello_world")
	if err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}

	if len(outputs) != 1 || outputs[0] != "Hello, MCP World!" {
		t.Errorf("unexpected output: %v", outputs)
	}
}
