{"content":"package server

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestNewHelloServer(t *testing.T) {
	s := NewHelloServer()
	if s == nil {
		t.Fatal("expected non-nil server")
	}
}

func TestHelloServer_Interaction(t *testing.T) {
	s := NewHelloServer()
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	clientTransport, serverTransport := mcp.InMemoryTransport()

	go func() {
		if err := s.Run(ctx, serverTransport); err != nil {
			// ignore error on cancel
		}
	}()

	client := mcp.NewClient(&mcp.Implementation{Name: "test", Version: "1.0.0"}, nil)
	session, err := client.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("failed to connect: %v", err)
	}
	defer session.Close()

	// List tools
	tools := session.Tools(ctx, nil)
	found := false
	for tool, err := range tools {
		if err != nil {
			t.Fatalf("error listing tools: %v", err)
		}
		if tool.Name == "hello_world" {
			found = true
		}
	}
	if !found {
		t.Error("tool 'hello_world' not found")
	}

	// Call tool
	res, err := session.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("failed to call tool: %v", err)
	}

	if len(res.Content) == 0 {
		t.Fatal("expected content in result")
	}
	text, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatal("expected text content")
	}
	if text.Text != "Hello, MCP World!" {
		t.Errorf("expected 'Hello, MCP World!', got %q", text.Text)
	}
}
