func TestConnect(t *testing.T) {
	// Create a dummy server script
	script := "exit 0"
	tmpfile, err := os.CreateTemp("", "dummy_server")
	if err != nil {
		t.Fatal(err)
	}
	defer os.Remove(tmpfile.Name())

	if _, err := tmpfile.Write([]byte(script)); err != nil {
