	if err := os.Chmod(tmpfile.Name(), 0755); err != nil {
		t.Fatal(err)
	}

	c := NewHelloClient()
	ctx := context.Background()

	// This will fail to connect properly because it's not a real MCP server,
	// but it should cover the Connect function statements until the ConnectWithTransport call.
	_ = c.Connect(ctx, tmpfile.Name())
	c.Close()
