	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-hello-world/internal/client"
	"mcp-hello-world/internal/server"
)

func TestIntegration(t *testing.T) {
	ctx := context.Background()

	// Setup server and client with in-memory pipes
	serverReader, clientWriter := io.Pipe()
	clientReader, serverWriter := io.Pipe()

	serverTransport := &mcp.PipeTransport{
		Reader: serverReader,
		Writer: serverWriter,
	}
	clientTransport := &mcp.PipeTransport{
		Reader: clientReader,
		Writer: clientWriter,
	}

	s := server.NewHelloServer()
	go func() {
		if err := s.Run(ctx, serverTransport); err != nil {
			// May happen on close
		}
	}()

	c := mcp.NewClient(&mcp.Implementation{Name: "test-client", Version: "1.0.0"}, nil)
	session, err := c.Connect(ctx, clientTransport, nil)
	if err != nil {
		t.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	// Test ListTools
	var out bytes.Buffer
	if err := client.ListTools(ctx, session, &out); err != nil {
		t.Fatalf("ListTools failed: %v", err)
	}
	if !bytes.Contains(out.Bytes(), []byte("hello_world")) {
		t.Errorf("Expected output to contain hello_world, got %q", out.String())
	}

	// Test CallTool
	out.Reset()
	if err := client.CallTool(ctx, session, "hello_world", &out); err != nil {
		t.Fatalf("CallTool failed: %v", err)
	}
	if !bytes.Contains(out.Bytes(), []byte("Hello, MCP World!")) {
		t.Errorf("Expected output to contain Hello, MCP World!, got %q", out.String())
	}
}
