	}

	// Re-connect for calling tool (since Run closes the connection)
	clientTransport2, serverTransport2 := mcp.NewInMemoryTransports()
	go func() {
		if err := s.Run(ctx, serverTransport2); err != nil {
			// ignore
		}
	}()
	err = c.Run(ctx, clientTransport2, false, "hello_world")
	if err != nil {
		t.Fatalf("Run(callTool=hello_world) failed: %v", err)
	}
}
