{"content":"package main

import (
	"context"
	"flag"
	"log"
	"os"

	"mcp-hello-world/internal/client"
)

func main() {
	opts := client.RunOptions{
		Stdout: os.Stdout,
		Stderr: os.Stderr,
	}
	flag.BoolVar(&opts.ListTools, "list-tools", false, "List available tools")
	flag.StringVar(&opts.CallTool, "call-tool", "", "Call a tool by name")
	flag.StringVar(&opts.ServerPath, "server-path", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !opts.ListTools && opts.CallTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	if err := client.RunClient(context.Background(), opts); err != nil {
		log.Fatal(err)
	}
}
