{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	// In a real scenario, the server path might be configurable.
	// For this task, we assume ./bin/server exists or we use go run.
	// But the requirement is to build it as ./bin/server.
	serverPath := "./bin/server"
	if _, err := os.Stat(serverPath); os.IsNotExist(err) {
		// Fallback for development if not built yet
		serverPath = "go run ./cmd/server/main.go"
		transport := &mcp.CommandTransport{
			Command: exec.Command("go", "run", "./cmd/server/main.go"),
		}
		runClient(ctx, client, transport, *listTools, *callTool)
	} else {
		transport := &mcp.CommandTransport{
			Command: exec.Command(serverPath),
		}
		runClient(ctx, client, transport, *listTools, *callTool)
	}
}

func runClient(ctx context.Context, client *mcp.Client, transport mcp.Transport, listTools bool, callTool string) {
	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer session.Close()

	if listTools {
		tools, err := session.ListTools(ctx, nil)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, tool := range tools.Tools {
			fmt.Println(tool.Name)
		}
	}

	if callTool != "" {
		res, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: callTool,
		})
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		for _, content := range res.Content {
			if text, ok := content.(mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
}
","filename":"cmd/client/main.go"}

{"content":"package client

import (
	"context"
	"fmt"
	"io"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

type RunOptions struct {
	ListTools  bool
	CallTool   string
	ServerPath string
	Stdout     io.Writer
	Stderr     io.Writer
	Transport  mcp.Transport // Optional, if nil, CommandTransport is used with ServerPath
}

func RunClient(ctx context.Context, opts RunOptions) error {
	transport := opts.Transport
	if transport == nil {
		cmd := exec.Command(opts.ServerPath)
		cmd.Stderr = opts.Stderr
		transport = &mcp.CommandTransport{Command: cmd}
	}

	c := mcp.NewClient(
		&mcp.Implementation{
			Name:    "hello-mcp-client",
			Version: "1.0.0",
		},
		nil,
	)

	session, err := c.Connect(ctx, transport, nil)
	if err != nil {
		return fmt.Errorf("failed to connect to server: %w", err)
	}
	defer session.Close()

	if opts.ListTools {
		if err := ListTools(ctx, session, opts.Stdout); err != nil {
			return err
		}
	}

	if opts.CallTool != "" {
		if err := CallTool(ctx, session, opts.CallTool, opts.Stdout); err != nil {
			return err
		}
	}

	return nil
}
","file_path":"internal/client/app.go"}

{"content":"package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func main() {
	listTools := flag.Bool("list-tools", false, "List available tools")
	callTool := flag.String("call-tool", "", "Call a tool by name")
	serverPath := flag.String("server", "./bin/server", "Path to the server binary")
	flag.Parse()

	if !*listTools && *callTool == "" {
		flag.Usage()
		os.Exit(1)
	}

	ctx := context.Background()
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	transport := &mcp.CommandTransport{
		Command: exec.Command(*serverPath),
	}

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		log.Fatalf("Failed to connect to server: %v", err)
	}
	defer session.Close()

	if *listTools {
		result, err := session.ListTools(ctx, nil)
		if err != nil {
			log.Fatalf("Failed to list tools: %v", err)
		}
		for _, tool := range result.Tools {
			fmt.Println(tool.Name)
		}
	}

	if *callTool != "" {
		result, err := session.CallTool(ctx, &mcp.CallToolParams{
			Name: *callTool,
		})
		if err != nil {
			log.Fatalf("Failed to call tool: %v", err)
		}
		for _, content := range result.Content {
			if text, ok := content.(*mcp.TextContent); ok {
				fmt.Println(text.Text)
			}
		}
	}
}
