func TestIntegration(t *testing.T) {
	ctx := context.Background()

	// Setup server and client with in-memory transports
	serverTransport, clientTransport := mcp.NewInMemoryTransports()

	go func() {
		if err := server.RunServer(ctx, serverTransport); err != nil {
			// May happen on close
		}
	}()

	// Test RunClient with ListTools
	var out bytes.Buffer
	opts := client.RunOptions{
		ListTools: true,
		Stdout:    &out,
		Transport: clientTransport,
	}
	if err := client.RunClient(ctx, opts); err != nil {
		t.Fatalf("RunClient ListTools failed: %v", err)
	}
	if !bytes.Contains(out.Bytes(), []byte("hello_world")) {
		t.Errorf("Expected output to contain hello_world, got %q", out.String())
	}

	// For the second call, we need new transports because the session was closed
	serverTransport, clientTransport = mcp.NewInMemoryTransports()
	go func() {
		if err := server.RunServer(ctx, serverTransport); err != nil {
		}
	}()

	// Test RunClient with CallTool
	out.Reset()
	opts = client.RunOptions{
		CallTool:  "hello_world",
		Stdout:    &out,
		Transport: clientTransport,
	}
	if err := client.RunClient(ctx, opts); err != nil {
		t.Fatalf("RunClient CallTool failed: %v", err)
	}
	if !bytes.Contains(out.Bytes(), []byte("Hello, MCP World!")) {
		t.Errorf("Expected output to contain Hello, MCP World!, got %q", out.String())
	}
}
