import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-example/pkg/hello"
)

func TestClientApp(t *testing.T) {
	ctx := context.Background()
	server := mcp.NewServer(&mcp.Implementation{Name: "test", Version: "1.0"}, nil)
	mcp.AddTool(server, &mcp.Tool{Name: "hello_world"}, hello.HelloWorld)

	client := mcp.NewClient(&mcp.Implementation{Name: "test", Version: "1.0"}, nil)
	t1, t2 := mcp.NewInMemoryTransports()

	if _, err := server.Connect(ctx, t1, nil); err != nil {
		t.Fatal(err)
	}
	session, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer session.Close()

	t.Run("ListTools", func(t *testing.T) {
		if err := ListTools(ctx, session); err != nil {
			t.Errorf("ListTools failed: %v", err)
		}
	})

	t.Run("CallTool", func(t *testing.T) {
		if err := CallTool(ctx, session, "hello_world"); err != nil {
			t.Errorf("CallTool failed: %v", err)
		}
	})

	t.Run("CallToolNonExistent", func(t *testing.T) {
		if err := CallTool(ctx, session, "non_existent"); err == nil {
			t.Error("expected error for non-existent tool, got nil")
		}
	})
}
