{"content":"package hello

import (
	"context"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

func TestHelloWorldHandler(t *testing.T) {
	ctx := context.Background()
	res, _, err := HelloWorldHandler(ctx, nil, nil)
	if err != nil {
		t.Fatalf("HelloWorldHandler returned error: %v", err)
	}

	if len(res.Content) != 1 {
		t.Fatalf("Expected 1 content, got %d", len(res.Content))
	}

	textContent, ok := res.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("Expected TextContent, got %T", res.Content[0])
	}

	if textContent.Text != "Hello, MCP World!" {
		t.Errorf("Expected 'Hello, MCP World!', got '%s'", textContent.Text)
	}
}

func TestRegisterHelloWorld(t *testing.T) {
	server := mcp.NewServer(&mcp.Implementation{Name: "test"}, nil)
	RegisterHelloWorld(server)
	// AddTool doesn't expose a way to check registered tools easily in Server type without session,
	// but we can at least ensure it doesn't panic.
}
