import (
	"context"
	"strings"
	"testing"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"mcp-hello-world/internal/hello"
)

func TestIntegration(t *testing.T) {
	ctx := context.Background()

	// Setup server
	server := mcp.NewServer(&mcp.Implementation{
		Name:    "hello-server",
		Version: "1.0.0",
	}, nil)
	hello.RegisterHelloWorld(server)

	// Setup client
	client := mcp.NewClient(&mcp.Implementation{
		Name:    "hello-client",
		Version: "1.0.0",
	}, nil)

	t1, t2 := mcp.NewInMemoryTransports()

	// Connect server
	serverSession, err := server.Connect(ctx, t1, nil)
	if err != nil {
		t.Fatalf("failed to connect server: %v", err)
	}
	defer serverSession.Close()

	// Connect client
	clientSession, err := client.Connect(ctx, t2, nil)
	if err != nil {
		t.Fatalf("failed to connect client: %v", err)
	}
	defer clientSession.Close()

	// Test ListTools
	toolsResult, err := clientSession.ListTools(ctx, nil)
	if err != nil {
		t.Fatalf("failed to list tools: %v", err)
	}

	found := false
	for _, tool := range toolsResult.Tools {
		if tool.Name == "hello_world" {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("hello_world tool not found in list")
	}

	// Test CallTool
	callResult, err := clientSession.CallTool(ctx, &mcp.CallToolParams{
		Name: "hello_world",
	})
	if err != nil {
		t.Fatalf("failed to call tool: %v", err)
	}

	if len(callResult.Content) != 1 {
		t.Fatalf("expected 1 content, got %d", len(callResult.Content))
	}

	textContent, ok := callResult.Content[0].(*mcp.TextContent)
	if !ok {
		t.Fatalf("expected TextContent, got %T", callResult.Content[0])
	}

	if !strings.Contains(textContent.Text, "Hello, MCP World!") {
		t.Errorf("expected text to contain 'Hello, MCP World!', got '%s'", textContent.Text)
	}
}
","filename":"cmd/client/client_test.go"}

