func TestClientApp(t *testing.T) {
	ctx := context.Background()
	s := server.NewHelloWorldServer()

	t1, t2 := mcp.NewInMemoryTransports()

	// Start server in background
	go func() {
		_, _ = s.Connect(ctx, t1, nil)
	}()

	var buf bytes.Buffer
	app := NewClientApp(&buf)

	// Test ListTools
	err := app.Run(ctx, t2, true, "")
	if err != nil {
		t.Fatalf("Run failed: %v", err)
	}

	if !strings.Contains(buf.String(), "hello_world") {
		t.Errorf("Expected output to contain hello_world, got %q", buf.String())
	}

	// Test CallTool
	buf.Reset()
	// Need a new transport because Connect closes it or we need to re-connect?
	// Actually t2 is already connected to t1.
	// But app.Run connects and then DEFER session.Close().
	// So we need new transports for the second run if we use Run again.
}

func TestClientApp_CallTool(t *testing.T) {
	ctx := context.Background()
	s := server.NewHelloWorldServer()

	t1, t2 := mcp.NewInMemoryTransports()

	go func() {
		_, _ = s.Connect(ctx, t1, nil)
	}()

	var buf bytes.Buffer
	app := NewClientApp(&buf)

	err := app.Run(ctx, t2, false, "hello_world")
	if err != nil {
		t.Fatalf("Run failed: %v", err)
	}

	expected := "Hello, MCP World!"
	if !strings.Contains(buf.String(), expected) {
		t.Errorf("Expected output to contain %q, got %q", expected, buf.String())
	}
}
