func TestRunClient(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	t1, t2 := mcp.NewInMemoryTransports()

	s := server.NewServer()
	go func() {
		if err := s.Run(ctx, t1); err != nil && err != context.Canceled {
			// t.Errorf here might not be thread safe depending on go version, but typically fine in simple tests
		}
	}()

	var out bytes.Buffer

	// Test ListTools
	err := RunClient(ctx, t2, true, "", &out)
	if err != nil {
		t.Fatalf("RunClient failed for list-tools: %v", err)
	}
	if !strings.Contains(out.String(), "hello_world") {
		t.Errorf("expected output to contain 'hello_world', got '%s'", out.String())
	}

	out.Reset()

	// Test CallTool
	err = RunClient(ctx, t2, false, "hello_world", &out)
	if err != nil {
		t.Fatalf("RunClient failed for call-tool: %v", err)
	}
	if !strings.Contains(out.String(), "Hello, MCP World!") {
		t.Errorf("expected output to contain 'Hello, MCP World!', got '%s'", out.String())
	}
}
